def moscow_price_index(at: str = "") -> dict[str, Any]:
    """Коэффициент изменения цен на дату. Пусто — последний известный."""
    rows = sorted(MOSCOW_VRI_PRICE_INDEX, key=lambda row: str(row["effective_from"]))
    moment = str(at or "").strip()
    chosen = None
    for row in rows:
        if not moment or str(row["effective_from"]) <= moment:
            chosen = row
    return dict(chosen or rows[-1])


# --- места постоянного размещения транспортных средств жителей ---------------
# Приложение 5 к 945-ПП в редакции 2118-ПП от 05.08.2026 (текст на руках,
# владелец прислал 20.08.2026). Прежняя наша строка — НП жилая / 90 × К1 — на
# выгрузке давала те же 897 мест, и это было совпадением: у неё другой
# driver (наземная площадь вместо площади квартир) и лишний множитель К1,
# которого в новом порядке нет вовсе. На утверждённом ТЭП различие уже видно —
# 123 места против 130.
_PARKING_2118_HOUSEHOLD = 2.1     # средний размер домовладения, чел.
_PARKING_2118_PER_FLAT = 0.8      # D — мест на одну квартиру
_PARKING_2118_SQM_PER_PERSON = 33.0   # S₁ — площадь квартир на жителя
_PARKING_GUEST_SHARE = 0.1        # гостевые — десятая часть постоянных
# Пункт 2: коэффициенты по полосам площади квартиры и границы полос —
# до 70 м², от 70 до 100, свыше 100.
_PARKING_2118_MIX = {"small": 0.8, "medium": 1.2, "large": 1.6}
_PARKING_2118_BANDS = {"small_max": 70.0, "medium_max": 100.0}
# Те же числа нужны странице: она показывает потребность в местах рядом с ТЭП и
# обязана считать её той же нормой. Копии на странице нет — как у `TEP_RATIOS`
# и `VERSION`, значения подставляются плейсхолдером.
PARKING_2118_PARAMS: dict[str, Any] = {
    "sqm_per_person": _PARKING_2118_SQM_PER_PERSON,
    "household": _PARKING_2118_HOUSEHOLD,
    "per_flat": _PARKING_2118_PER_FLAT,
    "guest_share": _PARKING_GUEST_SHARE,
    # Пункт 2 по средней квартире — те же полосы и коэффициенты, что у движка.
    "mix": dict(_PARKING_2118_MIX),
    "bands": dict(_PARKING_2118_BANDS),
    # Область считается своей нормой (`underground_parking_requirement`),
    # и её числа странице подставляются отсюда же — копии нет.
    "mo": {key: MO_NORMS_DEFAULT[key] for key in (
        "living_space_per_person_sqm", "parking_permanent_per_1000",
        "parking_permanent_share")},
}
PARKING_2118_PLACEHOLDER = "__DEVELOPAID_PARKING_2118__"

# Средняя квартира — делитель, которым площадь превращается в ЧИСЛО квартир, и
# ответ у него разный по источнику (решение владельца, 03.09.2026: «там где мы
# сами вручную собираем, пусть будет 60, там где подгружаем из АПУ — как в АПУ,
# если Подмосковье по кадастру или адресу — РНГП Подмосковья»). Пока делителей
# было четыре и ни один не назывался, на 136 818 м² выходило от 1 974 до 3 800
# квартир, и на экране они выглядели одинаково достоверно.
#
# Норматив Москвы 33 × 2,1 = 69,3 м² остаётся мерой НАСЕЛЕНИЯ — по нему считают
# жителей, соцнагрузку и машино-места. Мерой квартиры он не является: город
# нормирует обеспеченность, а квартиры продаёт рынок.
AVERAGE_FLAT_MANUAL_SQM = 60.0
AVERAGE_FLAT_MO_SQM = round(
    MO_NORMS_DEFAULT["living_space_per_person_sqm"] * _PARKING_2118_HOUSEHOLD, 2)
AVERAGE_FLAT_SOURCES: dict[str, tuple[float, str]] = {
    "manual": (AVERAGE_FLAT_MANUAL_SQM,
               "рынок — 60 м² на квартиру (решение владельца, 03.09.2026)"),
    # РНГП области называет 28 м² на человека и НЕ называет размера
    # домовладения — 2,1 взят из 2118-ПП и назван вслух: подставленное молча
    # число из чужого документа неотличимо от числа этого.
    "mo": (AVERAGE_FLAT_MO_SQM,
           "РНГП Московской области — "
           f"{MO_NORMS_DEFAULT['living_space_per_person_sqm']:g} м² на человека "
           f"при размере домовладения {_PARKING_2118_HOUSEHOLD:g} (2118-ПП)".replace(".", ",")),
}
AVERAGE_FLAT_PLACEHOLDER = "__DEVELOPAID_AVERAGE_FLAT__"


def average_flat_sqm(source: str) -> tuple[float, str]:
    """Средняя квартира и ОСНОВАНИЕ, по которому она взята.

    Выгрузки ГлавАПУ здесь нет намеренно: она приносит готовое число квартир
    (строка 5), и делить её площадь нашим делителем значит дать второй ответ на
    вопрос, на который город уже ответил.
    """
    value, basis = AVERAGE_FLAT_SOURCES.get(
        str(source or "manual"), AVERAGE_FLAT_SOURCES["manual"])
    return value, basis


_PARKING_REGIMES = ("2118_2026", "legacy_945")


def moscow_parking_band(average_flat_sqm: float) -> str:
    """Полоса пункта 2 по площади квартиры: до 70 — малая, до 100 — средняя."""
    avg = float(average_flat_sqm or 0.0)
    if avg < _PARKING_2118_BANDS["small_max"]:
        return "small"
    if avg <= _PARKING_2118_BANDS["medium_max"]:
        return "medium"
    return "large"


def moscow_permanent_parking_by_average(apartment_area_sqm: float,
                                        apartment_count: float) -> tuple[int, str]:
    """Пункт 2 по средней квартире — когда известно число квартир, а состава нет.

    Состав квартир по размерам есть только со стадии АГР; на стадии оценки его
    нет, но средняя квартира меняется вместе с числом квартир, и от неё можно
    плясать (владелец, 04.09.2026). Все квартиры относятся к полосе средней: на
    28 966 м² при 750 квартирах (38,6 м²) это 600 мест, при 419 (69,1 м²) — 336;
    пункт 1 от площади дал бы 335 в обоих случаях, потому что число квартир в
    него не входит. Это оценка, и основание говорит это словами. Без числа
    квартир — пункт 1.
    """
    area = max(0.0, float(apartment_area_sqm or 0.0))
    count = max(0.0, float(apartment_count or 0.0))
    if area <= 0:
        return 0, "площади квартир нет — мест не посчитать"
    if count <= 0:
        return (moscow_permanent_parking_2118(area),
                "приложение 5 к 945-ПП в редакции 2118-ПП, пункт 1: S / (33 × 2,1) × 0,8 "
                "(число квартир не задано)")
    avg = area / count
    band = moscow_parking_band(avg)
    label = {"small": "до 70 м²", "medium": "от 70 до 100 м²", "large": "свыше 100 м²"}[band]
    places = math.ceil(count * _PARKING_2118_MIX[band])
    basis = (f"приложение 5 к 945-ПП в редакции 2118-ПП, пункт 2 по средней квартире "
             f"{avg:.1f} м²: все {int(count)} квартир отнесены к полосе {label} "
             f"× {_PARKING_2118_MIX[band]:g} — оценка, состава квартир до АГР нет")
    return places, basis


def moscow_permanent_parking_2118(apartment_area_sqm: float,
                                  sqm_per_person: float = _PARKING_2118_SQM_PER_PERSON) -> int:
    """Пункт 1: Nп = S / (S₁ × 2,1) × D — для градостроительного проектирования.

    S — площадь квартир; S₁ — площадь квартир на жителя (33 м² по нормативам
    города); D = 0,8 места на квартиру. Округление вверх.
    """
    area = max(0.0, float(apartment_area_sqm or 0.0))
    per_person = float(sqm_per_person or 0.0)
    if area <= 0 or per_person <= 0:
        return 0
    return math.ceil(area / (per_person * _PARKING_2118_HOUSEHOLD) * _PARKING_2118_PER_FLAT)


def moscow_permanent_parking_by_mix(small: float, medium: float, large: float) -> int:
    """Пункт 2: Nп = F₁×0,8 + F₂×1,2 + F₃×1,6 — когда известен состав квартир.

    F₁ — до 70 м², F₂ — от 70 до 100, F₃ — свыше 100 плюс ИЖС и блокированные.
    Это стадия АГР: до неё состава нет, и считают по пункту 1.
    """
    counts = (max(0.0, float(small or 0.0)), max(0.0, float(medium or 0.0)),
              max(0.0, float(large or 0.0)))
    if not any(counts):
        return 0
    return math.ceil(counts[0] * _PARKING_2118_MIX["small"]
                     + counts[1] * _PARKING_2118_MIX["medium"]
                     + counts[2] * _PARKING_2118_MIX["large"])
# `n` и `b` стоят здесь, а не ниже по файлу: строка ТЭП подземного
# паркинга считается ими ПРИ ИМПОРТЕ, когда собирается умолчание, и
# объявление ниже своего читателя дало бы `NameError` на ровном месте.
def n(x: dict, key: str, default: float = 0.0) -> float:
    try:
        value = x.get(key, default)
        return float(default if value in (None, "") else value)
    except (TypeError, ValueError):
        return float(default)


def b(x: dict, key: str) -> bool:
    value = x.get(key, False)
    if isinstance(value, bool):
        return value
    return str(value).lower() in ("1", "true", "да", "yes", "on")


# --- строка ТЭП подземного паркинга ------------------------------------------
def _underground_number(source: dict[str, Any], key: str) -> float:
    try:
        return max(0.0, float(source.get(key) or 0.0))
    except (TypeError, ValueError):
        return 0.0


def underground_area_per_space(inputs: dict[str, Any]) -> float:
    """Норматив площади на машино-место: гросс — рампы и проезды внутри.

    Ноль и пустое значат «умолчание», а не «площади нет»: поле приходит со
    страницы явным нулём, когда его не было в сохранённом проекте.
    """
    fallback = _underground_number(DEFAULT_INPUTS, "underground_area_per_space_sqm")
    return (_underground_number(inputs, "underground_area_per_space_sqm")
            or fallback or 35.0)


def glavapu_apartments_unchanged(normalized: dict[str, Any],
                                 apartment_row: dict[str, Any]) -> bool:
    """Квартиры те же, что у выгрузки ГлавАПУ? Импорт кладёт их в ТЭП как есть.

    Сверяются и площадь, и число квартир: норма считает места по средней
    квартире, и правка одного числа квартир при той же площади меняет её
    («меняю количество квартир до 24 — почему не меняется количество
    машиномест», владелец, «Донской», 07.10.2026).

    Нет площади в выгрузке — сравнить не с чем, и «не меняли» не доказано:
    отсутствие числа не равно совпадению.
    """
    city = _underground_number(normalized or {}, "apartment_area_sqm")
    if city <= 0:
        return False
    same_area = abs(_underground_number(apartment_row or {}, "saleable") - city) < 0.5
    same_count = abs(_underground_number(apartment_row or {}, "units")
                     - _underground_number(normalized or {}, "apartment_units")) < 0.5
    return same_area and same_count


def underground_parking_requirement(inputs: dict[str, Any],
                                    tep: dict[str, dict[str, Any]]) -> dict[str, Any] | None:
    """Потребность в подземных местах: выгрузка города первой, её нет — норма.

    Выгрузка идёт первой потому, что знает приобъектные места нежилья; наша
    норма их не считает и говорит это в основании — К1 и К2 квартала без
    выгрузки неизвестны, а единица «пока не знаем» отдала бы максимум,
    выданный за норматив.
    """
    rows = tep or {}
    per = underground_area_per_space(inputs)
    apartment_row = rows.get("apartments") or {}
    apartments = _underground_number(apartment_row, "saleable")
    normalized = (inputs.get("_glavapu_import") or {}).get("normalized") or {}
    if str(inputs.get("vri_region") or "msk") == "mo":
        # В области норматив мест свой — РНГП МО, и он у движка уже есть
        # (`mo_social_program`): по нему же считаются соцобъекты. 2118-ПП —
        # постановление Москвы, а выгрузка ГлавАПУ — московский орган; в
        # области ни то ни другое потребность не задаёт. Гостевых здесь нет:
        # временные места норматив МО отдаёт жилому району, а не кварталу.
        if apartments <= 0:
            return None
        program = mo_social_program(apartments)
        permanent = float(program["parking"]["permanent_spaces"])
        if permanent <= 0:
            return None
        return {"permanent": permanent, "guest": 0.0, "mfc": 0.0, "spaces": permanent,
                "basis": (f"РНГП Московской области: {program['population']} чел. от "
                          + f"{apartments:,.0f}".replace(",", " ")
                          + " м² квартир, только постоянное хранение"),
                "gns": permanent * per}
    imported_permanent = _underground_number(normalized, "parking_permanent")
    imported_guest = _underground_number(normalized, "parking_guest")
    imported_mfc = _underground_number(normalized, "mfc_parking_spaces")
    if imported_permanent + imported_guest + imported_mfc > 0:
        permanent, guest = imported_permanent, imported_guest
        basis = "норматив ГлавАПУ по нормативному ТЭП"
        if apartments > 0 and not glavapu_apartments_unchanged(normalized, apartment_row):
            # Квартиры правили после выгрузки — места пересчитываются нормой от
            # НОВЫХ квартир: число города посчитано на его же ТЭП. Пока
            # квартиры те же, что у города, его места и остаются (решение
            # владельца 07.10.2026: «числа ГлавАПУ до правки»). Норма — та же,
            # что без выгрузки: пункт 2 по средней квартире, второй формулы нет.
            places, basis = moscow_permanent_parking_by_average(
                apartments, _underground_number(apartment_row, "units"))
            permanent = float(places)
            guest = float(math.ceil(permanent * _PARKING_GUEST_SHARE))
        mfc = imported_mfc
        was_office = _underground_number(normalized, "office_gba_sqm")
        if imported_mfc > 0 and was_office > 0:
            now_office = sum(_underground_number(rows.get(key) or {}, "gns")
                             for key in object_keys_of("offices", "standalone_retail"))
            mfc = float(math.ceil(imported_mfc * now_office / was_office))
        spaces = permanent + guest + mfc
        if spaces <= 0:
            return None
        # Площадь паркинга МФЦ город назвал сам — пересчитывать её нашим
        # нормативом незачем, пока число мест осталось его.
        mfc_area = mfc * per
        if imported_mfc > 0 and mfc == imported_mfc:
            mfc_area = _underground_number(normalized, "mfc_parking_area_sqm") or mfc * per
        return {"permanent": permanent, "guest": guest, "mfc": mfc, "spaces": spaces,
                "basis": basis, "gns": (permanent + guest) * per + mfc_area}
    if apartments <= 0:
        return None
    permanent_places, basis = moscow_permanent_parking_by_average(
        apartments, _underground_number(apartment_row, "units"))
    permanent = float(permanent_places)
    guest = float(math.ceil(permanent * _PARKING_GUEST_SHARE))
    spaces = permanent + guest
    if spaces <= 0:
        return None
    return {"permanent": permanent, "guest": guest, "mfc": 0.0, "spaces": spaces,
            "basis": basis + "; приобъектные места нежилья не учтены",
            "gns": spaces * per}


def underground_parking_by_hand(inputs: dict[str, Any]) -> bool:
    """Пара «места ↔ площадь» подземного паркинга — решение человека?

    Страница сама заполняет пару нормой и помечает это `_parking_by_norm`
    (`fillUndergroundFromTep`): поле непустое, но число — нормы. Движок прежде
    читал всякое непустое поле как ручное, и производные строки (гостевые)
    замирали на прежних вводных. Пометка руки сильнее пометки нормы; проект без
    пометок (до них, API, бот) — непустое поле человеческое.

    От `object_parking_by_hand` отличается одним: проектный подземный посев
    списка `_parking_by_hand` не проходит намеренно, поэтому отсутствие в нём
    ещё не значит «норма».
    """
    key = "underground"
    if key in set(inputs.get("_parking_by_hand") or ()):
        return True
    if key in set(inputs.get("_parking_by_norm") or ()):
        return False
    return True


def underground_tep_row(inputs: dict[str, Any],
                        tep: dict[str, dict[str, Any]]) -> dict[str, float] | None:
    """Строка ТЭП подземного паркинга — производная, и ответ у неё ОДИН.

    Считали её четверо и по-разному. Страница (`repairParkingFromGlavapu`)
    шла по порядку «отказ → руками → выгрузка → норматив»; движок последней
    ступени не имел ВОВСЕ и на проекте без ручных полей и без выгрузки брал
    присланное — на умолчаниях это 1 107,51 места (дробное число мест!) и
    38 763 м² против 1 199 и 41 965 у страницы, а правка норматива 35 → 40 не
    двигала в движке ничего. Книга показывает ФАКТИЧЕСКИЙ норматив (площадь ÷
    места) и потому следует за строкой, а `/v2` пересчитывает пару при правке
    ячейки — обе поверхности верны ровно настолько, насколько верна строка.

    Кладовые площадь гаража НЕ уменьшают — они прибавляют свою (решение
    владельца, 13.09.2026: «конечно они добавляют подземную площадь, иначе на
    машиноместа и хватит просто площадей»). Здесь стоит ровно «места ×
    норматив»: ни один источник не даёт нам этаж целиком — ни выгрузка ГлавАПУ,
    ни ручной шаблон, ни поле «Площадь подземной парковки», которое пара
    «места ↔ площадь» держит на том же нормативе. Вычитание превращало
    норматив 35 м²/место в фактические 33,67 при 400 кладовых по 4 м², то есть
    молча отнимало у гаража метры, которых в нём и не было.

    Возвращает `None`, когда считать не из чего: ни отказа, ни ручных полей,
    ни выгрузки, ни квартир. Тогда строку не трогают — «мы не знаем» не то же
    самое, что «паркинга нет».
    """
    row = (tep or {}).get("underground_parking")
    if not isinstance(row, dict):
        return None
    zero = {"units": 0.0, "gns": 0.0, "total_area": 0.0,
            "useful": 0.0, "saleable": 0.0, "transfer": 0.0}
    if b(inputs, "underground_parking_disabled"):
        # Отказ от подземного паркинга: потребность закрывает наземный гараж.
        # Ноль в поле мест значит «по нормативу», поэтому отказ — свой признак.
        return dict(zero)
    per = underground_area_per_space(inputs)
    manual_spaces = _underground_number(inputs, "underground_manual_spaces")
    manual_area = _underground_number(inputs, "underground_manual_gns_sqm")
    guest: float | None = None
    if underground_parking_by_hand(inputs) and (manual_spaces > 0 or manual_area > 0):
        # Заданная руками площадь сильнее норматива ВСЕГДА, а не только когда
        # мест не назвали: реальный подземный этаж диктуют пятно застройки,
        # рампы и техпомещения, а норматив описывает потребность.
        spaces = manual_spaces if manual_spaces > 0 else (
            round(manual_area / per) if per > 0 else 0.0)
        area = manual_area if manual_area > 0 else spaces * per
        # Гостевые человек не вписывал — они выводятся из его мест тем же
        # правилом, что у читателя (S/11). Оставить в строке прежнее число
        # значит заморозить производное: на «Донском» 44 места несли 109
        # гостевых от давно сменившихся вводных.
        guest = float(underground_guest_spaces({"units": spaces}))
    else:
        need = underground_parking_requirement(inputs, tep)
        if not need:
            return None
        spaces, area, guest = need["spaces"], need["gns"], need["guest"]
    if str(inputs.get("vri_region") or "msk") == "mo":
        # Гостевых мест норматив области в квартале не строит — значит, и
        # заданные руками места все постоянные. Без явного нуля движок
        # вычел бы из них московскую одиннадцатую часть и не продал бы её.
        guest = 0.0
    computed = dict(zero)
    computed["units"] = float(spaces)
    computed["gns"] = round(area, 1)
    computed["total_area"] = computed["gns"]
    if guest is not None:
        # Точное число гостевых известно из самой нормы — выводить его из доли
        # незачем, а потерять значит продать их.
        computed["guest_units"] = guest
    return computed


def apply_underground_tep_row(inputs: dict[str, Any],
                              tep: dict[str, dict[str, Any]]) -> None:
    """Привести строку подземного паркинга к вводным. Правится на месте.

    Объявленную очередью строку не трогаем: её площадь — доля уже посчитанной
    проектной, и повторный вычет кладовых снял бы их дважды.
    """
    row = (tep or {}).get("underground_parking")
    if not isinstance(row, dict) or row.get(TEP_ROW_DECLARED):
        return
    computed = underground_tep_row(inputs, tep)
    if computed:
        row.update(computed)


STORAGE_AREA_PER_UNIT_DEFAULT = 4.3


def storage_area_per_unit(inputs: dict[str, Any]) -> float:
    """Площадь одной кладовой, м². Ноль и пустое значат «умолчание».

    Величина измерена, а не назначена: средняя кладовая в продаже 4,3 м² (ПИК,
    май–июль 2026) и 4,6 (НДВ, 2024), в продаже 2,3–9,8, а СП 4.13130.2013
    изм. 3 ограничивает одну кладовую десятью метрами. Замер накрывает
    масс-сегмент; у бизнеса и элитки своего замера нет, и потому число одно на
    все классы — у кого кладовая крупнее, правит его в профиле своего класса.
    """
    fallback = _underground_number(DEFAULT_INPUTS, "storage_area_per_unit_sqm")
    return (_underground_number(inputs, "storage_area_per_unit_sqm")
            or fallback or STORAGE_AREA_PER_UNIT_DEFAULT)


def storage_tep_row(inputs: dict[str, Any],
                    tep: dict[str, dict[str, Any]]) -> dict[str, float] | None:
    """Строка ТЭП кладовых: штуки и метры — одна величина в двух видах.

    Жили они независимо, и это ровно то, что владелец увидел на экране
    (14.09.2026: «ввёл в ТЭП 800 штук — ничего не изменилось в площади и
    наоборот»). Замер на живых функциях страницы подтвердил дословно: 800 штук
    давали 0 м², 8 000 м² давали 0 штук. Цена обеих половин посчитана на
    умолчаниях: 800 кладовых без метров это +989,1 млн ₽ выручки и ноль СМР
    (LLCR 0,9656 → 0,9893) — товар из воздуха; 8 000 м² без штук это +1 169,9
    млн ₽ CAPEX и ноль выручки (0,9333) — стройка без товара. Верная пара
    (800 × 4,3 = 3 440 м²) даёт 0,9750, то есть настоящий ответ лежит между
    двумя молчаливыми ошибками, и ни одна из них ошибкой не выглядит.

    Ведущее — ШТУКИ: продаётся кладовая, а не её метр, и норматив меняют,
    когда меняется представление о самой кладовой. Заданная руками площадь
    сильнее норматива — то же правило, что у подземного паркинга: реальный
    этаж диктует пятно застройки, а не норматив.

    Нормы «сколько кладовых на дом» не существует ни у города, ни у нас,
    поэтому пустая строка остаётся пустой: сколько их строить — решение
    проекта, и выдуманный норматив потребности построил бы товар, которого
    никто не заказывал.
    """
    row = (tep or {}).get("storage")
    if not isinstance(row, dict):
        return None
    per = storage_area_per_unit(inputs)
    units = _underground_number(row, "units")
    area = _underground_number(row, "gns")
    if units <= 0 and area <= 0:
        return None
    if units > 0 and area > 0:
        # Заданы оба — это решение человека, и трогать его нечем: фактический
        # норматив (площадь ÷ штуки) виден в подписи строки, как у соцобъектов
        # в режиме «Требование КРТ».
        return None
    # Кладовая неделима: 833⅓ штуки не продаются и не строятся. Живой импорт
    # такие числа приносит — он сам считает их из площади (на Мытищах 833,3333
    # при 5 555,6 м² общей), — и пока метров у строки не было, дробь никому не
    # мешала. С парой она мешает сразу: по очередям штуки раздаются целыми
    # (`_integer_phase_allocations`), их сумма становится 833, а метры едут
    # долей от 833⅓ — сумма очередей выходит 3 581,87 против 3 583,3 у
    # участка. Округляем ЗДЕСЬ, у единственного места, где пара считается:
    # округление в раздаче лечило бы следствие, а дробная кладовая осталась бы
    # в отчёте и в выручке.
    units = float(round(units))
    if units > 0:
        area = round(units * per, 1)
    else:
        units = float(round(area / per)) if per > 0 else 0.0
    computed = {"units": units, "gns": round(area, 1)}
    computed["total_area"] = computed["gns"]
    return computed


def apply_storage_tep_row(inputs: dict[str, Any],
                          tep: dict[str, dict[str, Any]]) -> None:
    """Привести строку кладовых к паре. Правится на месте.

    Объявленную очередью строку не трогаем: её метры и штуки — доля уже
    посчитанной проектной пары, и второй пересчёт развёл бы сумму очередей с
    проектом.
    """
    row = (tep or {}).get("storage")
    if not isinstance(row, dict) or row.get(TEP_ROW_DECLARED):
        return
    computed = storage_tep_row(inputs, tep)
    if computed:
        row.update(computed)


# Умолчание строки считается тем же ответом, а не пишется литералом: копию
# негде обновлять, потому что копии нет. Прежний литерал нёс 1 107,5142857
# места — дробное число мест, которых не строят, — и 38 763 м², то есть ответ
# ещё одной, пятой методики.
if "underground_parking" in TEP_DEFAULT:
    _underground_default = underground_tep_row(DEFAULT_INPUTS, TEP_DEFAULT)
    if _underground_default:
        TEP_DEFAULT["underground_parking"].update(_underground_default)
    del _underground_default


# Делители платы за смену ВРИ по праву на участок — из формулы калькулятора
# (класс Df): собственность 1,00001, аренда жилья 1,001. Разница 0,099%, но
# платят при обоих правах, и отказ вместо расчёта показывал бы ноль там, где
# деньги есть.
_VRI_RIGHT_DIVISOR: dict[str, float] = {"ownership": 1.00001, "lease": 1.001}


def recalculate_from_glavapu_baseline(baseline: dict[str, Any],
                                      areas: dict[str, Any]) -> dict[str, Any]:
    """Пересчёт по параметрам исходного расчёта ГлавАПУ.

    Второй калькулятор строить не нужно: территория уже посчитана, и при правке
    ТЭП меняется только количественная база. Кадастровый квартал, К1, зона,
    коэффициент аренды, базовые стоимости и УПКС остаются теми же — значит
    ставки территории можно снять с самой выгрузки и применить к новым метрам
    (решение владельца, 20.08.2026).

    Так надёжнее зашитых констант: у ставок, снятых с базы, нет срока годности —
    новая выгрузка приносит новые. Наши УУПСС дали компенсацию 486,9 млн там,
    где ставки выгрузки дают 497,0.

    Метод проверяет сам себя: применённый к ИСХОДНОМУ ТЭП, он обязан
    воспроизвести числа ГлавАПУ. Не воспроизводит — результат не показывается
    как расчёт, а называется расхождением с базой.
    """
    def num(source: dict[str, Any], key: str) -> float:
        try:
            return max(0.0, float(source.get(key) or 0.0))
        except (TypeError, ValueError):
            return 0.0

    base_res_spp = num(baseline, "residential_spp_sqm")
    base_built_in_spp = num(baseline, "ground_commercial_spp_sqm")
    base_vri_spp = base_res_spp + base_built_in_spp
    base_res_np = num(baseline, "residential_np_sqm")
    base_built_in_np = num(baseline, "ground_commercial_np_sqm")
    base_apartments = num(baseline, "apartment_area_sqm")

    warnings: list[str] = []
    rates: dict[str, Any] = {}

    # --- ставки территории, снятые с базы --------------------------------
    vri_base = num(baseline, "change_vri_mln")
    vri_rate = vri_base / base_vri_spp if base_vri_spp > 0 else 0.0
    if vri_rate <= 0:
        warnings.append("в исходном расчёте нет платы за ВРИ — ставку снять не с чего")
    rates["vri_mln_per_sqm"] = vri_rate

    social_rates: dict[str, float] = {}
    for key, money_key, places_key in (
            ("kindergarten", "social_compensation_kindergarten_mln", "required_kindergarten_places"),
            ("school", "social_compensation_school_mln", "required_school_places"),
            ("clinic", "social_compensation_clinic_mln", "required_clinic_capacity")):
        places = num(baseline, places_key)
        money = num(baseline, money_key)
        social_rates[key] = money / places if places > 0 else 0.0
    rates["social_mln_per_place"] = social_rates
    if not any(social_rates.values()):
        warnings.append("в исходном расчёте нет компенсации за соцобъекты — ставки снять не с чего")

    permanent_rate = (num(baseline, "parking_permanent") / base_res_np
                      if base_res_np > 0 else 0.0)
    attached_rate = (num(baseline, "parking_attached") / base_built_in_np
                     if base_built_in_np > 0 else 0.0)
    rates["parking_permanent_per_sqm"] = permanent_rate
    rates["parking_attached_per_sqm"] = attached_rate

    # --- новые метры -----------------------------------------------------
    apartments = num(areas, "apartment_area_sqm")
    res_spp = num(areas, "residential_living_spp_sqm")
    built_in_spp = num(areas, "ground_commercial_spp_sqm")
    nonres_np = num(areas, "nonresidential_np_sqm")
    nonres_by_use = {str(key): max(0.0, float(value or 0.0))
                     for key, value in (areas.get("nonres_spp_by_use") or {}).items()}

    # --- население и соцпотребность --------------------------------------
    # Пропорцией население не считают: округления вверх идут на каждом шаге.
    zone_two = bool(areas.get("zone_two") or baseline.get("calculation_zone") == "2")
    norms = tep_derived_norms(
        apartment_area_sqm=apartments, residential_living_spp_sqm=res_spp,
        nonresidential_np_sqm=nonres_np, k1=1.0, k2=1.0, zone_two=zone_two)
    places = {"kindergarten": norms["kindergarten_places"],
              "school": norms["school_places"],
              "clinic": norms["clinic_capacity"]}
    compensation = {key: round(social_rates.get(key, 0.0) * count, 3)
                    for key, count in places.items()}

    # --- машино-места ----------------------------------------------------
    # К1 и К2 в ставках уже сидят: они сняты с базы, где город их применил.
    regime = str(areas.get("parking_norm_regime") or "2118_2026")
    if regime not in _PARKING_REGIMES:
        regime = "2118_2026"
        warnings.append("неизвестный режим норматива парковки — считаю по 2118-ПП")
    flats = areas.get("apartment_mix") or {}
    if regime == "legacy_945":
        # Переходные положения 2118-ПП (п. 2.1): объекты с разрешением на
        # строительство, свидетельством АГР, одобренной 3D-моделью на 05.08.2026
        # или вводом до 01.01.2028 считаются по прежней редакции. Определять это
        # «примерно по дате» нельзя — режим задаётся явно.
        permanent = math.ceil(res_spp * 0.9 * permanent_rate) if res_spp and permanent_rate else 0
        parking_basis = "прежняя редакция 945-ПП: ставка исходного расчёта на метр НП жилой"
    elif any(float(flats.get(key) or 0) for key in ("small", "medium", "large")):
        permanent = moscow_permanent_parking_by_mix(
            flats.get("small"), flats.get("medium"), flats.get("large"))
        parking_basis = ("приложение 5 к 945-ПП в редакции 2118-ПП, пункт 2: "
                         "F₁×0,8 + F₂×1,2 + F₃×1,6 по составу квартир")
    else:
        # Число квартир известно — пункт 2 по средней квартире; нет — пункт 1.
        # На числе квартир самой выгрузки (население / 2,1) средняя равна
        # 69,3 м² — та же полоса и тот же 0,8, что в пункте 1; расходятся они
        # только на округление числа квартир вверх (898 против 897 на базе).
        permanent, parking_basis = moscow_permanent_parking_by_average(
            apartments, float(areas.get("apartment_count") or 0.0))
    guest = math.ceil(permanent / 10.0) if permanent else 0
    # Приобъектные места — по ставке базы от ВСТРОЕННЫХ помещений: ставка снята
    # с их НП (12 мест на 6 867 м²), и растягивать её на отдельно стоящее
    # офисное здание значит выдать 109 мест за посчитанные. У отдельного здания
    # свой паркинг со своим нормативом, и он в проекте отдельным продуктом.
    built_in_np = built_in_spp * 0.9
    attached = (math.ceil(built_in_np * attached_rate)
                if built_in_np and attached_rate else 0)
    standalone_np = max(0.0, nonres_np - built_in_np)
    if standalone_np > 1:
        warnings.append(
            f"приобъектные места посчитаны для встроенных помещений "
            f"({built_in_np:,.0f} м² НП); отдельно стоящие нежилые здания "
            f"({standalone_np:,.0f} м² НП) обеспечиваются своим паркингом и здесь "
            f"не считаются".replace(",", " "))

    # --- плата за ВРИ ----------------------------------------------------
    # Жильё — по ставке базы. Нежилые функции — по той же ставке, поправленной
    # отношением базовых стоимостей: формула линейна, коэффициент аренды и
    # индекс те же, и вводить их руками не надо (вписанные руками 25 вместо
    # 0,1497 дали 238 млрд ₽ платы, 20.08.2026).
    bases = dict((baseline.get("vri_base_costs_by_use") or {}))
    base_mkd = float(bases.get("mkd") or 0.0)
    vri_lines = []
    vri_total = 0.0
    # Плата за смену ВРИ берётся при обоих правах — отличается делитель: у
    # собственности 1,00001, у аренды жилья 1,001 (формула калькулятора, класс
    # Df). Разница 0,099%. Отказывать при аренде было неверно: модель показывала
    # ноль там, где платят (владелец, 20.08.2026).
    land_right = str(areas.get("land_right") or "ownership").strip().lower()
    leased = land_right in ("lease", "аренда", "rent")
    # Ставка снята с расчёта калькулятора, а он считает для собственности.
    right_factor = (_VRI_RIGHT_DIVISOR["ownership"] / _VRI_RIGHT_DIVISOR["lease"]
                    if leased else 1.0)
    if leased:
        warnings.append(
            "право на участок — аренда: ставка снята с расчёта для собственности, "
            "к плате применён делитель аренды 1,001 (разница 0,099%). Повышенная "
            "составляющая первого года по 273-ПП — отдельный платёж, здесь не считается")
    vri_available = True
    residential_payment = vri_rate * (res_spp + built_in_spp) * right_factor
    if residential_payment:
        vri_lines.append({"type": "mkd", "spp_sqm": round(res_spp + built_in_spp, 2),
                          "payment_mln": round(residential_payment, 3),
                          "rate_mln_per_sqm": vri_rate})
        vri_total += residential_payment
    # Отдельно стоящее нежилое здание в плату НЕ идёт (владелец, 20.08.2026:
    # «смену ВРИ калькулятор считает по жилью и нежилью первого этажа; зачем нам
    # считать 65 000 отдельно стоящего здания офисов»). Прежде оно считалось по
    # той же ставке, поправленной отношением базовых стоимостей, и на ТЭП по
    # решению ГЗК давало 3 656 млн ₽ поверх 1 444 млн жилья: плата выходила
    # 5 100 вместо 1 444, и число выглядело посчитанным.
    #
    # Считать его всё же приходится — но отдельно и не в итог: свод норм 593-ПП
    # даёт иному нежилому функциональный коэффициент 0,001, то есть плату почти
    # нулевую, а таблица базовых стоимостей калькулятора несёт для торговли и
    # офисов настоящие числа. Что из этого применит город к отдельному зданию,
    # ни выгрузка, ни свод не решают. Молчать нельзя, приписывать к плате —
    # тоже: строка стоит рядом с суммой и названа справочной.
    standalone_total = 0.0
    for use, spp in sorted(nonres_by_use.items()):
        if spp <= 0:
            continue
        base_cost = bases.get(use)
        if base_cost is None or base_mkd <= 0:
            warnings.append(
                f"{use}: нет базовой стоимости в исходном расчёте — справочную плату "
                f"по этим {spp:,.0f} м² посчитать не из чего".replace(",", " "))
            continue
        rate = (vri_rate * float(base_cost) / base_mkd * right_factor
                if float(base_cost) > 0 else 0.0)
        payment = rate * spp
        standalone_total += payment
        vri_lines.append({"type": use, "spp_sqm": round(spp, 2),
                          "payment_mln": round(payment, 3), "rate_mln_per_sqm": rate,
                          "in_total": False,
                          "note": "отдельно стоящее здание — в плату не включено"})
    if standalone_total > 0:
        warnings.append(
            f"отдельно стоящие нежилые здания в плату за ВРИ не включены "
            f"({standalone_total:,.1f} млн ₽ справочно): город считает смену ВРИ по жилью "
            f"и встроенным помещениям первых этажей. По 593-ПП у иного нежилого "
            f"функциональный коэффициент 0,001 — плата почти нулевая, но применит ли "
            f"город его к отдельному зданию, выгрузка не решает".replace(",", " "))

    # --- самопроверка обратным ходом -------------------------------------
    # Проверять имеет смысл только то, что считается НЕ снятой с базы ставкой:
    # плата за ВРИ и постоянные места по ставке воспроизводят базу тождественно,
    # какой бы база ни была, и такая «проверка» ничего не значит. Настоящие
    # проверки — там, где у нас своя формула против числа города: население по
    # 33 м², места по нормативам зоны и гостевые как десятая часть постоянных.
    self_check: dict[str, Any] = {"checked": [], "mismatch": []}

    def compare(name: str, got: Any, want: Any) -> None:
        self_check["checked"].append({"name": name, "baseline": want, "recalculated": got})
        if want and got != want:
            self_check["mismatch"].append(f"{name}: {got} против {want}")

    # Ставка, снятая с базы, обязана сходиться с формулой города: та же плата
    # считается как 1,8964 × СПП × коэффициент аренды × базовая × индекс /
    # делитель. Есть коэффициент и базовая — считаем и сверяем; расходится
    # больше чем на 2% (индексация квартала) — это не ставка, а ошибка чтения
    # выгрузки, и пропорция на ней даст уверенно неверные деньги.
    base_rent = num(baseline, "rent_coefficient")
    if vri_rate > 0 and base_rent > 0 and base_mkd > 0:
        formula_rate = 1.8964 * base_rent * base_mkd / 1.00001 / 1e6
        drift = abs(vri_rate - formula_rate) / formula_rate
        self_check["checked"].append({
            "name": "ставка ВРИ против формулы города",
            "baseline": round(vri_rate, 6), "recalculated": round(formula_rate, 6),
            "drift_pct": round(drift * 100, 2)})
        if drift > 0.05:
            self_check["mismatch"].append(
                f"ставка ВРИ {vri_rate:.6f} млн/м² расходится с формулой города "
                f"{formula_rate:.6f} на {drift*100:.1f}% — так индексация не дрейфует, "
                f"похоже на ошибку чтения выгрузки")

    if base_apartments > 0:
        compare("население", math.ceil(base_apartments / 33.0), int(num(baseline, "population")))
        base_pop = int(num(baseline, "population"))
        if base_pop:
            base_zone_two = bool(baseline.get("calculation_zone") == "2")
            compare("места ДОО",
                    math.ceil((63 if base_zone_two else 44) * base_pop / 1000),
                    int(num(baseline, "required_kindergarten_places")))
            compare("места школы",
                    math.ceil((124 if base_zone_two else 90) * base_pop / 1000),
                    int(num(baseline, "required_school_places")))
            compare("мощность поликлиники",
                    math.ceil(19 * base_pop / 1000),
                    int(num(baseline, "required_clinic_capacity")))
    base_permanent = int(num(baseline, "parking_permanent"))
    if base_permanent:
        compare("гостевые машино-места", math.ceil(base_permanent / 10.0),
                int(num(baseline, "parking_guest")))
        if regime == "2118_2026" and base_apartments > 0:
            # Настоящая проверка формулы: город посчитал 897 мест на 77 696 м²
            # квартир — ровно столько даёт пункт 1. Разойдётся — значит база
            # считалась по прежней редакции или норматив снова сменился.
            compare("постоянные машино-места",
                    moscow_permanent_parking_2118(base_apartments), base_permanent)
    self_check["matches_baseline"] = not self_check["mismatch"]
    if self_check["mismatch"]:
        warnings.append("пересчёт не воспроизводит исходный расчёт: "
                        + "; ".join(self_check["mismatch"]))

    return {
        "method": "glavapu_baseline_rescale",
        "title": "Пересчёт по параметрам исходного расчёта ГлавАПУ",
        "population": norms["population"],
        "places": places,
        "compensation_mln": round(sum(compensation.values()), 3),
        "compensation_breakdown_mln": compensation,
        "parking": {"permanent": permanent, "guest": guest, "attached": attached,
                    "total": permanent + guest + attached,
                    "regime": regime, "basis": parking_basis},
        "vri_lines": vri_lines,
        "vri_total_mln": round(vri_total, 3),
        "vri_available": vri_available,
        "land_right": land_right,
        "land_right_factor": right_factor,
        "rates": rates,
        "baseline": {
            "vri_mln": round(vri_base, 3),
            "compensation_mln": round(num(baseline, "social_compensation_kindergarten_mln")
                                      + num(baseline, "social_compensation_school_mln")
                                      + num(baseline, "social_compensation_clinic_mln"), 3),
            "parking_total": int(num(baseline, "parking_permanent")
                                 + num(baseline, "parking_guest")
                                 + num(baseline, "parking_attached")),
            "population": int(num(baseline, "population")),
            "places": {"kindergarten": int(num(baseline, "required_kindergarten_places")),
                       "school": int(num(baseline, "required_school_places")),
                       "clinic": int(num(baseline, "required_clinic_capacity"))},
        },
        "self_check": self_check,
        "warnings": warnings,
    }


# Нормативы соцобъектов — мест (посещений в смену) на 1000 жителей по
# расчётной зоне. Один источник: ими считает `tep_derived_norms`, их же сверка
# с калькулятором ГлавАПУ ставит рядом с «Нормативом ДОО / школ» его листа
# «Параметры территории».
SOCIAL_NORMS_PER_1000: dict[str, dict[str, int]] = {
    "kindergarten": {"1": 44, "2": 63},
    "school": {"1": 90, "2": 124},
    "clinic": {"1": 19, "2": 19},
}


def tep_derived_norms(*, apartment_area_sqm: float, residential_living_spp_sqm: float,
                      nonresidential_np_sqm: float = 0.0,
                      k1: float = 1.0, k2: float = 1.0,
                      zone_two: bool = False,
                      upks_rub: float = 0.0,
                      sqm_per_job: float = 32.0,
                      parking_norm_regime: str = "2118_2026",
                      apartment_count: float = 0.0) -> dict[str, Any]:
    """Что следует из введённого руками ТЭП: население, соцпотребность,
    компенсация, машино-места, места приложения труда.

    `apartment_count` — число квартир, если оно известно: тогда постоянные
    места считаются пунктом 2 по средней квартире, иначе пунктом 1 от площади.

    Формулы городские и сверены на выгрузке штатного калькулятора
    (77:01:0004023, 20.08.2026): постоянные места 897, гостевые 90,
    приобъектные 12 — воспроизводятся до единицы.

    `residential_living_spp_sqm` — СПП **жилая** (строка 7.1 выгрузки, у нас
    «ТЭП → Квартиры → ГНС»), без нежилой части жилых зданий. В действующем
    порядке она на постоянные места не влияет вовсе — они считаются от площади
    квартир, — но нужна прежнему режиму и печатается в основании. Плата за ВРИ
    берётся от полной СПП жилых зданий, включая встроенные помещения.

    Постоянные места — приложение 5 к 945-ПП в редакции 2118-ПП: тот же расчёт,
    что и в пересчёте по параметрам исходной выгрузки. Два наших ответа на одни
    метры расходиться не могут: `parking_norm_regime="legacy_945"` возвращает
    прежнюю строку (НП жилая / 90 × К1) — она нужна, чтобы сверяться с
    калькулятором, а не как второе мнение о норме.
    """
    apartments = max(0.0, float(apartment_area_sqm or 0.0))
    residential_spp = max(0.0, float(residential_living_spp_sqm or 0.0))
    nonresidential_np = max(0.0, float(nonresidential_np_sqm or 0.0))
    k1 = max(0.0, float(k1 or 0.0))
    k2 = max(0.0, float(k2 or 0.0))
    upks = max(0.0, float(upks_rub or 0.0))

    population = math.ceil(apartments / 33.0) if apartments > 0 else 0
    zone = "2" if zone_two else "1"
    dou = (math.ceil(SOCIAL_NORMS_PER_1000["kindergarten"][zone] * population / 1000)
           if population else 0)
    school = (math.ceil(SOCIAL_NORMS_PER_1000["school"][zone] * population / 1000)
              if population else 0)
    clinic = (math.ceil(SOCIAL_NORMS_PER_1000["clinic"][zone] * population / 1000)
              if population else 0)

    residential_np = residential_spp * 0.9
    regime = str(parking_norm_regime or "2118_2026").strip().lower()
    if regime not in _PARKING_REGIMES:
        regime = "2118_2026"
    if regime == "2118_2026":
        permanent, parking_basis = moscow_permanent_parking_by_average(
            apartments, apartment_count)
        parking_basis = "постоянные места — " + parking_basis
    else:
        # Прежняя строка города: от НАЗЕМНОЙ ЖИЛОЙ площади (90% жилой СПП), а не
        # от всей СПП жилых зданий — на выгрузке первое даёт 897 мест, второе 954.
        permanent = math.ceil(residential_np / 90.0 * k1) if residential_np and k1 else 0
        parking_basis = ("постоянные места — прежняя строка города: НП жилая / 90 × К1 "
                         f"{k1:g}".replace(".", ",") + " (режим сверки с калькулятором)")
    guest = math.ceil(permanent / 10.0) if permanent else 0
    onsite = math.ceil(nonresidential_np / 90.0 * k1 * k2) if nonresidential_np and k1 and k2 else 0

    def compensation(places: float, uupss_th: float, land_sqm: float, factor: float) -> float:
        if places <= 0 or upks <= 0:
            return 0.0
        return factor * (uupss_th * places / 1000.0 + places * land_sqm * upks / 1e6)

    # Земля на место — по мощности объекта, как у калькулятора: ДОО 35 м² до
    # 150 мест, дальше 32; школа 19 до 900, 16 до 1 500, дальше 14. Мощность
    # поликлиники в компенсации — взрослая (13,2) + детская (5,8) на тысячу:
    # на Нагатино 101 + 45 = 146 при смешанной 145 (выгрузка 06.10.2026).
    clinic_parts = ((math.ceil(13.2 * population / 1000) + math.ceil(5.8 * population / 1000))
                    if population else 0)
    comp_dou = compensation(dou, 4799.71, 35.0 if dou <= 150 else 32.0, 1.2)
    comp_school = compensation(school, 4578.69,
                               19.0 if school <= 900 else 16.0 if school <= 1500 else 14.0, 1.2)
    comp_clinic = compensation(clinic_parts, 7887.92, 30.0, 1.0)
    return {
        "population": population,
        "apartment_units": math.ceil(population / 2.1) if population else 0,
        "kindergarten_places": dou,
        "school_places": school,
        "clinic_capacity": clinic,
        "compensation_mln": round(comp_dou + comp_school + comp_clinic, 3),
        "compensation_breakdown_mln": {
            "kindergarten": round(comp_dou, 3),
            "school": round(comp_school, 3),
            "clinic": round(comp_clinic, 3),
        },
        "parking_permanent": permanent,
        "parking_guest": guest,
        "parking_onsite": onsite,
        "parking_total": permanent + guest + onsite,
        "parking_norm_regime": regime,
        "parking_basis": parking_basis,
        # Места приложения труда — основание льготы по плате за ВРИ (3135-ПП),
        # у калькулятора для неё своя строка 52 «Льгота на стр-во жилья за
        # создание МПТ». Норма — 32 м² НП на место с округлением ВНИЗ, как в
        # коде калькулятора (таблица Q, места по ВРИ — lodash `floor`;
        # 6 867 м² → 214, а к ближайшему вышло бы 215; Нагатино 22 217 м² →
        # 694). У торговли у калькулятора 45 — поэтому делитель параметр и
        # печатается вместе с ответом.
        "jobs": math.floor(nonresidential_np / sqm_per_job) if nonresidential_np and sqm_per_job else 0,
        "sqm_per_job": float(sqm_per_job or 0.0),
        "upks_rub": upks,
        "k1": k1,
        "k2": k2,
        "zone_two": bool(zone_two),
        # Компенсация без УПКС не считается, и ноль здесь означал бы «бесплатно».
        "missing": ([] if upks > 0 or not population
                    else ["УПКС квартала не задан — компенсация не посчитана"]),
    }


# --- нормативная потребность объектов в машино-местах -----------------------
# Норма объявлена один раз, в `parking_norms`. Здесь только сборка: какой
# продукт какой функцией считается, какие метры ему принадлежат и куда его
# места ставит человек.
#
# Правило владельца (24.08.2026): МЕСТА ОБЪЕКТА ПРИНАДЛЕЖАТ ОБЪЕКТУ. Норматив
# порождает объект, а не проект целиком: у офисника в третьей очереди своя
# потребность, у ТЦ во второй — своя. Прибавлять их к общей куче нельзя, потому
# что куча разносится по очередям своими правилами и приезжает не туда.
#
# Куда ставить места — решение владельца 05.09.2026: «у осз должны быть паркинг
# или подземные или наземные напервых этажах». Двух мест ровно два, и общий
# наземный паркинг проекта в них НЕ входит — объекты его больше не наполняют.
#
# НАДЗЕМНЫЙ и НАЗЕМНЫЙ — разные вещи, и различие стоило владельцу отдельной
# поправки («стоп надземные не вычитается, я ошибся, вычитается наземный»).
# Надземный — этажи самого здания: его метры уже внутри ГНС объекта, и ГНС
# не меняется. Наземный — отдельная стоянка (`above_parking`), её метры свои,
# из объекта они вычитаются; в модели у неё своя строка ТЭП и мера «место».
#
# Выбор — ДВА ЧИСЛА, а не переключатель («При выборе парковок надо сделать
# выбор, что идет в надземные и подземные с контролем суммы по обязательствам
# согласном нормам»). Переключатель сумму сводит по построению, и проверять в
# нём нечего; два числа принадлежат человеку и с нормой могут не сойтись —
# ради этого расхождения контроль и написан.
# Имя функции у юрисдикций СВОЁ. У Москвы это код ВРИ (спорт — 5.1), у области
# — строка приложения № 10, и называются они по-разному: «спорт» против
# «оздоровительные комплексы». Одно имя на обе таблицы однажды нашло бы в
# соседней не ту строку — а выглядело бы это как посчитанный норматив.
_PARKING_DEMAND_PRODUCTS = (
    # (ключ ТЭП, функция Москвы, функция области, встроенность)
    ("ground_commercial", "shop", "shop", True),
    ("offices", "office", "office", False),
    ("standalone_retail", "mall", "mall", False),
    ("sports", "sport", "fitness", False),
)
# Второй объект нормируется функцией своего продукта: второй офисник — офис.
_PARKING_DEMAND_PRODUCTS = _PARKING_DEMAND_PRODUCTS + tuple(
    (obj.key, *next(item[1:] for item in _PARKING_DEMAND_PRODUCTS if item[0] == obj.family))
    for obj in STANDALONE_OBJECTS
    if obj.family and any(item[0] == obj.family for item in _PARKING_DEMAND_PRODUCTS))

# Назначение отдельно стоящего объекта «ФОК / медцентр» решает его норматив.
#
# Объект один: двух таких в проекте разом не бывает (владелец, 15.09.2026),
# поэтому вместо пятого объекта у ФОКа появилось назначение. Норматив у них
# РАЗНЫЙ, и это не оттенок: у Москвы спорт — код ВРИ 5.1 (200 м² ННП на место),
# здравоохранение — 3.4 (300 м²), то есть в полтора раза меньше мест. Оставь
# медцентр на спортивном нормативе — и лишние места выглядели бы посчитанными.
#
# У области строки здравоохранения НЕТ ВОВСЕ: приложение № 10 знает только
# оздоровительные комплексы, а п. 5.12 в редакции 774-ПП даёт правило «1 место
# на 50 м² общей площади» для нежилого здания без конкретной функции — оно и
# применяется. Поликлиники это правило исключает прямым текстом, но поликлиника
# города и коммерческий медцентр — разные вещи: первая приходит нормативом
# соцнагрузки, второй строится на продажу. Отнести медцентр к исключению значит
# оставить объект вовсе без норматива; отнести к фитнесу — посчитать по чужой
# строке. Взято правило без функции, и основание это называет.
_SPORTS_PURPOSE_FUNCTIONS = {
    "sport": ("sport", "fitness"),
    "healthcare": ("healthcare", "healthcare"),
}


def sports_parking_functions(inputs: dict[str, Any] | None,
                             purpose_key: str = "sports_purpose") -> tuple[str, str]:
    """Функции норматива для объекта «ФОК / медцентр»: (Москва, область).

    У области строки здравоохранения в таблице нет, и `mo_required` отвечает на
    неё правилом п. 5.12 «1 место на 50 м²», называя это допущением, — своего
    костыля здесь не нужно. Назначение у каждого экземпляра ФОКа своё
    (`purpose_key`).
    """
    purpose = str(((inputs or {}).get(purpose_key) or "sport")).strip().lower()
    return _SPORTS_PURPOSE_FUNCTIONS.get(purpose, _SPORTS_PURPOSE_FUNCTIONS["sport"])



OBJECT_PARKING_AREA_DEFAULT = 35.0
OBJECT_PARKING_OVER_AREA_DEFAULT = 25.0


def standalone_object_saleable(inputs: dict[str, Any], tep: dict[str, Any] | None,
                               key: str) -> float:
    """Продаваемая площадь ОСЗ после пятна мест первых этажей. Ответ один.

    Ровно формула книги v4 (K26/K46/K129 «Расчётная продаваемая площадь»):
    (GBA вводных − места первых этажей × площадь места) × продаваемая / GBA
    вводных. Себестоимость объекта движок и книга берут с той же GBA вводных;
    выручка в движке после #481 читала строку ТЭП, и при ТЭП, пришедшем
    отдельно от вводных (API, бот), продавала 16 575 м² против 5 840 в книге.
    Её же читают строки отчёта: объём «Офисы / МФОЦ» стоял до паркинга, а
    выручка — после, и средняя цена метра выходила ниже назначенной.
    """
    obj = next((item for item in standalone_objects() if item.key == key), None)
    if obj is None or obj.measure == "spaces":
        return 0.0
    base_saleable = max(0.0, n(inputs, f"{obj.prefix}_saleable_sqm"))
    base_gba = max(0.0, n(inputs, f"{obj.prefix}_gba_sqm"))
    if base_gba <= 0:
        return 0.0
    row = (tep or {}).get(key) or {}
    over_gba = max(0.0, n(row, "parking_over_units")) * (
        n(inputs, "object_parking_over_area_per_space_sqm", OBJECT_PARKING_OVER_AREA_DEFAULT)
        or OBJECT_PARKING_OVER_AREA_DEFAULT)
    return max(0.0, base_gba - over_gba) * base_saleable / base_gba


def object_sold_saleable(inputs: dict[str, Any], tep: dict[str, Any] | None,
                         key: str) -> float:
    """Сколько метров объекта ПРОДАЁТСЯ — для структуры продукта, отчёта и сводки.

    Строка ТЭП объекта держит площадь здания: места первых этажей её не
    уменьшают (владелец, 29.09.2026: «оставь в структуре»). Продаётся остаток
    — `standalone_object_saleable`. Строка без продаваемой (объект выключен,
    передан) или объект без вводной ГНС отвечают своей строкой.
    """
    row = (tep or {}).get(key) or {}
    obj = _BY_KEY.get(key)
    if (obj is None or obj.measure == "spaces" or n(row, "saleable") <= 0
            or n(inputs, f"{obj.prefix}_gba_sqm") <= 0):
        return n(row, "saleable")
    return standalone_object_saleable(inputs, tep, key)


def object_parking_by_hand(inputs: dict[str, Any], prefix: str) -> bool:
    """Места гаража объекта заданы человеком? Ответ один на проект и очередь.

    Страница ведёт список тронутых руками (`_parking_by_hand`). Пока он есть,
    объект вне списка — поле заполнила норма, и оно идёт за ТЭП, а не замирает
    на вчерашнем числе. Проект без списка (сохранён до него) — непустое поле
    человеческое. Пометка нормы (`_parking_by_norm`) говорит «её число» прямо.

    Прежде ответов было два: очередь считала ручным всякое непустое поле, а
    проект — по списку, и одни и те же вводные строили разные гаражи в своде и
    в очередях.
    """
    key = str(prefix)
    if key in set(inputs.get("_phase_parking_by_hand") or ()):
        return True
    marks = inputs.get("_parking_by_hand")
    if marks is not None:
        return key in set(marks)
    if key in set(inputs.get("_parking_by_norm") or ()):
        return False
    return any(n(inputs, f"{prefix}_parking_{kind}_spaces") > 0 for kind in ("under", "over"))


# Своё поле площади места гаража объекта удалено (#541): теперь это норматив
# класса. Проекты, сохранённые раньше, несут прежний ключ, и молча терять
# вписанное туда число нельзя — сохранённое состояние накладывается на
# умолчания, а не исчезает. Прежнее умолчание поля было одно на все классы —
# 35 м², — и оно решением человека не считается.
OBJECT_PARKING_AREA_SAVED_KEY = "object_parking_area_per_space_sqm"
OBJECT_PARKING_AREA_OLD_DEFAULT = 35.0


def object_parking_area_saved(inputs: dict[str, Any]) -> dict[str, Any] | None:
    """Число прежнего поля из сохранённого проекта и его судьба.

    `None` — ключа нет, он пуст или совпадает с нормативом класса: сказать
    нечего. Иначе `origin`:
    - `manual` — число вписано руками, оно и действует для гаража объекта;
    - `old_default` — стояло прежнее умолчание 35 м²: действует норматив
      класса, а человеку сказано, что число заменено.
    """
    raw = (inputs or {}).get(OBJECT_PARKING_AREA_SAVED_KEY)
    if raw in (None, "") or isinstance(raw, bool):
        return None
    try:
        value = float(raw)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(value) or value <= 0:
        return None
    norm = underground_area_per_space(inputs) or OBJECT_PARKING_AREA_DEFAULT
    if math.isclose(value, norm, abs_tol=1e-9):
        return None
    origin = ("old_default"
              if math.isclose(value, OBJECT_PARKING_AREA_OLD_DEFAULT, abs_tol=1e-9)
              else "manual")
    return {"value": value, "norm": norm, "origin": origin}


def object_parking_area_per_space(inputs: dict[str, Any]) -> float:
    """Площадь одного подземного места гаража ОСЗ — норматив класса.

    Ответ один на гараж дома и гараж объекта: `underground_area_per_space`.
    Исключение одно — число, вписанное руками в прежнее поле сохранённого
    проекта (`object_parking_area_saved`). Книга пишет в K158 это же число
    (`_V4_DERIVED_INPUTS`).
    """
    saved = object_parking_area_saved(inputs)
    if saved and saved["origin"] == "manual":
        return saved["value"]
    return underground_area_per_space(inputs) or OBJECT_PARKING_AREA_DEFAULT


def _object_parking_area_saved_line(saved: dict[str, Any]) -> str:
    value = _pdf_num(saved["value"], 1).replace(",0", "")
    norm = _pdf_num(saved["norm"], 1).replace(",0", "")
    if saved["origin"] == "manual":
        return (f"площадь подземного места гаража объектов {value} м² — из сохранённого "
                f"проекта, вписана руками; норматив класса {norm} м²")
    return (f"в сохранённом проекте площадь места гаража объектов стояла {value} м² — "
            f"прежнее умолчание; теперь берётся норматив класса {norm} м²")


def apply_object_parking(inputs: dict[str, Any], tep: dict[str, Any]) -> dict[str, Any]:
    """Разместить СОБСТВЕННЫЙ паркинг объектов по строкам ТЭП.

    Подземные места добавляют отдельную подземную площадь объекта. Места на
    первых этажах занимают часть уже существующей наземной ГНС: ГНС объекта
    не растёт и не уменьшается, а общая, полезная и продаваемая площади
    пересчитываются от остатка ГНС в тех же долях, которые были у объекта до
    размещения паркинга.
    """
    # Книга может вызвать расчёт повторно на той же копии ТЭП. Первый проход
    # запоминает исходные площади, а следующий обязан быть идемпотентным.
    # Но ТЭП может быть ПЕРЕСЧИТАН между проходами на той же структуре: прежняя
    # реализация безусловно восстанавливала старый _object_parking_base_* и
    # тем самым отменяла свежий ТЭП. Поэтому рядом с базой держим последнее
    # значение, которое поставили МЫ. Если текущее значение уже отличается от
    # него, это внешнее изменение — оно становится новой базой.
    for tep_key, prefix, _enabled_key, _sellable in OBJECT_PARKING_OBJECTS:
        row = (tep or {}).get(tep_key) or None
        if row is None:
            continue
        # Продаваемая объекта — вводная, а не присланная строка: страница
        # кладёт в свою строку ответ прошлого расчёта, и строка, сохранённая,
        # пока движок вычитал в ней места первых этажей, несёт уже уменьшенное
        # число — следующий расчёт вычитал бы его снова (строка ТЭП 50 709 м²
        # при выручке от 66 613, владелец, 29.09.2026).
        # Строка приводится к вводной одной долей: пропорции общей, полезной и
        # продаваемой у неё свои, и место мест в них не меняет.
        # Строка с другой ГНС — это другой ТЭП (свежий пересчёт, доля очереди),
        # и вводная о ней не говорит: тогда база — сама строка.
        anchor = max(0.0, n(inputs, f"{prefix}_saleable_sqm"))
        sent = n(row, "saleable")
        same_object = math.isclose(n(row, "gns"), n(inputs, f"{prefix}_gba_sqm"),
                                   rel_tol=1e-9, abs_tol=0.05)
        if (same_object and anchor > 0 and sent > 0
                and not math.isclose(anchor, sent, rel_tol=1e-9, abs_tol=1e-6)):
            scale = anchor / sent
            for field in ("total_area", "useful", "saleable"):
                row[field] = n(row, field) * scale
        for field in ("total_area", "useful", "saleable"):
            base_key = f"_object_parking_base_{field}"
            applied_key = f"_object_parking_applied_{field}"
            current = n(row, field)
            if base_key not in row:
                row[base_key] = current
                continue
            applied = row.get(applied_key)
            if applied is not None and not math.isclose(
                    current, float(applied), rel_tol=1e-10, abs_tol=1e-6):
                row[base_key] = current
            else:
                row[field] = n(row, base_key)

    demand = parking_demand(inputs, tep)
    # Площадь подземного места гаража объекта — та же, что у паркинга дома:
    # норматив класса (35 / 37,5 / 40 м²). Своё поле у гаража было второй
    # копией того же числа и при смене класса не двигалось (владелец,
    # 27.09.2026: блок «Нормативы парковки нежилья» во вводных не нужен).
    under_per_space = object_parking_area_per_space(inputs)
    over_per_space = (
        n(inputs, "object_parking_over_area_per_space_sqm", OBJECT_PARKING_OVER_AREA_DEFAULT)
        or OBJECT_PARKING_OVER_AREA_DEFAULT
    )
    required_by_key = {row.get("tep_key"): row.get("required_spaces")
                       for row in (demand.get("rows") or [])
                       if row.get("required_spaces")}
    own: list[dict[str, Any]] = []
    layout_warnings: list[str] = []

    for tep_key, prefix, enabled_key, sellable in OBJECT_PARKING_OBJECTS:
        row = (tep or {}).get(tep_key) or None
        if row is None:
            continue
        enabled = b(inputs, enabled_key)
        under = max(0, int(n(inputs, f"{prefix}_parking_under_spaces"))) if enabled else 0
        over = max(0, int(n(inputs, f"{prefix}_parking_over_spaces"))) if enabled else 0

        by_norm = False
        take_norm = enabled and not object_parking_by_hand(inputs, prefix)
        if take_norm:
            required = int((required_by_key.get(tep_key) or 0))
            if required > 0:
                under, over, by_norm = required, 0, True
            else:
                under, over = 0, 0

        guests = 0
        if sellable and enabled:
            guests = int(round((under + over) * n(inputs, f"{prefix}_parking_guest_pct") / 100.0))
            guests = max(0, min(guests, under + over))

        row["under_gns"] = under * under_per_space
        row["parking_under_units"] = float(under)
        row["parking_over_units"] = float(over)
        row["parking_units"] = float(under + over)
        row["parking_saleable_units"] = (
            float(max(0, under + over - guests)) if sellable else 0.0
        )
        # Гостевые — число движка, а не разность на экране: у ТЦ и ФОКа места
        # не продаются, и «построено − продаётся» называло гостевыми все места.
        # Поле перенесено из ветки Codex fix/object-parking-tep-expense-units.
        row["parking_guest_units"] = float(guests)

        base_gns = max(0.0, n(row, "gns"))
        over_gba = over * over_per_space
        remaining_gba = max(0.0, base_gns - over_gba)
        ratio = (remaining_gba / base_gns) if base_gns > 0 else (1.0 if over_gba <= 0 else 0.0)

        # Строка ТЭП объекта остаётся площадью ЗДАНИЯ: места первых этажей её
        # не уменьшают. Вычет живёт в структуре продукта — продаётся остаток,
        # `standalone_object_saleable`, — и называется здесь числом (владелец,
        # 29.09.2026: «оставь в структуре»). Прежде строка уменьшалась, и
        # ТЭП, продукт и присланная назад строка давали три разных числа.
        losses: dict[str, float] = {}
        for field in ("total_area", "useful", "saleable"):
            base = n(row, f"_object_parking_base_{field}")
            row[field] = base
            row[f"_object_parking_applied_{field}"] = base
            losses[field] = max(0.0, base - max(0.0, base * ratio))
        row["parking_saleable_after_sqm"] = max(0.0, n(row, "saleable") - losses["saleable"])

        overflow = max(0.0, over_gba - base_gns)
        if overflow > 1e-9:
            label = str(row.get("label") or tep_key)
            layout_warnings.append(
                f"{label}: паркинг первых этажей требует {over_gba:,.0f} м² ГНС, "
                f"а у объекта только {base_gns:,.0f} м²; площадь объекта не увеличена"
            )

        row["parking_over_gba_sqm"] = over_gba
        row["parking_layout_overflow_sqm"] = overflow
        row["parking_saleable_taken"] = losses["saleable"]

        own.append({
            "tep_key": tep_key,
            "prefix": prefix,
            "label": row.get("label") or tep_key,
            "enabled": enabled,
            "under_spaces": under,
            "over_spaces": over,
            "units": under + over,
            "guest_spaces": guests,
            "by_norm": by_norm,
            "required_spaces": int(required_by_key.get(tep_key) or 0),
            "sellable": sellable,
            "saleable_units": int(row["parking_saleable_units"]),
            "under_gns": row["under_gns"],
            "over_gba_sqm": over_gba,
            "layout_overflow_sqm": overflow,
            "saleable_taken_sqm": losses["saleable"],
        })

    demand["own"] = own
    demand["own_units"] = sum(item["units"] for item in own if item["enabled"])
    demand["own_saleable_units"] = sum(item["saleable_units"] for item in own if item["enabled"])
    demand["own_under_gns"] = sum(item["under_gns"] for item in own if item["enabled"])
    demand["area_per_space_sqm"] = under_per_space
    demand["over_area_per_space_sqm"] = over_per_space
    # Происхождение площади места — рядом с числом: норматив класса и число
    # из сохранённого проекта на экране выглядят одинаково.
    saved_area = object_parking_area_saved(inputs)
    demand["area_per_space_source"] = (
        "saved_manual" if saved_area and saved_area["origin"] == "manual" else "class_norm")
    demand["area_per_space_saved"] = saved_area
    if saved_area and any(item["under_spaces"] for item in own if item["enabled"]):
        demand.setdefault("assumptions", []).append(_object_parking_area_saved_line(saved_area))
    if layout_warnings:
        demand.setdefault("warnings", []).extend(layout_warnings)
    demand["note"] = _object_parking_note(demand, own)
    return demand

def _object_parking_note(demand: dict[str, Any], own: list[dict[str, Any]]) -> str:
    """Одной фразой: сколько мест положено, сколько строим и сколько продаём.

    Приобъектная парковка по приложению 6 к 945-ПП — это «временное хранение»,
    то есть места ПРИ объекте: под ним или на первых этажах (владелец,
    06.09.2026). Норма ставит число, человек его перебивает — и на экране
    обязано быть видно, чьё оно: «по нормативу» и «задано руками» на одном
    поле выглядят одинаково.
    """
    required = int(demand.get("required_total") or 0)
    live = [item for item in own if item.get("enabled")]
    if not live:
        if demand.get("missing"):
            return ("Норматив приобъектной парковки не посчитан: "
                    + demand["missing"][0].split(": ", 1)[-1] + ".")
        return "Нежилых объектов в проекте нет — приобъектная парковка не требуется."
    built = sum(item["units"] for item in live)
    sold = sum(item["saleable_units"] for item in live)
    parts = []
    for item in live:
        # Чьё число — часть числа. «Задано руками» у нетронутого поля — это
        # утверждение о человеке, сделанное из нашего же нуля: он ничего не
        # вписывал, просто мест не потребовалось.
        if item.get("by_norm"):
            whose = ", по нормативу"
        elif item["units"]:
            whose = ", задано руками"
        elif item.get("required_spaces"):
            whose = f", мест нет — а по нормативу положено {item['required_spaces']}"
        else:
            whose = ", норматив мест не требует"
        line = (f"{item['label']} — {item['units']} мест "
                f"({item['under_spaces']} в подземном, {item['over_spaces']} на первых этажах"
                + whose + ")")
        if not item["sellable"]:
            # «Ты видел ТЦ, где покупатели купили бы места?» — обеспеченность
            # посетителей. Не сказать этого рядом с числом значит показать
            # построенные места там, где читатель ждёт продаваемые.
            line += ", не продаются"
        elif item["guest_spaces"]:
            line += f", из них {item['guest_spaces']} гостевых"
        parts.append(line)
    # Норматив считается и встроенной коммерции МКД, а своего гаража у неё нет.
    # Это приобъектная стоянка у дома — плоскостная парковка или сторона улицы
    # (945-ПП п. 6.1.2.3), и в подземный паркинг МКД она не идёт: гараж дома —
    # постоянные и гостевые (`underground_parking_requirement`, выгрузка
    # ГлавАПУ строками 42.1–42.2). Прежде подпись клала её «в подземный паркинг
    # дома» — о гараже, который её не содержит. Без оговорки «положено 222,
    # строим 173» читается как недострой на 49 мест.
    own_keys = {item["tep_key"] for item in own}
    in_house = sum(int(row.get("required_spaces") or 0)
                   for row in (demand.get("rows") or [])
                   if row.get("tep_key") not in own_keys)
    head = (f"По нормативу {demand.get('norm_of') or ''} положено {required} мест."
            if required else "Норматив не посчитан — числа заданы руками.")
    if in_house:
        head += (f" Из них {in_house} — встроенной коммерции МКД: приобъектная "
                 "стоянка у дома (плоскостная парковка или улица, 945-ПП п. 6.1.2.3), "
                 "в подземный паркинг МКД не входит.")
    text = head + f" Строим {built}, продаётся {sold}: " + "; ".join(parts) + "."
    # Оговорка живёт у числа, а не в соседнем месте. Без выгрузки ГлавАПУ норма
    # берёт верхний край (К1 = К2 = 1) — это МАКСИМУМ мест, и подписанный
    # нормой он читается как расчёт города. Число при этом попадает в поля
    # гаража, то есть в метры, в CAPEX и в выручку: молчать о его
    # происхождении дороже, чем показать длинную фразу.
    caveats = [line for line in ((demand.get("assumptions") or []) + (demand.get("warnings") or [])) if line]
    if caveats:
        spoken = "; ".join(caveats)
        text += " " + spoken[:1].upper() + spoken[1:] + "."
    return text


# Чей норматив посчитал приобъектные места — в родительном падеже, чтобы
# встать после «по нормативу». Подпись берётся отсюда же, откуда расчёт
# берёт юрисдикцию: зашитое «приложение 6 к 945-ПП» на участке в области
# называло московский документ под областным числом (Мытищи, 04.10.2026).
PARKING_NORM_OF: dict[str, str] = {
    parking_norms.MOSCOW: "приложения 6 к 945-ПП",
    parking_norms.MOSCOW_OBLAST: "Московской области (СП 42.13330.2016, табл. Ж.1)",
}


def parking_demand(inputs: dict[str, Any], tep: dict[str, Any]) -> dict[str, Any]:
    """Сколько ПРИОБЪЕКТНЫХ мест требует каждый нежилой объект.

    Это справка, а не стройка. Приобъектная парковка — стоянка вдоль проезда:
    её нельзя поставить на кадастр, значит нельзя и продать (решение владельца,
    06.09.2026: «это кусок асфальта»). Она входит в благоустройство своей
    статьёй и ни метров ГНС, ни своего СМР, ни выручки не порождает. Норма
    отвечает на «сколько положено», и на этом её работа кончается.

    Собственный паркинг объекта — другое: гараж под ОСЗ ставится на кадастр и
    продаётся машино-местами. Его число задаёт человек (`OBJECT_PARKING_FIELDS`),
    и из этой нормы оно НЕ выводится.

    База московского норматива — НЕЖИЛАЯ НАЗЕМНАЯ ПЛОЩАДЬ (сноска 2 приложения
    1 в редакции 2579-ПП). В нашем ТЭП это `gns` продукта: подземная часть у
    него своей строкой. Подмена базы здесь не выглядит ошибкой — между ННП и
    суммарной поэтажной площадью десятая часть метров.

    Постоянные и гостевые места жителей сюда не входят: у них своё приложение 5
    и свой расчёт, и трогать его этот модуль не должен.
    """
    region = str((inputs or {}).get("vri_region") or "msk").strip().lower()
    jurisdiction = parking_norms.MOSCOW_OBLAST if region in ("mo", "область") else parking_norms.MOSCOW
    k1 = n(inputs, "parking_k1")
    k2 = n(inputs, "parking_k2")
    design_mode = str((inputs or {}).get("parking_design_mode")
                      or parking_norms.DESIGN_MODE_DEFAULT)
    # Вторая ступень лестницы коэффициентов — приложения 3 и 6 по своему
    # участку. Район и ТТК — у одного владельца с льготой за МПТ
    # (`site_position`): руки сильнее документа, противоречие с разбором
    # кадастра показывается, а не молчит. Прежде здесь читалась
    # `_glavapu_import.territory`, которую страница не сохраняет, и ступень
    # «К2 по району из разбора кадастра» в живом проекте не срабатывала.
    position = site_position.site_position(inputs)
    district = position["district"]
    inside_ttk: Any = position["inside_ttc"]
    rail_distance = n(inputs, "parking_rail_distance_m")
    ratios, _ratio_notes = tep_ratios_applied(inputs)
    rows: list[dict[str, Any]] = []
    required_named = 0
    # Коэффициент, ПРИНЯТЫЙ расчётом, а не пришедший во вводных: без выгрузки
    # ГлавАПУ норма берёт верхний край (решение владельца, 06.09.2026), и
    # отдавать наружу ноль значило бы показать одно, а посчитать другим.
    k1_applied = k2_applied = 0.0
    k_assumed = False
    k_origin = {"k1": "", "k2": ""}
    for tep_key, msk_function, mo_function, built_in in _PARKING_DEMAND_PRODUCTS:
        # Единственный продукт, у которого функция норматива зависит от вводных:
        # «ФОК / медцентр» — объект с двумя назначениями, и у каждого его
        # экземпляра назначение своё.
        _purposeful = _BY_KEY.get(tep_key)
        if _purposeful is not None and _purposeful.purpose_key:
            msk_function, mo_function = sports_parking_functions(
                inputs, _purposeful.purpose_key)
        row = (tep or {}).get(tep_key) or {}
        # База у юрисдикций РАЗНАЯ, и это часть норматива, а не подробность.
        # Москва считает от нежилой наземной площади (сноска 2 приложения 1 в
        # редакции 2579-ПП), область — от общей (приложение 10 и п. 5.12).
        #
        # ННП — площадь В ГАБАРИТАХ ВНУТРЕННИХ СТЕН (владелец, 08.09.2026), то
        # есть наша ОБЩАЯ площадь помещений, а не ГНС: ГНС обводит здание по
        # наружным стенам. Прежде встроенная коммерция считалась от общей, а
        # отдельно стоящие — от ГНС целиком: одна единица приложения 1 стояла
        # над двумя разными базами, и на офиснике 20 000 м² это давало 318 мест
        # против 298. Толщина стен — это доля продукта (`total_of_gns`), она
        # версионируемая и правится человеком, поэтому берётся из ПРИМЕНЁННЫХ
        # долей, а не зашивается числом.
        share = float((ratios.get(tep_key) or {}).get("total_of_gns") or 0.0)
        area = n(row, "total_area") or (n(row, "gns") * share if share else 0.0)
        if area <= 0:
            continue
        if jurisdiction == parking_norms.MOSCOW:
            got = parking_norms.moscow_required(
                msk_function, area, k1=k1, k2=k2, built_in=built_in,
                district=district, inside_ttk=inside_ttk,
                rail_distance_m=rail_distance)
        else:
            # 774-ПП называет встроенно-пристроенные помещения первых этажей
            # прямо, и для них правило 1/50 — не фолбэк, а сама норма.
            got = parking_norms.mo_required(
                "built_in" if built_in else mo_function, area, design_mode=design_mode)
        got["tep_key"] = tep_key
        got["label"] = row.get("label") or tep_key
        if got.get("k1") is not None:
            k1_applied = float(got.get("k1") or 0.0)
            k2_applied = float(got.get("k2") or 0.0)
            k_assumed = k_assumed or bool(got.get("k1_assumed") or got.get("k2_assumed"))
            k_origin = {"k1": str(got.get("k1_origin") or ""),
                        "k2": str(got.get("k2_origin") or "")}
        required_named += int(got.get("required_spaces") or 0)
        rows.append(got)
    assumptions: list[str] = []
    for row in rows:
        assumptions.extend(row.get("assumptions") or [])
    missing = [f"{row['label']}: {row.get('reason')}" for row in rows if row.get("reason")]
    return {
        "jurisdiction": jurisdiction,
        "norm_of": PARKING_NORM_OF[jurisdiction],
        "k1": k1_applied or k1, "k2": k2_applied or k2,
        "k_input": {"k1": k1, "k2": k2},
        "k_assumed": k_assumed,
        # Чьи это коэффициенты: города, приложения или нашего незнания. Между
        # таблицей и верхним краем разница впятеро, и «assumed» их не разводит.
        "k_origin": k_origin,
        "k_basis": {"district": district, "inside_ttk": inside_ttk,
                    "district_source": position["district_source"],
                    "ttk_source": position["ttk_source"],
                    "rail_distance_m": rail_distance,
                    "conflicts": position["conflicts"]},
        "design_mode": design_mode if jurisdiction == parking_norms.MOSCOW_OBLAST else "",
        "rows": rows,
        "required_total": required_named,
        "missing": missing,
        "assumptions": list(dict.fromkeys(assumptions)),
    }


_GLAVAPU_VRI_BASE_INDEXATION = 1.0175
_GLAVAPU_VRI_BASE_INDEXATION_DATE = "16.08.2026"

# --- штатный калькулятор ГлавАПУ на сервере ---------------------------------
# Копировать методику ГлавАПУ оказалось тупиком: плата за ВРИ разошлась на
# 1,75%, компенсация — на 19%, и оба раза расхождение находил человек на
# скриншотах, а не мы. Ставки индексируются, коэффициенты меняются, и наш
# пересказ отстаёт на неизвестный срок. Поэтому расчёт делает сам калькулятор,
# запущенный браузером без экрана: та же последовательность, что отрабатывает
# скрытый iframe на сайте. Наши формулы остаются фолбэком — если ГлавАПУ
# недоступен или сломалась автоматизация, отчёт честно говорит, что расчёт
# запасной, вместо тихой выдачи устаревшей методики.
_GLAVAPU_HEADLESS_ENABLED = _env_str("GLAVAPU_HEADLESS", "").strip().lower() in ("1", "true", "yes", "on")
_GLAVAPU_HEADLESS_TIMEOUT_MS = int(max(20.0, _env_float("GLAVAPU_HEADLESS_TIMEOUT_SECONDS", 90.0)) * 1000)
_GLAVAPU_HEADLESS: dict[str, Any] = {"last_ok": "", "last_error": "", "runs": 0,
                                     "fallbacks": 0, "waits": 0, "last_ms": {}}
# Браузер запускается по одному на машину: ядро — 2 vCPU и 4 ГБ, воркеров два,
# и каждый Chromium берёт 300–400 МБ. Два одновременных расчёта клали бы не
# только ТЭП, а весь контейнер по нехватке памяти. Второй запрос ждёт очереди
# — секунды ожидания дешевле перезапуска бота.
_GLAVAPU_HEADLESS_SLOTS = max(1, int(_env_float("GLAVAPU_HEADLESS_PARALLEL", 1)))
_GLAVAPU_HEADLESS_LOCK = threading.Semaphore(_GLAVAPU_HEADLESS_SLOTS)
_GLAVAPU_HEADLESS_QUEUE_SECONDS = max(5.0, _env_float("GLAVAPU_HEADLESS_QUEUE_SECONDS", 120.0))
# Предохранитель. Пока штатный калькулятор недоступен — нет Chromium в образе,
# закрыт выход к genplan.tech, сменилась вёрстка — каждый расчёт честно ждал
# полный таймаут и только потом уходил на формулы. Человек платил полторы
# минуты за ответ, который был известен заранее. После сбоя браузер не трогаем
# несколько минут: формулы отвечают сразу, а причина видна в /status.
_GLAVAPU_HEADLESS_COOLDOWN_SECONDS = max(0.0, _env_float("GLAVAPU_HEADLESS_COOLDOWN_SECONDS", 300.0))
_GLAVAPU_HEADLESS_BLOCKED_UNTIL = {"at": 0.0, "row": 0}

# Предохранитель растёт, пока отказы идут подряд, и не дольше получаса.
# 01.09.2026 калькулятор ГлавАПУ лежал у самого города — проверено вручную в
# браузере, — и каждый человек платил за это ожиданием: пять минут паузы, потом
# снова полторы минуты в недоступную кнопку, и так весь день. Пауза в пять
# минут написана под СРЫВ БРАУЗЕРА, который проходит сам; лежащий чужой сервис
# сам не проходит, и стучаться к нему с прежней частотой — это платить временем
# людей за уже известный ответ.
#
# Обратная сторона названа тем же правилом, по которому пауза вообще короткая:
# запасной ответ не должен пережить штатный. Поэтому лестница сбрасывается
# первым же удавшимся расчётом, а расти начинает только со второго отказа —
# одиночный срыв браузера остаётся пятиминутным, как и был.
_GLAVAPU_HEADLESS_COOLDOWN_MAX_SECONDS = max(
    _GLAVAPU_HEADLESS_COOLDOWN_SECONDS,
    _env_float("GLAVAPU_HEADLESS_COOLDOWN_MAX_SECONDS", 1800.0))


def _glavapu_headless_available() -> bool:
    """Стоит ли вообще пытаться поднимать браузер."""
    if not _GLAVAPU_HEADLESS_ENABLED:
        return False
    return time.monotonic() >= _GLAVAPU_HEADLESS_BLOCKED_UNTIL["at"]


def _glavapu_cooldown_seconds(row: int) -> float:
    """Пауза после `row`-го отказа подряд: 5, 10, 20, 30 минут и дальше 30."""
    if _GLAVAPU_HEADLESS_COOLDOWN_SECONDS <= 0:
        return 0.0
    grown = _GLAVAPU_HEADLESS_COOLDOWN_SECONDS * (2 ** max(0, int(row) - 1))
    return min(grown, _GLAVAPU_HEADLESS_COOLDOWN_MAX_SECONDS)


def _glavapu_headless_failed() -> None:
    _GLAVAPU_HEADLESS_BLOCKED_UNTIL["row"] = int(
        _GLAVAPU_HEADLESS_BLOCKED_UNTIL.get("row") or 0) + 1
    pause = _glavapu_cooldown_seconds(_GLAVAPU_HEADLESS_BLOCKED_UNTIL["row"])
    if pause > 0:
        _GLAVAPU_HEADLESS_BLOCKED_UNTIL["at"] = time.monotonic() + pause

# Браузер живёт между расчётами. Холодный запуск Chromium и первая загрузка
# страницы калькулятора со всеми её ассетами стоили большую часть минуты, и
# платились они каждый раз заново. Тёплый браузер отдаёт ассеты из своего кэша,
# а платится за это памятью — поэтому после простоя он закрывается сам.
#
# Синхронный Playwright привязан к потоку, в котором создан, поэтому браузером
# владеет один выделенный поток, а расчёты приходят к нему очередью. Заодно это
# и есть ограничение «один Chromium на машину»: второго потока не бывает.
# Ноль (умолчание) — браузер живёт, пока живёт процесс. Таймер простоя экономил
# 300–400 МБ, но платил холодным стартом за каждый расчёт: боты не работают
# непрерывно, и пятнадцати минут между двумя участками хватает, чтобы Chromium
# успел закрыться. Кому память дороже секунд — ставит секунды.
_GLAVAPU_HEADLESS_IDLE_SECONDS = max(0.0, _env_float("GLAVAPU_HEADLESS_IDLE_SECONDS", 0.0))
_GLAVAPU_HEADLESS_POLL_MS = int(max(50.0, _env_float("GLAVAPU_HEADLESS_POLL_MS", 200.0)))
_GLAVAPU_HEADLESS_JOBS: "queue.Queue[tuple[list[str], float, dict[str, Any], threading.Event]]" = queue.Queue()
_GLAVAPU_BROWSER_LOCK = threading.Lock()
_GLAVAPU_BROWSER_THREAD: threading.Thread | None = None
# --disable-dev-shm-usage: в контейнере /dev/shm мал, и Chromium на тяжёлой
# странице падает молча, вместо того чтобы честно отработать.
_GLAVAPU_HEADLESS_ARGS = [
    "--no-sandbox", "--disable-dev-shm-usage", "--disable-gpu",
    "--disable-extensions", "--disable-background-networking",
    "--disable-features=Translate,BackForwardCache", "--mute-audio", "--no-first-run",
]
# Картинки, шрифты и счётчики к таблице ТЭП отношения не имеют, а тянутся
# дольше самого расчёта. Всё, что участвует в счёте, — запросы к API ГлавАПУ.
# Что случилось с запросами САМОЙ страницы. Территория у ГлавАПУ формируется не
# в браузере: страница спрашивает свой бэкенд, и пока ответа нет, кнопка
# «Перейти к расчётам» стоит недоступной — ровно то, что мы видели. Канал до их
# API с ядра никто не проверял (владелец, 01.09.2026: «ты вообще проверить
# канал до ГлавАПУ то не хочешь?»), а по нашей диагностике это было неотличимо
# от «участок не опознан».
#
# Список ограничен и очищается перед каждым расчётом: это диагностика, а не
# журнал.
_GLAVAPU_NET: dict[str, list[dict[str, str]]] = {"failed": [], "bad": []}
_GLAVAPU_NET_LIMIT = 12


def _glavapu_net_reset() -> None:
    _GLAVAPU_NET["failed"] = []
    _GLAVAPU_NET["bad"] = []


def _glavapu_net_watch(page: Any) -> None:
    """Записывает сорванные запросы и ответы с ошибкой. Один раз на страницу."""
    def failed(request: Any) -> None:
        if len(_GLAVAPU_NET["failed"]) >= _GLAVAPU_NET_LIMIT:
            return
        try:
            failure = str(getattr(request, "failure", "") or "")
            # Мы сами гасим аналитику и картинки — это не сорванный канал.
            if "aborted" in failure.lower() or "ERR_ABORTED" in failure:
                return
            _GLAVAPU_NET["failed"].append(
                {"url": str(request.url)[:200], "why": failure[:120]})
        except Exception:
            pass

    def answered(response: Any) -> None:
        try:
            if int(response.status) < 400 or len(_GLAVAPU_NET["bad"]) >= _GLAVAPU_NET_LIMIT:
                return
            _GLAVAPU_NET["bad"].append(
                {"url": str(response.url)[:200], "why": f"HTTP {response.status}"})
        except Exception:
            pass

    page.on("requestfailed", failed)
    page.on("response", answered)


_GLAVAPU_BLOCKED_TYPES = {"image", "font", "media"}
_GLAVAPU_BLOCKED_HOSTS = ("mc.yandex.", "metrika", "google-analytics.com",
                          "googletagmanager.com", "top-fwz1.mail.ru",
                          "doubleclick.net", "vk.com/rtrg")

# Обучающий тур genplan.tech (react-joyride) висит поверх интерфейса с
# затемнением и перехватывает клики: Playwright честно повторял попытку 168 раз
# и уходил в таймаут. В браузере человека тур закрыт однажды и больше не
# появляется, а свежий Chromium на сервере видит его каждый раз.
#
# Сначала пробуем закрыть штатно — кнопкой пропуска: она пишет в хранилище, что
# тур пройден, и он не возвращается. Если кнопки нет, снимаем оверлей из DOM.
_GLAVAPU_DISMISS_TOUR_JS = """() => {
  let closed = 0;
  const buttons = document.querySelectorAll(
    '[data-action="skip"], [data-action="close"], [aria-label="Close"],'
    + ' .react-joyride__tooltip button');
  for (const button of buttons) {
    const label = String(button.textContent || '').trim().toLowerCase();
    const action = String(button.getAttribute('data-action') || '');
    if (action === 'skip' || action === 'close'
        || /пропустить|закрыть|skip|close|понятно/.test(label)) {
      button.click();
      closed += 1;
      break;
    }
  }
  // Узлы не удаляем: React считает портал своим и при следующем обновлении
  // обращается к нему. Удаление роняло всё приложение — калькулятор показывал
  // экран «Перезагрузить страницу», и расчёт упирался в отсутствие полей.
  // Стиль тур гасит так же надёжно, а чужой DOM остаётся нетронутым.
  let hidden = 0;
  if (!document.getElementById('plato-tour-off')) {
    const style = document.createElement('style');
    style.id = 'plato-tour-off';
    style.textContent = '#react-joyride-portal, .react-joyride__overlay,'
      + ' .react-joyride__spotlight, .react-joyride__tooltip'
      + ' { display: none !important; pointer-events: none !important; }';
    document.head.appendChild(style);
    hidden = 1;
  }
  return {closed, hidden};
}"""

# Поле кадастровых номеров ищется по нескольким признакам. Один жёсткий
# селектор на чужой странице — это обещание, что вёрстка genplan.tech никогда
# не изменится; она изменилась, и `#id-cad-numbers-text-field` перестал
# находиться, а расчёт девяносто секунд ждал элемент, которого нет.
_GLAVAPU_NUMBER_FIELD_SELECTORS = (
    "#id-cad-numbers-text-field",
    "[id*='cad-numbers']",
    "textarea[placeholder*='адастр']",
    "input[placeholder*='адастр']",
    "[aria-label*='адастр']",
    ".MuiDialog-root textarea, .MuiDialog-root input[type='text']",
)

# Что вообще есть на странице в момент срыва: без этого следующая правка
# селектора — это ещё один круг переписки со скриншотами.
#
# Видимость считается по прямоугольнику, а не по offsetParent: у всего, что
# лежит внутри position:fixed — а диалоги MUI именно такие, — offsetParent
# равен null, и поле в открытом диалоге не попало бы в список вовсе. Первая
# версия этой диагностики честно сообщила «полей нет» там, где они могли быть.
_GLAVAPU_VISIBLE_FIELDS_JS = """() => {
  const shown = el => {
    const rect = el.getBoundingClientRect();
    return rect.width > 0 && rect.height > 0;
  };
  const fields = Array.from(document.querySelectorAll('input, textarea'))
    .slice(0, 15)
    .map(el => [el.tagName.toLowerCase(), el.id || '-',
                el.getAttribute('placeholder') || el.getAttribute('aria-label') || '-',
                shown(el) ? 'виден' : 'скрыт'].join(':'));
  const buttons = Array.from(document.querySelectorAll('button, [role="button"]'))
    .filter(shown)
    .slice(0, 15)
    .map(el => String(el.textContent || '').trim().slice(0, 24) || '·');
  return {
    url: String(location.href).slice(0, 120),
    fields: fields.length ? fields : ['нет'],
    buttons: buttons.length ? buttons : ['нет'],
  };
}"""

_GLAVAPU_READ_ROWS_JS = """() => {
  const table = document.querySelector('table[aria-label="calc table"]');
  if (!table) return [];
  return Array.from(table.querySelectorAll('tbody tr')).map(row => {
    const cells = Array.from(row.children).map(c => String(c.textContent || '').replace(/\s+/g, ' ').trim());
    if (cells.length < 4) return null;
    const raw = cells[0];
    const code = /^\d+(?:[.,]\d+)*$/.test(raw) ? raw.replace(/,/g, '.') : '';
    return {code, name: cells[1], unit: cells[2], value: cells[3]};
  }).filter(r => r && r.name && r.value);
}"""


# Что на странице лежит на самом деле. Спрашивается ровно тогда, когда таблица
# не признана готовой: «калькулятор не отдал таблицу (строк 79)» — сообщение,
# которое ничего не объясняет, потому что таблица-то как раз пришла, и в ней
# семьдесят девять строк. Не сошлись КОДЫ, а какие пришли — знала только чужая
# страница. Правило прежнее: селектор на чужой странице живёт парой с
# диагностикой, и в ошибку кладётся сама страница, а не её отсутствие.
_GLAVAPU_SNAPSHOT_JS = """() => {
  const tables = Array.from(document.querySelectorAll('table')).map(t => ({
    label: t.getAttribute('aria-label') || '',
    rows: t.querySelectorAll('tbody tr').length,
  }));
  const table = document.querySelector('table[aria-label="calc table"]');
  const rows = table ? Array.from(table.querySelectorAll('tbody tr')).map(row =>
    Array.from(row.children).map(c => String(c.textContent || '').replace(/\s+/g, ' ').trim())
  ) : [];
  const proceed = document.querySelector('[data-r="map-proceed-button"]')
    || Array.from(document.querySelectorAll('button')).find(b =>
         /перейти к расч/i.test(b.getAttribute('aria-label') || b.textContent || ''));
  const dialog = document.querySelector('[role="dialog"]');
  return {
    url: location.href,
    proceed: proceed ? {
      disabled: !!proceed.disabled,
      label: String(proceed.getAttribute('aria-label') || proceed.textContent || '')
        .replace(/\s+/g, ' ').trim().slice(0, 80),
    } : null,
    dialog: dialog ? String(dialog.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 600) : '',
    // Ввод участка у ГлавАПУ — не диалог, а левая ПАНЕЛЬ (экран владельца,
    // 01.09.2026), и `[role="dialog"]` её не находит: отказ говорил «диалог
    // ничего не сообщил» там, где на странице написано «Район: Савёловский» и
    // площадь участка. В ошибку кладётся сама страница, а не её отсутствие.
    page_text: String(document.body ? document.body.innerText || '' : '')
      .replace(/\s+/g, ' ').trim().slice(0, 1500),
    errors: Array.from(document.querySelectorAll(
      '.Mui-error, .MuiFormHelperText-root, [role="alert"]'))
      .map(n => String(n.textContent || '').replace(/\s+/g, ' ').trim())
      .filter(Boolean).slice(0, 8),
    tables: tables.slice(0, 12),
    calc_table: !!table,
    row_count: rows.length,
    widths: Array.from(new Set(rows.map(r => r.length))).slice(0, 6),
    sample: rows.slice(0, 6),
    tail: rows.slice(-3),
    buttons: Array.from(document.querySelectorAll('button'))
      .map(b => String(b.textContent || '').replace(/\s+/g, ' ').trim())
      .filter(Boolean).slice(0, 12),
  };
}"""


# Строки, без которых таблица бесполезна. Проверяются по ИМЕНИ, а не по номеру:
# разбор и так читает таблицу по именам, а номера чужой таблицы источник
# перенумеровал молча — кода 60 у ГлавАПУ больше нет, таблица кончается на 58
# (живой снимок ядра, 01.09.2026). Имя строки означает величину, номер — только
# её место, и держаться надо за первое.
_GLAVAPU_CONTROL_NAMES = (
    "площадь территории проектирования",
    "население",
    "количество квартир",
    "площадь квартир",
)


def _glavapu_name_key(value: Any) -> str:
    return " ".join(str(value or "").lower().replace("ё", "е").split())


def _glavapu_stems(value: str) -> list[str]:
    """Основы слов: шесть букв хватает, чтобы пережить падеж и не поймать чужое."""
    return [word[:6] for word in _glavapu_name_key(value).split() if len(word) > 2]


def _glavapu_missing_controls(rows: list[dict[str, Any]]) -> list[str]:
    """Каких контрольных строк в таблице нет. Пусто — значит все на месте.

    Ищется не начало строки и не строка целиком, а ОСНОВЫ её слов в любом
    месте имени. Начало — та же ловушка, что и номер строки, только мягче:
    «Численность населения» не начинается с «население». Целое слово — ловушка
    третья: «населения» это не «население», русский падеж рассыпает совпадение
    ровно так же, как он рассыпал якорь площадки в модуле публикаций.

    Ложное совпадение здесь дёшево — это признак готовности, а не величина;
    пропущенное останавливает расчёт у всех сразу.
    """
    have = [_glavapu_name_key(row.get("name")) for row in rows]
    return [need for need in _GLAVAPU_CONTROL_NAMES
            if not any(all(stem in name for stem in _glavapu_stems(need))
                       for name in have)]


def _glavapu_table_shot(rows: list[dict[str, Any]]) -> str:
    """Отпечаток таблицы: по нему видно, что она перестала меняться.

    Ждать «появился код 60» нельзя — номер чужой строки меняет источник. Ждать
    «таблица перестала меняться» можно всегда: это свойство самой таблицы, а не
    её нумерации.
    """
    return "|".join(
        f"{row.get('code') or ''}={row.get('value') or ''}" for row in rows)


def _glavapu_not_ready_message(rows: list[dict[str, Any]],
                               snapshot: dict[str, Any]) -> str:
    """Отказ называет то, что увидел, а не то, чего не дождался.

    Состояния читаются одинаково и означают разное: таблицы нет вовсе; таблица
    есть и пуста; таблица полна, но в ней нет строк, которые мы читаем; таблица
    полна и всё ещё считается.
    """
    limit = _GLAVAPU_HEADLESS_TIMEOUT_MS // 1000
    if not snapshot.get("calc_table", True):
        labels = ", ".join(f"{t.get('label') or '—'}:{t.get('rows')}"
                           for t in (snapshot.get("tables") or [])[:6])
        return (f"таблицы calc table на странице нет за {limit} с; "
                f"таблицы на странице: {labels or 'ни одной'}")
    if not rows:
        return f"таблица calc table пуста за {limit} с"
    missing = _glavapu_missing_controls(rows)
    if missing:
        first = " | ".join((snapshot.get("sample") or [[]])[0][:4])
        return (f"таблица есть ({len(rows)} строк), но в ней нет строк, которые мы "
                f"читаем: {', '.join(missing)}. Первая строка: {first[:180]}")
    return (f"таблица есть ({len(rows)} строк), все контрольные строки на месте, но за "
            f"{limit} с она так и не перестала меняться — калькулятор всё ещё считает")


class GlavapuParcelNotAccepted(TimeoutError):
    """Калькулятор не принял участок: кнопка перехода к расчётам не ожила.

    Живой ответ ядра (01.09.2026): кнопка `map-proceed-button` есть, но стоит
    `disabled` с подписью «…», и Playwright девяносто секунд стучится в неё,
    после чего отдаёт свой стек. Читать в нём нечего: это не поломка клика, а
    ответ калькулятора — он не собрал территорию по этим номерам. Ждать в таком
    состоянии бессмысленно: кнопка не оживёт, пока участок не опознан.
    """

    def __init__(self, message: str, snapshot: dict[str, Any] | None = None) -> None:
        super().__init__(message)
        # Подпись написана нами для человека — её и отдаём наружу, а не
        # `str(exc)`: так в ответ не попадает ничего, кроме этого текста.
        self.public_message = str(message)
        self.snapshot = snapshot or {}


class GlavapuTableNotReady(TimeoutError):
    """Таблица не признана готовой. Снимок страницы приложен к отказу."""

    def __init__(self, message: str, snapshot: dict[str, Any] | None = None) -> None:
        super().__init__(message)
        # Подпись написана нами для человека — её и отдаём наружу, а не
        # `str(exc)`: так в ответ не попадает ничего, кроме этого текста.
        self.public_message = str(message)
        self.snapshot = snapshot or {}


def _glavapu_block_junk(route: Any) -> None:
    """Отсекает то, что к расчёту отношения не имеет."""
    request = route.request
    junk = (request.resource_type in _GLAVAPU_BLOCKED_TYPES
            or any(host in request.url for host in _GLAVAPU_BLOCKED_HOSTS))
    try:
        route.abort() if junk else route.continue_()
    except Exception:  # страница уже ушла — нечего продолжать
        pass


# Сколько ждём, пока калькулятор примет участок. Меньше общего срока
# намеренно: пока кнопка перехода стоит `disabled`, таблицы не будет вовсе, и
# доедать оставшееся время нечем — а отказ нужен человеку сейчас, а не через
# полторы минуты.
_GLAVAPU_PARCEL_WAIT_MS = 45_000


def _glavapu_proceed(page: Any, numbers: list[str]) -> None:
    """Нажать «Перейти к расчётам», дождавшись, что кнопка ожила.

    Прежде здесь стоял голый `click()`, и Playwright девяносто секунд стучался
    в `disabled`-кнопку, после чего отдавал свой стек: «Timeout 90000ms
    exceeded … element is not enabled». В стеке не было главного — что
    калькулятор ПРОСТО НЕ ОПОЗНАЛ участок, и кнопка не оживёт никогда.

    Кнопка ищется по нескольким признакам: `data-r` устойчивее подписи, а
    подпись у неё в этом состоянии вообще «…». Правило то же, что и с полем
    номеров: селектор на чужой странице живёт парой с диагностикой.
    """
    button = page.locator('[data-r="map-proceed-button"]').first
    try:
        button.wait_for(state="attached", timeout=5000)
    except Exception:
        button = page.get_by_role("button", name="Перейти к расчётам").first
    deadline = time.monotonic() + _GLAVAPU_PARCEL_WAIT_MS / 1000.0
    while True:
        try:
            if button.is_enabled(timeout=1000):
                button.click(timeout=10_000)
                return
        except Exception:
            pass
        if time.monotonic() > deadline:
            break
        page.wait_for_timeout(_GLAVAPU_HEADLESS_POLL_MS)
    try:
        snapshot = page.evaluate(_GLAVAPU_SNAPSHOT_JS) or {}
    except Exception:
        snapshot = {}
    snapshot = _glavapu_with_network(snapshot)
    raise GlavapuParcelNotAccepted(
        _glavapu_parcel_message(numbers, snapshot), snapshot)


def _glavapu_with_network(snapshot: dict[str, Any]) -> dict[str, Any]:
    """К снимку — что случилось с запросами страницы к её же бэкенду."""
    out = dict(snapshot or {})
    out["network_failed"] = list(_GLAVAPU_NET["failed"])
    out["network_bad"] = list(_GLAVAPU_NET["bad"])
    return out


def _glavapu_network_note(snapshot: dict[str, Any]) -> str:
    """Одной фразой: дошли ли запросы страницы до её бэкенда."""
    failed = snapshot.get("network_failed") or []
    bad = snapshot.get("network_bad") or []
    if not failed and not bad:
        return ""
    parts = []
    if failed:
        first = failed[0]
        parts.append(f"не дошли {len(failed)} запросов страницы, первый — "
                     f"{first.get('url', '')} ({first.get('why', '')})")
    if bad:
        first = bad[0]
        parts.append(f"ответили ошибкой {len(bad)}, первый — "
                     f"{first.get('url', '')} ({first.get('why', '')})")
    return "Канал страницы: " + "; ".join(parts) + ". "


def _glavapu_parcel_message(numbers: list[str], snapshot: dict[str, Any]) -> str:
    """Отказ шага участка — словами, а не стеком Playwright."""
    limit = _GLAVAPU_PARCEL_WAIT_MS // 1000
    listed = ", ".join(numbers[:3]) + ("…" if len(numbers) > 3 else "")
    proceed = snapshot.get("proceed")
    if proceed is None:
        return (f"кнопки «Перейти к расчётам» на странице нет за {limit} с; "
                f"участки: {listed}")
    said = "; ".join(str(x) for x in (snapshot.get("errors") or []))[:200]
    # Панель ввода участка — не диалог, поэтому текст берётся со страницы
    # целиком: по нему видно, сформировалась территория (есть район и площадь)
    # или ввод не дошёл вовсе.
    told = str(snapshot.get("dialog") or "") or str(snapshot.get("page_text") or "")
    return (f"калькулятор не принял участок за {limit} с: кнопка «Перейти к расчётам» "
            f"осталась недоступной (подпись «{proceed.get('label') or '—'}»). "
            f"Участки: {listed}. "
            + _glavapu_network_note(snapshot)
            + (f"Страница говорит: {said}. " if said else "")
            + (f"На странице: {told[:400]}" if told else "Страница ничего не сообщила"))


def _glavapu_drive_page(page: Any, numbers: list[str], area_ha: float,
                        timings: dict[str, int]) -> list[dict[str, Any]]:
    """Шаги браузерной автоматизации — те же, что отрабатывает скрытый iframe
    на сайте: «Участок» → кадастровые номера → «Отправить» → «Перейти к
    расчётам» → чтение таблицы. Готовность таблицы определяется так же, как на
    странице: есть коды 60 и 54 и не меньше шестидесяти строк — иначе рискуем
    снять её недосчитанной.

    Страница переиспользуется между расчётами, поэтому хранилище прошлого
    прогона стирается: восстановленный оттуда чужой участок дал бы правдоподобно
    выглядящий чужой ТЭП. Сама таблица переживает переход не может — переход
    пересобирает DOM.
    """
    step = time.monotonic()

    def mark(name: str) -> None:
        nonlocal step
        now = time.monotonic()
        timings[name] = int((now - step) * 1000)
        step = now

    def recover_if_crashed() -> None:
        """Калькулятор мог упасть и показать экран «Перезагрузить страницу».

        Своя кнопка перезагрузки у него есть — нажимаем её и даём приложению
        собраться заново, вместо того чтобы искать поля на экране ошибки.
        """
        try:
            button = page.get_by_role("button", name="Перезагрузить страницу").first
            if button.is_visible(timeout=1500):
                button.click(timeout=5000)
                page.wait_for_timeout(2500)
                timings["reloaded"] = timings.get("reloaded", 0) + 1
        except Exception:
            pass

    def open_parcel_dialog() -> None:
        """Открывает панель ввода участка.

        «Участок» может оказаться и кнопкой, и вкладкой, и пунктом меню —
        роль button находит не всё. Промах здесь виден не сразу: клик проходит
        вхолостую, а падает уже поиск поля, и причина выглядит чужой.
        """
        attempts = (
            lambda: page.get_by_role("button", name="Участок").first,
            lambda: page.get_by_role("tab", name="Участок").first,
            lambda: page.get_by_text("Участок", exact=True).first,
        )
        for index, attempt in enumerate(attempts):
            try:
                attempt().click(timeout=7000)
                timings["parcel_click"] = index
                return
            except Exception:
                continue
        raise TimeoutError("кнопка «Участок» не нажалась ни одним способом")

    def fill_numbers(text: str) -> None:
        """Вводит кадастровые номера, чем бы ни было поле в текущей вёрстке."""
        for selector in _GLAVAPU_NUMBER_FIELD_SELECTORS:
            try:
                field = page.locator(selector).first
                field.wait_for(state="visible", timeout=5000)
                field.fill(text)
                timings["field"] = _GLAVAPU_NUMBER_FIELD_SELECTORS.index(selector)
                return
            except Exception:
                continue
        try:
            seen = page.evaluate(_GLAVAPU_VISIBLE_FIELDS_JS) or {}
        except Exception:
            seen = {}
        raise TimeoutError(
            "поле кадастровых номеров не найдено. Поля: "
            + ("; ".join(str(x) for x in (seen.get("fields") or ["?"]))[:220])
            + ". Кнопки: "
            + ("; ".join(str(x) for x in (seen.get("buttons") or ["?"]))[:220])
            + f". Адрес: {seen.get('url') or '?'}")

    def dismiss_tour() -> None:
        """Снимает обучающий тур, если он перехватывает клики."""
        try:
            result = page.evaluate(_GLAVAPU_DISMISS_TOUR_JS) or {}
        except Exception:
            return
        if result.get("closed") or result.get("hidden"):
            timings["tour"] = timings.get("tour", 0) + 1

    try:
        if "genplan.tech" in str(page.url or ""):
            page.evaluate("() => { try { localStorage.clear(); sessionStorage.clear(); }"
                          " catch (e) {} }")
    except Exception:
        pass
    url = ("https://genplan.tech/calc/?terrArea=" + urllib.parse.quote(f"{area_ha:.4f}")
           + "&restrictArea=0&plato=" + str(int(time.time() * 1000)))
    page.goto(url, wait_until="domcontentloaded")
    mark("load")
    if not numbers:
        dismiss_tour()  # прогрев заодно гасит тур: он пишется в хранилище
        return []  # страница загружена, ассеты в кэше браузера
    # Тур показывается по шагам и всплывает на каждом новом экране, поэтому
    # снимается перед каждым кликом, а не однажды.
    recover_if_crashed()
    dismiss_tour()
    open_parcel_dialog()
    dismiss_tour()
    fill_numbers(", ".join(numbers))
    page.get_by_role("button", name="Отправить").click()
    dismiss_tour()
    _glavapu_proceed(page, numbers)
    mark("parcel")
    deadline = time.monotonic() + _GLAVAPU_HEADLESS_TIMEOUT_MS / 1000.0
    last_shot = ""
    while True:
        rows = page.evaluate(_GLAVAPU_READ_ROWS_JS) or []
        # Готовность больше не держится на номере чужой строки. Кода 60 у
        # ГлавАПУ не стало — таблица перенумерована и кончается на 58 (живой
        # снимок ядра, 01.09.2026), — и мы ждали несуществующую строку девяносто
        # секунд, на каждом участке и у всех сразу. Номер строки источник меняет
        # когда захочет; ждём того, что от нумерации не зависит: строки, которые
        # мы читаем ПО ИМЕНАМ, на месте, и таблица перестала меняться.
        shot = _glavapu_table_shot(rows)
        # Готовность — свойство самой таблицы, а не наших ожиданий от неё:
        # она пришла, она не пуста и перестала меняться. Ни номера строки, ни
        # её количества здесь больше нет. Число строк было последним таким
        # ожиданием («не меньше шестидесяти»), и оно того же рода, что код 60:
        # источник вправе поменять его молча, а стоит это полутора минутами
        # ожидания на каждом участке у всех сразу.
        if rows and shot and shot == last_shot:
            missing = _glavapu_missing_controls(rows)
            if not missing:
                mark("table")
                return rows
            # Таблица устоялась, а строк, которые мы читаем, в ней нет. Ждать
            # больше нечего: она уже не изменится. Отказ сейчас и по имени
            # лучше полутора минут молчания и «истекло время».
            try:
                snapshot = page.evaluate(_GLAVAPU_SNAPSHOT_JS) or {}
            except Exception:  # страница ушла — снимка не будет, но отказ будет
                snapshot = {}
            raise GlavapuTableNotReady(
                _glavapu_not_ready_message(rows, _glavapu_with_network(snapshot)),
                snapshot)
        last_shot = shot
        if time.monotonic() > deadline:
            try:
                snapshot = page.evaluate(_GLAVAPU_SNAPSHOT_JS) or {}
            except Exception:  # страница ушла — снимка не будет, но отказ будет
                snapshot = {}
            snapshot = _glavapu_with_network(snapshot)
            raise GlavapuTableNotReady(
                _glavapu_not_ready_message(rows, snapshot), snapshot)
        page.wait_for_timeout(_GLAVAPU_HEADLESS_POLL_MS)


def _glavapu_browser_worker() -> None:
    """Единственный поток, владеющий браузером.

    Синхронный Playwright нельзя дёргать из чужого потока, а воркеров у нас
    два, и запросы приходят из пула FastAPI. Поэтому браузер держит один поток,
    расчёты приходят к нему очередью, и он же закрывает Chromium после простоя:
    держать 300–400 МБ ради расчёта, которого может не быть до вечера, дорого.
    """
    global _GLAVAPU_BROWSER_THREAD
    from playwright.sync_api import sync_playwright

    browser = page = None
    try:
        with sync_playwright() as playwright:
            while True:
                try:
                    job = _GLAVAPU_HEADLESS_JOBS.get(
                        timeout=_GLAVAPU_HEADLESS_IDLE_SECONDS or None)
                except queue.Empty:
                    with _GLAVAPU_BROWSER_LOCK:
                        if _GLAVAPU_HEADLESS_JOBS.empty():
                            _GLAVAPU_BROWSER_THREAD = None
                            return
                    continue
                numbers, area_ha, holder, done = job
                timings: dict[str, int] = {}
                try:
                    if browser is None or not browser.is_connected():
                        started = time.monotonic()
                        # Запуск общий с печатью PDF: Playwright при headless
                        # берёт отдельную сборку `chromium_headless_shell`, и
                        # если её в образе нет, падает не только ГлавАПУ —
                        # падает всё, что заводит браузер. Отказ при этом
                        # выглядел по-разному: там формулы, тут прежний PDF, —
                        # и обе поломки читались как «так работает».
                        browser = browser_launch.launch(
                            playwright, args=_GLAVAPU_HEADLESS_ARGS)
                        page = None
                        timings["launch"] = int((time.monotonic() - started) * 1000)
                    if page is None or page.is_closed():
                        page = browser.new_page()
                        page.set_default_timeout(_GLAVAPU_HEADLESS_TIMEOUT_MS)
                        page.route("**/*", _glavapu_block_junk)
                        # Слушатели вешаются один раз на страницу, а список
                        # чистится перед каждым расчётом: диагностика, а не журнал.
                        _glavapu_net_watch(page)
                    _glavapu_net_reset()
                    holder["rows"] = _glavapu_drive_page(page, numbers, area_ha, timings)
                    scenario = holder.get("scenario_params")
                    if scenario and numbers:
                        # Сценарий ставится на ТОМ ЖЕ экране расчёта, что
                        # только что открыт по участку: анализ территории
                        # (район, квартал, К1/К2) — его, а метры — наши.
                        holder["scenario_report"] = glavapu_scenario.apply_scenario(
                            page, scenario)
                        holder["scenario_rows"] = glavapu_scenario.read_rows(page)
                        holder["scenario_xlsx"] = glavapu_scenario.export_xlsx(
                            page, _GLAVAPU_HEADLESS_TIMEOUT_MS // 3)
                        timings["scenario"] = int(
                            holder["scenario_report"].get("ms") or 0)
                except Exception as exc:
                    # Снимок страницы прикладывается к ЛЮБОМУ отказу, а не
                    # только к тем, что мы предвидели: `snapshot: {}` у пробы
                    # означает «смотреть не на что», и именно так выглядел
                    # стек Playwright на недоступной кнопке.
                    if getattr(exc, "snapshot", None) is None and page is not None:
                        try:
                            exc.snapshot = page.evaluate(_GLAVAPU_SNAPSHOT_JS) or {}
                        except Exception:
                            pass
                    holder["error"] = exc
                    # Упавший прогон мог оставить страницу в неизвестном
                    # состоянии, а тихо считать на ней дальше — это чужой ТЭП
                    # под своим именем. Рвём браузер: следующий начнёт с нуля.
                    try:
                        if browser is not None:
                            browser.close()
                    except Exception:
                        pass
                    browser = page = None
                finally:
                    holder["timings"] = timings
                    done.set()
    finally:
        with _GLAVAPU_BROWSER_LOCK:
            if _GLAVAPU_BROWSER_THREAD is threading.current_thread():
                _GLAVAPU_BROWSER_THREAD = None
        try:
            if browser is not None:
                browser.close()
        except Exception:
            pass
        # Поток умер — ждущие расчёты обязаны узнать об этом сейчас, а не по
        # таймауту через три минуты: их место на серверных формулах.
        while True:
            try:
                _, _, holder, done = _GLAVAPU_HEADLESS_JOBS.get_nowait()
            except queue.Empty:
                break
            holder.setdefault("error", RuntimeError("поток браузера остановлен"))
            done.set()


def _glavapu_warm_up() -> None:
    """Поднимает браузер и прогревает страницу калькулятора заранее.

    Иначе первый расчёт после выкатки платит и за старт Chromium, и за полную
    загрузку ассетов ГлавАПУ — а первый расчёт всегда чей-то.
    """
    try:
        _glavapu_headless_rows([], 0.0)
        logging.info("glavapu warm-up done: браузер готов")
    except Exception as exc:
        # Нет Chromium, нет выхода к genplan.tech — расчёт не должен узнавать
        # об этом ценой полутора минут ожидания на первом же участке.
        _GLAVAPU_HEADLESS["last_error"] = (
            f"{datetime.now().isoformat(timespec='seconds')}: прогрев — {_error_location(exc)}")
        _glavapu_headless_failed()
        logging.warning("glavapu warm-up failed: %s", exc)


def _glavapu_headless_rows(numbers: list[str], area_ha: float) -> list[dict[str, Any]]:
    """Таблица ТЭП, снятая с настоящего калькулятора ГлавАПУ.

    Расчёт уходит потоку-владельцу браузера и ждёт его ответа. Ожидание в
    очереди конечно: не дождался — уходим на серверные формулы, а не висим.
    """
    return _glavapu_headless_run(numbers, area_ha).get("rows") or []


def _glavapu_headless_run(numbers: list[str], area_ha: float,
                          scenario_params: dict[str, Any] | None = None) -> dict[str, Any]:
    """Прогон браузера: таблица участка и — если задан — наш сценарий поверх.

    Один путь для расчёта, пробы и сверки сценария: второй браузер или вторая
    очередь к той же странице разошлись бы с первой при первой же правке.
    """
    global _GLAVAPU_BROWSER_THREAD

    # Проверяется здесь, а не в потоке: без Playwright в образе поток умрёт
    # молча, и расчёт вместо мгновенного отката на формулы ждал бы ответа
    # три минуты.
    from playwright.sync_api import sync_playwright  # noqa: F401

    if not _GLAVAPU_HEADLESS_LOCK.acquire(timeout=_GLAVAPU_HEADLESS_QUEUE_SECONDS):
        _GLAVAPU_HEADLESS["waits"] += 1
        raise TimeoutError(
            f"браузер занят дольше {int(_GLAVAPU_HEADLESS_QUEUE_SECONDS)} с "
            "— расчёт уходит на серверные формулы")
    started = time.monotonic()
    try:
        holder: dict[str, Any] = {"scenario_params": scenario_params} if scenario_params else {}
        done = threading.Event()
        with _GLAVAPU_BROWSER_LOCK:
            if _GLAVAPU_BROWSER_THREAD is None or not _GLAVAPU_BROWSER_THREAD.is_alive():
                _GLAVAPU_BROWSER_THREAD = threading.Thread(
                    target=_glavapu_browser_worker, name="glavapu-browser", daemon=True)
                _GLAVAPU_BROWSER_THREAD.start()
            _GLAVAPU_HEADLESS_JOBS.put((list(numbers), float(area_ha), holder, done))
        # Сценарий — второй круг полей и выгрузка книги поверх расчёта участка.
        budget = _GLAVAPU_HEADLESS_TIMEOUT_MS / 1000.0 * (2 if scenario_params else 1) + 60.0
        if not done.wait(budget):
            raise TimeoutError("поток браузера не ответил — расчёт уходит на формулы")
        timings = dict(holder.get("timings") or {})
        timings["total"] = int((time.monotonic() - started) * 1000)
        _GLAVAPU_HEADLESS["last_ms"] = timings
        logging.info("glavapu headless timings: %s", timings)
        if holder.get("error") is not None:
            raise holder["error"]
        return holder
    finally:
        _GLAVAPU_HEADLESS_LOCK.release()


_GLAVAPU_DRIFT_CHECKS = [
    ("4", "население", 3.0, "abs"),
    ("10", "площадь квартир", 0.01, "rel"),
    ("30", "ДОО", 2.0, "abs"),
    ("31", "школа", 2.0, "abs"),
    ("32", "поликлиника", 2.0, "abs"),
    ("42.1", "постоянные машино-места", 2.0, "abs"),
    ("42.2", "гостевые машино-места", 2.0, "abs"),
    ("44", "плата за смену ВРИ", 0.01, "rel"),
    ("54", "компенсация ДОО", 0.01, "rel"),
    ("55", "компенсация школа", 0.01, "rel"),
    ("56", "компенсация поликлиника", 0.01, "rel"),
]
_GLAVAPU_FORMULA_DRIFT: dict[str, Any] = {"items": [], "checked_at": 0.0, "running": False}
# Сверка формул со штатным калькулятором стоит целого серверного расчёта: она
# заново спрашивает территорию у ГлавАПУ и собирает книгу ТЭП, чтобы сравнить
# одиннадцать чисел. Держать в этом человека, который ждёт свой ТЭП, незачем —
# дрейф методики появляется не чаще раза в квартал, а не раза в клик.
_GLAVAPU_DRIFT_INTERVAL_SECONDS = max(60.0, _env_float("GLAVAPU_DRIFT_INTERVAL_SECONDS", 3600.0))
_GLAVAPU_DRIFT_LOCK = threading.Lock()


def _glavapu_drift_in_background(rows: list[list[Any]], numbers: list[str]) -> None:
    """Ставит сверку формул в фон, но не чаще раза в интервал.

    Ошибка, ушедшая только в лог, — ошибка, которой нет, поэтому результат
    по-прежнему кричит в /status и в предупреждениях расчёта. Но кричать он
    может и со следующего расчёта: дрейф методики — это про квартал, а не про
    секунды ожидания.
    """
    if not numbers:
        return
    with _GLAVAPU_DRIFT_LOCK:
        if _GLAVAPU_FORMULA_DRIFT.get("running"):
            return
        last = float(_GLAVAPU_FORMULA_DRIFT.get("checked_at") or 0.0)
        if last and time.monotonic() - last < _GLAVAPU_DRIFT_INTERVAL_SECONDS:
            return
        _GLAVAPU_FORMULA_DRIFT["running"] = True

    def worker() -> None:
        try:
            drift = _glavapu_formula_drift(rows, numbers)
        except Exception as exc:
            logging.warning("glavapu drift check failed: %s", exc)
            drift = []
        else:
            if drift:
                _GLAVAPU_FORMULA_DRIFT.update(
                    items=drift, found_at=datetime.now(timezone.utc).isoformat(),
                    numbers=[str(n) for n in numbers])
                _TELEGRAM_RUNTIME["last_error"] = "Дрейф формул ГлавАПУ: " + "; ".join(drift[:4])
            elif _GLAVAPU_FORMULA_DRIFT.get("items"):
                # Формулы снова сходятся — снять флаг, чтобы Telegram не пугал зря.
                _GLAVAPU_FORMULA_DRIFT.update(items=[], found_at="", numbers=[])
        finally:
            with _GLAVAPU_DRIFT_LOCK:
                _GLAVAPU_FORMULA_DRIFT["checked_at"] = time.monotonic()
                _GLAVAPU_FORMULA_DRIFT["running"] = False

    threading.Thread(target=worker, name="glavapu-drift", daemon=True).start()


def _glavapu_formula_drift(rows: list[list[Any]], numbers: list[str]) -> list[str]:
    """Сравнивает собранную таблицу штатного калькулятора с серверными
    формулами по тем же кадастрам. Возвращает список расхождений."""
    if not numbers:
        return []
    quick = vri_tep_quick("msk", ", ".join(str(n) for n in numbers))
    server_rows = _xlsx_read_tables(quick["file"]).get("ТЭП") or []

    def as_map(items: list[list[Any]]) -> dict[str, float | None]:
        out: dict[str, float | None] = {}
        for row in items:
            if not row or len(row) < 4:
                continue
            code = str(row[0] or "").strip()
            if code:
                out[code] = _ru_number(str(row[3] or "").split("(")[0])
        return out

    browser, server = as_map(rows), as_map(server_rows)
    drift: list[str] = []
    for code, label, tolerance, kind in _GLAVAPU_DRIFT_CHECKS:
        b, s = browser.get(code), server.get(code)
        if not b or not s or b <= 0 or s <= 0:
            continue
        limit = tolerance if kind == "abs" else max(abs(b), abs(s)) * tolerance
        if abs(b - s) > limit:
            drift.append(f"{label}: калькулятор {b:g}, формулы {s:g}")
    return drift


# Один участок считают по многу раз подряд: поменяли цену — пересчитали,
# поменяли нарезку — пересчитали, и каждый раз заново поднимался браузер и
# заново считал ГлавАПУ. ТЭП участка за это время не меняется — меняются наши
# вводные. Ставки город индексирует поквартально, поэтому шесть часов памяти
# безопасны, а ждать минуту ради того же ответа — нет.
_GLAVAPU_TEP_CACHE_SECONDS = max(0.0, _env_float("GLAVAPU_TEP_CACHE_SECONDS", 21600.0))
# Запасной ответ помнится минутами, а не часами. Шесть часов — срок для расчёта
# штатного калькулятора: ТЭП участка за это время не меняется. Ответ формул —
# это «калькулятор был недоступен в ту секунду», и держать его наравне со
# штатным значит месяцами отдавать запасной расчёт после одного срыва: браузер
# уже починен, предохранитель снят через пять минут, а кэш всё ещё отвечает
# формулами.
_GLAVAPU_TEP_FALLBACK_CACHE_SECONDS = max(0.0, _env_float("GLAVAPU_TEP_FALLBACK_CACHE_SECONDS", 300.0))
_GLAVAPU_TEP_CACHE: dict[tuple[str, ...], tuple[float, dict[str, Any], bool]] = {}
_GLAVAPU_TEP_CACHE_LOCK = threading.Lock()
_GLAVAPU_TEP_CACHE_HITS = {"hits": 0}


def _glavapu_tep_cached(numbers: list[str],
                        want_calculator: bool = False) -> dict[str, Any] | None:
    """Запомненный ТЭП участка.

    `want_calculator` — «браузер сейчас на ходу»: тогда запасной ответ из памяти
    не отдаётся, иначе один срыв калькулятора обрекал участок на формулы до
    конца дня.
    """
    if _GLAVAPU_TEP_CACHE_SECONDS <= 0:
        return None
    key = tuple(sorted(str(x).strip() for x in numbers))
    with _GLAVAPU_TEP_CACHE_LOCK:
        item = _GLAVAPU_TEP_CACHE.get(key)
        if not item:
            return None
        stored_at, payload, is_fallback = item
        if is_fallback and want_calculator:
            return None
        limit = (_GLAVAPU_TEP_FALLBACK_CACHE_SECONDS if is_fallback
                 else _GLAVAPU_TEP_CACHE_SECONDS)
        if limit <= 0 or time.monotonic() - stored_at > limit:
            _GLAVAPU_TEP_CACHE.pop(key, None)
            return None
        _GLAVAPU_TEP_CACHE_HITS["hits"] += 1
    return copy.deepcopy(payload)


def _glavapu_tep_store(numbers: list[str], payload: dict[str, Any],
                       is_fallback: bool = False) -> None:
    if _GLAVAPU_TEP_CACHE_SECONDS <= 0 or not numbers:
        return
    key = tuple(sorted(str(x).strip() for x in numbers))
    with _GLAVAPU_TEP_CACHE_LOCK:
        if len(_GLAVAPU_TEP_CACHE) >= 64:
            oldest = min(_GLAVAPU_TEP_CACHE, key=lambda k: _GLAVAPU_TEP_CACHE[k][0])
            _GLAVAPU_TEP_CACHE.pop(oldest, None)
        _GLAVAPU_TEP_CACHE[key] = (time.monotonic(), copy.deepcopy(payload), is_fallback)


def _glavapu_headless_state() -> dict[str, Any]:
    """Почему расчёт идёт формулами — в самом ответе, а не только в логе.

    Браузер живёт на ядре, и с телефона его состояние никак не увидеть.
    «Ошибка, ушедшая только в лог, — это ошибка, которой нет»: причина отката
    должна доезжать до человека вместе с расчётом.
    """
    try:
        host = socket.gethostname()
    except Exception:
        host = "?"
    where = (f"пересылает на ядро, отвечает {host}"
             if _core_api_url("/cadastral/tep-server") else f"считает сам, {host}")
    if not _GLAVAPU_HEADLESS_ENABLED:
        return {"state": "выключен", "where": where,
                "hint": ("Штатный калькулятор запускает ядро. Нужны GLAVAPU_HEADLESS=1 "
                         "в .env ядра и образ с Chromium (docker compose build).")
                if where == "ядро" else
                ("Расчёт остался на Render — ядро не ответило или его адрес не задан. "
                 "Браузер живёт только на ядре.")}
    blocked = max(0, int(_GLAVAPU_HEADLESS_BLOCKED_UNTIL["at"] - time.monotonic()))
    if blocked:
        row = int(_GLAVAPU_HEADLESS_BLOCKED_UNTIL.get("row") or 0)
        return {"state": "предохранитель", "where": where, "blocked_for": blocked,
                "failures_in_row": row,
                "last_error": str(_GLAVAPU_HEADLESS.get("last_error") or ""),
                "hint": (f"Отказов подряд: {row}; следующая попытка через {blocked} с. "
                         "Пауза растёт, пока отказы идут подряд, и сбрасывается первым "
                         "удавшимся расчётом. Причина — в last_error.")}
    # «Готов» — это про браузер, а не про расчёт. На живом ответе ядра
    # (01.09.2026) стояло «готов» при `last_ok: ""` и четырёх откатах на
    # формулы: браузер поднимался исправно, а расчёт не удавался НИ РАЗУ, и
    # состояние это скрывало. Ответ на вопрос «работает ли связка» даёт
    # удавшийся расчёт, а не готовность запустить Chromium.
    return {"state": "готов", "where": where}


def _glavapu_state_with_history(state: dict[str, Any]) -> dict[str, Any]:
    """Готовность браузера и удача расчёта — разные ответы, и путать их нельзя."""
    if state.get("state") != "готов":
        return state
    runs = int(state.get("runs") or 0)
    fallbacks = int(state.get("fallbacks") or 0)
    if state.get("last_ok"):
        return state
    if runs or fallbacks:
        state["state"] = "браузер готов, расчёт не удавался"
        state["hint"] = (
            "Chromium поднимается, но ни один расчёт не дошёл до таблицы "
            f"(попыток {runs}, откатов на формулы {fallbacks}). Причина — в last_error; "
            "снимок страницы покажет /glavapu/probe?cad=<кадастровый номер>.")
    else:
        state["state"] = "браузер готов, расчётов ещё не было"
    return state


def _glavapu_health_file() -> Path:
    return Path(os.getenv("DEVELOPAID_DATA_DIR") or "data") / "glavapu-health.json"


def _glavapu_health_save() -> None:
    """Счётчики — на диск, потому что воркеров два.

    `_GLAVAPU_HEADLESS` живёт в памяти процесса, а `/glavapu/health` отвечает
    тот воркер, которому достался запрос. Расчёт уходил в один, состояние
    спрашивали у другого — и `runs: 0` читалось как «браузер не работает» при
    работающем браузере. Правило проекта прямое: всё, что должно пережить
    переход между запросами, дублируется на диск.
    """
    try:
        path = _glavapu_health_file()
        path.parent.mkdir(parents=True, exist_ok=True)
        keep = {key: _GLAVAPU_HEADLESS.get(key)
                for key in ("last_ok", "last_error", "runs", "fallbacks")}
        # Берётся большее из своего и записанного: счётчик у каждого воркера
        # свой, а вопрос «считал ли калькулятор вообще» — про приложение. Файл
        # от этого только растёт и никогда не отменяет чужой удачный расчёт.
        seen = _glavapu_health_load()
        keep["runs"] = max(int(keep.get("runs") or 0), int(seen.get("runs") or 0))
        keep["fallbacks"] = max(int(keep.get("fallbacks") or 0),
                                int(seen.get("fallbacks") or 0))
        path.write_text(json.dumps(keep, ensure_ascii=False), encoding="utf-8")
    except Exception:
        # Диагностика не должна ронять расчёт: не записалось — не записалось.
        pass


def _glavapu_health_load() -> dict[str, Any]:
    try:
        raw = json.loads(_glavapu_health_file().read_text(encoding="utf-8"))
    except Exception:
        return {}
    return raw if isinstance(raw, dict) else {}


@app.get("/glavapu/probe")
def glavapu_probe(cad: str = "", area: float = 1.0) -> dict[str, Any]:
    """Что калькулятор ГлавАПУ отдаёт прямо сейчас — снимком, а не догадкой.

    Живой ответ с ядра: `state` бывает «готов», а `last_error` при этом говорит
    «не отдал таблицу (строк 79)» — то есть таблица пришла, и в ней семьдесят
    девять строк, а признана неготовой она по кодам. Какие коды пришли, знала
    только чужая страница; из песочницы genplan.tech не спросить.

    Проба гоняет ТОТ ЖЕ путь, что и расчёт, — второго пути наружу не заводим, —
    и на отказе отдаёт приложенный к нему снимок: адрес, таблицы страницы, их
    подписи и размеры, первые и последние строки, видимые кнопки.
    """
    numbers = [part.strip() for part in str(cad or "").split(",") if part.strip()]
    if not numbers:
        raise HTTPException(status_code=400,
                            detail="Нужен кадастровый номер: /glavapu/probe?cad=77:01:0004023:1000")
    started = time.monotonic()
    try:
        rows = _glavapu_headless_rows(numbers, float(area or 1.0))
    except (GlavapuTableNotReady, GlavapuParcelNotAccepted) as exc:
        return {"ok": False, "seconds": round(time.monotonic() - started, 1),
                "error": exc.public_message, "snapshot": exc.snapshot}
    except Exception as exc:  # noqa: BLE001
        # Снимок берётся и у чужого отказа: его прикладывает поток браузера.
        return {"ok": False, "seconds": round(time.monotonic() - started, 1),
                "error": _public_error(exc, "glavapu probe"),
                "snapshot": getattr(exc, "snapshot", None) or {}}
    codes = sorted({str(r.get("code") or "") for r in rows} - {""})
    return {"ok": True, "seconds": round(time.monotonic() - started, 1),
            "row_count": len(rows), "codes": codes[:40], "sample": rows[:6]}


@app.get("/glavapu/health")
def glavapu_health() -> dict[str, Any]:
    """Состояние штатного калькулятора ГлавАПУ — для /status бота.

    Браузер живёт на ядре, а /status спрашивают у бота на Render: без этого
    маршрута сбой связки с ГлавАПУ виден только в предупреждении карточки ТЭП,
    которое легко пролистать. Если задан адрес ядра — спрашиваем его, иначе
    отвечаем о себе; счётчики показывают, чем закончились прошлые расчёты.
    """
    url = _core_api_url("/glavapu/health")
    if url:
        try:
            request = urllib.request.Request(url, headers={"Accept": "application/json"})
            with urllib.request.urlopen(request, timeout=10) as response:
                return json.loads(response.read().decode("utf-8"))
        except Exception as exc:
            return {"state": "ядро недоступно", "where": "Render",
                    "hint": ("Ядро не ответило на запрос состояния: "
                             + _public_error(exc, "glavapu health"))}
    state = dict(_glavapu_headless_state())
    state.update({key: _GLAVAPU_HEADLESS.get(key)
                  for key in ("last_ok", "last_error", "runs", "fallbacks")})
    # К своим счётчикам добавляется то, что записали остальные воркеры: их
    # память нам не видна, а вопрос «считал ли калькулятор» — про приложение
    # целиком, а не про тот процесс, которому достался этот запрос.
    shared = _glavapu_health_load()
    state["runs"] = max(int(state.get("runs") or 0), int(shared.get("runs") or 0))
    state["fallbacks"] = max(int(state.get("fallbacks") or 0),
                             int(shared.get("fallbacks") or 0))
    for key in ("last_ok", "last_error"):
        if not state.get(key) and shared.get(key):
            state[key] = shared[key]
    state["worker"] = os.getpid()
    return _glavapu_state_with_history(state)


# --- сверка нашего сценария со штатным калькулятором ГлавАПУ -----------------
# Выгрузка ГлавАПУ, которую мы забирали до сих пор, — калькулятор с ЕГО
# умолчаниями: 94/6 жилья и коммерции, плотность по таблице, нежильё целиком в
# 4.1. Сверить с ней свой сценарий нельзя — посчитано не то, что строим мы.
# Здесь калькулятору выставляются НАШИ параметры (`glavapu_scenario`), и его
# ответ стоит рядом с нашими числами. Роль ГлавАПУ — проверка: ничего в модели
# эти числа не заменяют.
#
# Браузер — тяжёлая работа на минуту и больше, а окно и бот ждать её не должны.
# Поэтому запрос ставит задание и сразу отвечает его состоянием; страница
# спрашивает тот же маршрут ещё раз, пока задание не кончится. Состояние —
# файл на диске по ключу набора параметров: воркеров два, и спросить о ходе
# расчёта можно не у того, кто его ведёт. Тот же файл — кэш: одинаковые
# параметры второй раз калькулятор не гоняют.
_GLAVAPU_SCENARIO_CACHE_SECONDS = max(0.0, _env_float("GLAVAPU_SCENARIO_CACHE_SECONDS", 21600.0))
# Отказ помнится минутами: он про «калькулятор не дался в ту минуту», а не
# про набор параметров.
_GLAVAPU_SCENARIO_ERROR_SECONDS = max(0.0, _env_float("GLAVAPU_SCENARIO_ERROR_SECONDS", 300.0))
# Задание, чей воркер умер (перезапуск), не должно числиться идущим вечно.
_GLAVAPU_SCENARIO_STALE_SECONDS = max(
    60.0, _GLAVAPU_HEADLESS_QUEUE_SECONDS + 3 * _GLAVAPU_HEADLESS_TIMEOUT_MS / 1000.0 + 60.0)
_GLAVAPU_SCENARIO_LOCK = threading.Lock()


class GlavapuScenarioRequest(BaseModel):
    """Сценарий проекта для сверки: те же вводные и ТЭП, что держит страница."""
    inputs: dict[str, Any] = {}
    tep: dict[str, Any] = {}
    cadastral_numbers: str | list[str] = ""
    # Только спросить состояние, не ставя задание (опрос страницы).
    poll: bool = False
    # Пересчитать, даже если ответ в кэше свежий.
    force: bool = False


def _glavapu_scenario_dir() -> Path:
    return Path(os.getenv("DEVELOPAID_DATA_DIR") or "data") / "glavapu-scenario"


_GLAVAPU_SCENARIO_KEY = re.compile(r"[0-9a-f]{8,40}")


def _glavapu_scenario_file(key: str) -> Path:
    """Файл задания. Ключ приходит и из адреса запроса, поэтому он обязан быть
    ровно хэшем `scenario_key`, а путь — лежать внутри каталога заданий."""
    key = str(key or "")
    if not _GLAVAPU_SCENARIO_KEY.fullmatch(key):
        raise ValueError("ключ сверки — шестнадцатеричный хэш набора параметров")
    base = os.path.normpath(os.path.abspath(_glavapu_scenario_dir()))
    path = os.path.normpath(os.path.join(base, key + ".json"))
    if not path.startswith(base + os.sep):
        raise ValueError("ключ сверки выводит за каталог заданий")
    return Path(path)


def _glavapu_scenario_load(key: str) -> dict[str, Any] | None:
    try:
        data = json.loads(_glavapu_scenario_file(key).read_text(encoding="utf-8"))
    except Exception:
        return None
    return data if isinstance(data, dict) else None


def _glavapu_scenario_save(key: str, record: dict[str, Any]) -> None:
    path = _glavapu_scenario_file(key)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(f".{os.getpid()}.tmp")
    tmp.write_text(json.dumps(record, ensure_ascii=False, default=str), encoding="utf-8")
    tmp.replace(path)


def _glavapu_scenario_product(key: str) -> str:
    obj = _BY_KEY.get(key)
    return obj.product if obj is not None else key


def _glavapu_scenario_build(req: GlavapuScenarioRequest) -> dict[str, Any]:
    # Участок проекта — у одного владельца: номер, вписанный в поле, найденный
    # через ЕГРН или посчитанный «Получить ТЭП», равноправны. Прежде сверка
    # читала только расчёт ТЭП и отказывала проекту, у которого номер вписан.
    numbers = _parse_cadastral_numbers(req.cadastral_numbers) if req.cadastral_numbers else []
    if not numbers:
        numbers = _project_cadastral_numbers(req.inputs or {})
    return glavapu_scenario.build_scenario(
        req.inputs or {}, req.tep or {}, product_of=_glavapu_scenario_product, numbers=numbers)


def _glavapu_scenario_ours(inputs: dict[str, Any], tep: dict[str, Any],
                           scenario: dict[str, Any]) -> tuple[dict[str, Any], dict[str, str]]:
    """Наша сторона сверки — из тех же владельцев, что считают модель.

    Нормы мест, соцпотребности и МПТ — `tep_derived_norms` (её ответ подписан
    как наш расчёт по городским формулам), приобъектные места — `parking_demand`,
    плата за ВРИ — поле проекта. Своей формулы сверка не заводит: второй ответ
    на тот же вопрос был бы третьим мнением, а не проверкой.
    """
    inputs = inputs or {}
    tep = tep or {}
    params = scenario.get("params") or {}
    normalized = (inputs.get("_glavapu_import") or {}).get("normalized") or {}
    living = sum(n(tep.get(k) or {}, "gns") for k in glavapu_scenario.RESIDENTIAL_LIVING_KEYS)
    built_in = n(tep.get(glavapu_scenario.RESIDENTIAL_NONRES_KEY) or {}, "gns")
    social_gns = sum(n(tep.get(k) or {}, "gns") for k in glavapu_scenario.SOCIAL_KINDS)
    skip = (set(glavapu_scenario.RESIDENTIAL_LIVING_KEYS) | set(glavapu_scenario.SOCIAL_KINDS)
            | {glavapu_scenario.RESIDENTIAL_NONRES_KEY} | set(glavapu_scenario.NOT_SPP_KEYS))
    nonres_gns = sum(n(row, "gns") for key, row in tep.items()
                     if key not in skip and isinstance(row, dict))
    nonres_np = sum(n(row, "total_area") for key, row in tep.items()
                    if key not in skip and isinstance(row, dict))
    total = living + built_in + nonres_gns + social_gns
    area = float(params.get("area_ha") or 0.0)
    apartments = tep.get("apartments") or {}
    demand = parking_demand(inputs, tep)
    derived = tep_derived_norms(
        apartment_area_sqm=n(apartments, "saleable"),
        residential_living_spp_sqm=n(apartments, "gns"),
        nonresidential_np_sqm=nonres_np + n(tep.get("ground_commercial") or {}, "total_area"),
        k1=float(demand.get("k1") or 1.0), k2=float(demand.get("k2") or 1.0),
        zone_two=str(normalized.get("calculation_zone") or "").strip() == "2",
        apartment_count=n(apartments, "units"))
    tep_src = "ТЭП проекта, ГНС"
    norm_src = "наша норма (tep_derived_norms)"
    ours: dict[str, Any] = {
        "spp": {
            "total": (round(total / 1000.0, 3), tep_src + ": все наземные строки"),
            "residential_living": (round(living / 1000.0, 3), tep_src + ": «Квартиры» + «Кладовые»"),
            "built_in": (round(built_in / 1000.0, 3), tep_src + ": «Коммерция 1 этажа»"),
            "nonres": (round(nonres_gns / 1000.0, 3), tep_src + ": нежилые объекты"),
            "social": (round(social_gns / 1000.0, 3), tep_src + ": ДОО, СОШ, поликлиника"),
        },
        "social": {
            "population": (derived["population"], norm_src + ": площадь квартир / 33 м²"),
            "kindergarten": (derived["kindergarten_places"], norm_src),
            "school": (derived["school_places"], norm_src),
            "clinic": (derived["clinic_capacity"], norm_src),
        },
        "parking": {
            "permanent": (derived["parking_permanent"], norm_src + ": " + derived["parking_basis"]),
            "guest": (derived["parking_guest"], norm_src + ": десятая часть постоянных"),
            "attached": (int(demand.get("required_total") or 0),
                         "наша норма приобъектных (parking_demand, 945-ПП)"),
            "short_stop": (None, ""),
        },
        "mpt": (derived["jobs"], norm_src + f": НП нежилья / {derived['sqm_per_job']:g} м²"),
        "density": (round(total / 1000.0 / area, 3) if area > 0 else None,
                    "ТЭП проекта: СПП / площадь территории"),
    }
    vri_value: float | None = None
    vri_origin = ""
    if inputs.get("vri_required") in (False, 0, "0", "false"):
        vri_value, vri_origin = 0.0, "вводные проекта: смена ВРИ не требуется"
    elif inputs.get("land_rights_cost_mln") not in (None, ""):
        vri_value = float(n(inputs, "land_rights_cost_mln"))
        imported = ((inputs.get("_glavapu_import") or {}).get("mappings") or {}).get("inputs") or {}
        if ("land_rights_cost_mln" in imported
                and abs(float(imported.get("land_rights_cost_mln") or 0.0) - vri_value) < 0.001):
            vri_origin = ("вводные проекта — число из выгрузки ГлавАПУ с ЕГО умолчаниями, "
                          "не наш расчёт")
        else:
            vri_origin = "вводные проекта: land_rights_cost_mln"
    ours["vri_cost_mln"] = (vri_value, vri_origin)

    # Наша льгота по плате за ВРИ — одна сумма (доля или фиксированная) из
    # вводных, тем же `vri_relief`, что считает модель. Режим «нет» — это не
    # «льгота ноль», а «льгота не задана»: сверке не с чем сравнивать.
    relief_mode = str(inputs.get("vri_relief_mode") or "none").strip().lower()
    relief_value: float | None = None
    if vri_value is not None and relief_mode in ("percent", "amount"):
        relief_value = round(vri_relief({k: v for k, v in inputs.items()
                                         if k != "vri_transfer_offset_mln"},
                                        vri_value * 1_000_000)[0] / 1_000_000, 3)
    ours["vri_relief"] = {"total": (relief_value,
                                    f"вводные проекта: vri_relief_mode = {relief_mode}"
                                    if relief_value is not None else "")}
    ours["vri_net_mln"] = ((round(vri_value - (relief_value or 0.0), 3), "плата проекта за вычетом нашей льготы")
                           if vri_value is not None else (None, ""))

    imported = ((inputs.get("_glavapu_import") or {}).get("mappings") or {}).get("inputs") or {}

    def from_import(key: str, value: float) -> bool:
        return (key in imported
                and abs(float(imported.get(key) or 0.0) - value) < 0.001)

    # Соцнагрузка деньгами: у проекта одна сумма; по объектам — справочно.
    comp_value: float | None = None
    comp_origin = ""
    if inputs.get("social_compensation_mln") not in (None, ""):
        comp_value = float(n(inputs, "social_compensation_mln"))
        comp_origin = ("вводные проекта — число из выгрузки ГлавАПУ с ЕГО умолчаниями"
                       if from_import("social_compensation_mln", comp_value)
                       else "вводные проекта: social_compensation_mln")
    ours["social_comp"] = {"total": (comp_value, comp_origin)}

    # Машино-места по ВРИ, все виды. Приобъектные — строки той же нормы
    # `parking_demand`, что дала общий итог (объект → ВРИ по карте
    # NONRES_VRI); постоянные и гостевые МКД — `tep_derived_norms`. Мест
    # остановки модель не считает — их строки остаются без нашей величины, и
    # «всего» по ВРИ не собирается: сумма без них была бы неполной, а не нашей.
    extra: dict[str, str] = {}
    by_vri: dict[str, list[Any]] = {}
    for row in demand.get("rows") or []:
        key = str(row.get("tep_key") or "")
        if key == glavapu_scenario.RESIDENTIAL_NONRES_KEY:
            kind = "built_in"
        else:
            target = glavapu_scenario.NONRES_VRI.get(_glavapu_scenario_product(key))
            if not target:
                continue
            kind = target[1]
        slot = by_vri.setdefault(kind, [0, []])
        slot[0] += int(row.get("required_spaces") or 0)
        slot[1].append(str(row.get("label") or key))
    ours["parking_vri"] = {f"{kind}.attached": (value, "наша норма (parking_demand): " + ", ".join(names))
                           for kind, (value, names) in by_vri.items()}
    ours["parking_vri"]["2_1_1.permanent"] = ours["parking"]["permanent"]
    ours["parking_vri"]["2_1_1.guest"] = ours["parking"]["guest"]
    for code in {kind.split(".", 1)[0] for kind in ours["parking_vri"]}:
        extra[f"parking_vri.{code}.total"] = (
            "«всего» по ВРИ у нас не собирается: мест кратковременной остановки модель "
            "не считает, и сумма без них была бы неполной — виды сверяются по строкам ниже")
        extra[f"parking_vri.{code}.short_stop"] = (
            "мест кратковременной остановки модель не считает: они не строятся в "
            "гараже (945-ПП п. 6.1.2), а потребность в них показана калькулятором")

    # Соцобъекты, которые поставил калькулятор, против строк ТЭП проекта.
    ours["social_obj"] = {}
    for key in glavapu_scenario.SOCIAL_KINDS:
        row = tep.get(key)
        if not isinstance(row, dict) or n(row, "gns") <= 0:
            continue
        label = glavapu_scenario._label(tep, key)
        ours["social_obj"][f"{key}.places"] = (n(row, "units") or None, f"ТЭП проекта: «{label}», места")
        ours["social_obj"][f"{key}.spp"] = (round(n(row, "gns") / 1000.0, 3), f"ТЭП проекта: «{label}», ГНС")
        if n(row, "total_area") > 0:
            ours["social_obj"][f"{key}.np"] = (round(n(row, "total_area") / 1000.0, 3),
                                               f"ТЭП проекта: «{label}», общая площадь")
        extra[f"social_obj.{key}.site"] = ("участка соцобъекта модель не ведёт — показано, "
                                             "сколько земли под него взял калькулятор")
        for field in ("spp", "np"):
            extra[f"social_obj.{key}.{field}"] = (
                f"калькулятор ставит типовое здание (лист «Социальные объекты»), у нас — «{label}» "
                "из ТЭП; площадь здания калькулятор берёт свою")
        extra[f"social_obj.{key}.places"] = (
            f"сценарий передаёт {glavapu_scenario._ru(n(row, 'units'))} мест «{label}», а "
            "калькулятор поставил своё типовое здание — его мощность из списка типовых, "
            "а не наше число (см. «Калькулятор не принял»)")

    # Обслуживание: своих норм на эти объекты у модели нет. Проверяется
    # запас — покрывает ли встроенная коммерция ННП торговли, быта, общепита,
    # культуры и городских служб, а ФОК — крытый спорт.
    built_in_np = n(tep.get(glavapu_scenario.RESIDENTIAL_NONRES_KEY) or {}, "total_area")
    ours["service"] = {"commerce_need": (
        round(built_in_np / 1000.0, 3) if built_in_np > 0 else None,
        "ТЭП проекта: «Коммерция 1 этажа», общая площадь")}
    sports = [(key, row) for key, row in tep.items() if isinstance(row, dict)
              and _glavapu_scenario_product(key) == "sports" and n(row, "total_area") > 0]
    if sports:
        ours["service"]["sport_indoor"] = (
            round(sum(n(row, "total_area") for _, row in sports) / 1000.0, 3),
            "ТЭП проекта: " + ", ".join(f"«{glavapu_scenario._label(tep, k)}»" for k, _ in sports))
    else:
        extra["service.sport_indoor"] = ("ФОК в ТЭП проекта нет — крытый спорт, который "
                                           "требует калькулятор, нечем покрыть")
    if built_in_np <= 0:
        extra["service.commerce_need"] = ("встроенной коммерции в ТЭП проекта нет — "
                                            "обслуживание квартала нечем покрыть")

    # Озеленённые территории ЖК (город: 5,0 м² на жителя) против площади
    # нашего двора — той, что считает благоустройство.
    yard_sqm, yard_basis = landscaping_area(inputs, tep)
    ours["territory"] = {"green_zhk": (round(yard_sqm / 10000.0, 4) if yard_sqm > 0 else None,
                                       "наш двор (landscaping_area): " + yard_basis)}
    extra["territory.green_zhk"] = (
        "наш двор — площадь благоустройства по ставке класса; город (2152-ПП) требует "
        "5,0 м² озеленённых территорий ЖК на жителя, из них 3,5 — насаждения"
        if yard_sqm > 0 else "площадь двора в проекте не посчитана: " + yard_basis)

    # Квартиры: всего и по размерам (если состав задан вводными).
    units = n(apartments, "units")
    ours["flats"] = {"total": (round(units) if units > 0 else None, "ТЭП проекта: «Квартиры», шт.")}
    mix = inputs.get("apartment_mix") if isinstance(inputs.get("apartment_mix"), dict) else {}
    for size in ("small", "medium", "large"):
        if mix.get(size) not in (None, ""):
            ours["flats"][size] = (n(mix, size), "вводные проекта: apartment_mix")
    average = n(apartments, "saleable") / units if units > 0 else 0.0
    extra["flats.total"] = ("калькулятор считает квартиры от населения (2,1 чел. на квартиру), "
                              "мы — штуками ТЭП")
    if not mix:
        for size in ("small", "medium", "large"):
            extra[f"flats.{size}"] = (
                "состава квартир по размерам в модели нет"
                + (f"; средняя квартира {average:,.1f} м²".replace(",", " ").replace(".", ",")
                   if average > 0 else ""))

    # Параметры территории: то, от чего считают наши нормы и плата.
    analysis_src = "выгрузка ГлавАПУ, принятая в проект"
    numbers = scenario.get("numbers") or []
    quarter = numbers[0].rsplit(":", 1)[0] if numbers and numbers[0].count(":") >= 3 else None
    zone = str(normalized.get("calculation_zone") or "").strip()
    zone_key = "2" if zone == "2" else "1"
    norms = SOCIAL_NORMS_PER_1000
    ours["params"] = {
        "k1": (float(demand.get("k1") or 0.0) or None,
               "наша норма приобъектных (parking_demand): "
               + str((demand.get("k_origin") or {}).get("k1") or "К1 вводных")),
        "k2": (float(demand.get("k2") or 0.0) or None,
               "наша норма приобъектных (parking_demand): "
               + str((demand.get("k_origin") or {}).get("k2") or "К2 вводных")),
        "district": (normalized.get("district") or None, analysis_src),
        "zone": (zone or None, analysis_src),
        "kindergarten_norm": (norms["kindergarten"][zone_key],
                              f"наша норма (SOCIAL_NORMS_PER_1000), зона {zone_key}"),
        "school_norm": (norms["school"][zone_key], f"наша норма (SOCIAL_NORMS_PER_1000), зона {zone_key}"),
        "quarter": (quarter, "кадастровые номера сценария"),
        "rent": (normalized.get("rent_coefficient"), analysis_src),
        "mpt_coef": (None, ""),
    }
    for use, value in (normalized.get("vri_upks_by_use") or {}).items():
        ours["params"][f"upks_{use}"] = (value, analysis_src)
    for use, value in (normalized.get("vri_base_costs_by_use") or {}).items():
        ours["params"][f"base_{use}"] = (value, analysis_src)
    if not zone:
        extra["params.zone"] = ("расчётной зоны в проекте нет — наша норма соцобъектов "
                                  "считает по зоне 1")
    for kind, key in (("district", "district"), ("rent", "rent_coefficient")):
        if normalized.get(key) in (None, ""):
            extra[f"params.{kind}"] = ("в проекте нет принятой выгрузки ГлавАПУ по участку "
                                       "— параметр квартала не задан")
    k_src = demand.get("k_origin") or {}
    extra["params.k1"] = ("наша норма приобъектных берёт К1 "
                          + (str(k_src.get("k1")) if k_src.get("k1") else
                             "вводных; не задан — верхний край 1,0")
                          + "; калькулятор — по участку (анализ ГлавАПУ)")
    extra["params.k2"] = ("К2 зависит от положения участка относительно ТТК: калькулятор "
                          "берёт своё (" + str(normalized.get("parking_k2_label") or "по анализу")
                          + "); наша норма — " + (str(k_src.get("k2")) if k_src.get("k2") else
                                                  "К2 вводных; не задан — верхний край 1,0"))

    reasons: dict[str, str] = {
        "parking.short_stop": ("в модели нет нормы мест кратковременной остановки: "
                               "они не строятся в гараже (945-ПП п. 6.1.2), сверка справочная"),
        "parking.attached": ("наша норма — от общей площади нежилья с К1 "
                             f"{float(demand.get('k1') or 0):g} и К2 {float(demand.get('k2') or 0):g}; "
                             "калькулятор считает по ВРИ, НП и К1/К2 своего квартала"),
        "mpt": (f"у модели {derived['sqm_per_job']:g} м² НП на рабочее место; "
                "калькулятор считает по ВРИ (лист «МПТ»)"),
        "parking.guest": ("гостевые — десятая часть постоянных и у нас, и у калькулятора: "
                          "расхождение идёт от постоянных мест"),
        "parking.permanent": ("наша норма: " + derived["parking_basis"]
                              + "; калькулятор — от своей площади квартир (строка 10)"),
    }
    relief_basis = ("калькулятор даёт льготу за МПТ сам: нежилые ВРИ выше порога × "
                    "коэффициент места (офисы и торговля вне ТТК 0,7, внутри 0; соцобъекты 0,3); "
                    "срезает только плату за МКД. Его Кзатр — база 2026 года 166,23078 ещё раз "
                    "× 1,2036 (= 166,23078 / 138,11132, переход с базы 2025 года) × индекс "
                    "квартала: на ~20% выше приказа, по которому считаем мы")
    reasons["vri_relief.total"] = (
        "наша льгота — доля или сумма из вводных; " + relief_basis if relief_value is not None
        else "в проекте льгота по плате за ВРИ не задана (vri_relief_mode = «нет»); "
             + relief_basis + " — проверить основание (3135-ПП)")
    reasons["vri_net_mln"] = ("к оплате = до льгот − льгота; расхождение складывается из "
                              "двух строк выше" if vri_value is not None else
                              reasons.get("vri_cost_mln", ""))
    if comp_value is not None:
        reasons["social_comp.total"] = (
            ("наше число — выгрузка ГлавАПУ с его умолчаниями, а не наш сценарий; "
             if comp_origin.startswith("вводные проекта — число из выгрузки") else "")
            + "калькулятор считает компенсацию от дефицита мест по нашему сценарию: "
              "объект, построенный сверх потребности, компенсацию не требует, а его "
              "лишние места вычитаются из дефицита других объектов (итог не меньше нуля)")
    else:
        reasons["social_comp.total"] = ("в проекте не задана компенсация за соцобъекты "
                                        "(social_compensation_mln) — сравнить не с чем")
    for kind in ours["parking_vri"]:
        column = kind.rsplit(".", 1)[-1]
        reasons[f"parking_vri.{kind}"] = reasons["parking." + column]
    reasons.update(extra)
    garage = tep.get("underground_parking") or {}
    if n(garage, "units") > 0:
        reasons["parking.permanent"] += (
            f"; в подземном гараже модели {n(garage, 'units'):,.0f} мест".replace(",", " "))
    for item in scenario.get("not_sent") or []:
        if str(item.get("param") or "").startswith("nonres."):
            for kind in ("spp.nonres", "spp.total", "density"):
                reasons[kind] = (reasons.get(kind, "") + "; " if reasons.get(kind) else "") + item["reason"]
    for item in params.get("social") or []:
        gns_text = f"{item['spp_ths'] * 1000:,.0f}".replace(",", " ")
        line = (f"{item['label']}: калькулятор ставит типовой объект своей площади, "
                f"у нас ГНС {gns_text} м²")
        for kind in ("spp.social", "spp.total", "density"):
            reasons[kind] = (reasons.get(kind, "") + "; " if reasons.get(kind) else "") + line
    population = derived["population"]
    for kind in ("social.population", "social.kindergarten", "social.school", "social.clinic"):
        reasons.setdefault(kind, f"наша норма: население {population} = площадь квартир / 33 м²; "
                                 "калькулятор — от своей площади квартир (строка 10)")
    if vri_origin.startswith("вводные проекта — число из выгрузки"):
        reasons["vri_cost_mln"] = ("наше число — выгрузка ГлавАПУ с его умолчаниями, а не "
                                   "наш сценарий; расхождение показывает, сколько стоит "
                                   "сценарий по калькулятору")
    elif vri_value == 0.0 and vri_origin:
        reasons["vri_cost_mln"] = vri_origin
    elif vri_value is None:
        reasons["vri_cost_mln"] = ("в проекте не задана плата за смену ВРИ "
                                   "(land_rights_cost_mln) — сравнить не с чем")
    else:
        reasons.setdefault("vri_cost_mln", "плата проекта задана вводными, калькулятор считает "
                                           "её от СПП по ВРИ и УПКС квартала")
    return ours, reasons


def _glavapu_scenario_run(key: str, scenario: dict[str, Any]) -> None:
    """Задание браузера: выставить сценарий, забрать книгу, записать ответ."""
    started = time.monotonic()
    record = _glavapu_scenario_load(key) or {}
    record.update(state="running", started_at=datetime.now(timezone.utc).isoformat(),
                  worker=os.getpid())
    _glavapu_scenario_save(key, record)
    try:
        params = scenario["params"]
        holder = _glavapu_headless_run(scenario["numbers"], float(params["area_ha"]), params)
        data = holder.get("scenario_xlsx") or b""
        parsed = parse_glavapu_xlsx(data, "glavapu-scenario.xlsx") if data else {}
        side = glavapu_scenario.glavapu_side(parsed.get("normalized") or {},
                                             holder.get("scenario_rows") or {}, data)
        record.update(state="done", glavapu=side,
                      applied=holder.get("scenario_report") or {},
                      warnings=parsed.get("warnings") or [],
                      timings=holder.get("timings") or {})
        _GLAVAPU_HEADLESS["last_ok"] = datetime.now().isoformat(timespec="seconds")
    except (GlavapuTableNotReady, GlavapuParcelNotAccepted) as exc:
        record.update(state="error", error=exc.public_message,
                      where="калькулятор ГлавАПУ: расчёт участка до ввода сценария")
    except Exception as exc:  # noqa: BLE001 — отказ доходит до окна с местом
        record.update(state="error", error=_public_error(exc, "glavapu scenario"),
                      where=_error_location(exc))
    record["finished_at"] = datetime.now(timezone.utc).isoformat()
    record["seconds"] = round(time.monotonic() - started, 1)
    record["stored_at"] = time.time()
    _glavapu_scenario_save(key, record)


def _glavapu_project_region(inputs: dict[str, Any]) -> tuple[str, str]:
    """Регион проекта — поле «Регион» (`class_region`), то же правило, что
    `projectRegion` страницы. Кадастровый номер регион не задаёт: у Новой
    Москвы — Новомосковского и Троицкого округов (НАО, ТАО) — номера
    областные: 50:21, 50:26, 50:27."""
    return class_region(inputs), "поле «Регион» проекта"


def _glavapu_scenario_fresh(record: dict[str, Any] | None) -> bool:
    if not record:
        return False
    age = time.time() - float(record.get("stored_at") or 0.0)
    state = record.get("state")
    if state == "done":
        return age <= _GLAVAPU_SCENARIO_CACHE_SECONDS
    if state == "error":
        return age <= _GLAVAPU_SCENARIO_ERROR_SECONDS
    if state in ("queued", "running"):
        return age <= _GLAVAPU_SCENARIO_STALE_SECONDS
    return False


@app.post("/glavapu/scenario")
def glavapu_scenario_check(req: GlavapuScenarioRequest) -> dict[str, Any]:
    """Сверка «наше / ГлавАПУ»: ставит задание и отвечает его состоянием.

    Ответ сразу: `queued`/`running` — браузер работает, спросить ещё раз;
    `done` — числа калькулятора и сверка; `error`/`unavailable` — причина и
    место. Тяжёлая работа идёт в фоне, окно и бот её не ждут.
    """
    url = _core_api_url("/glavapu/scenario")
    if url:
        # Браузер живёт на ядре, как и для расчёта ТЭП.
        forwarded = _core_post(url, _core_forward_payload(req), 30.0)
        forwarded.setdefault("route", "ядро")
        return forwarded
    scenario = _glavapu_scenario_build(req)
    key = glavapu_scenario.scenario_key(scenario)
    ours, reasons = _glavapu_scenario_ours(req.inputs or {}, req.tep or {}, scenario)
    answer: dict[str, Any] = {"key": key, "role": glavapu_scenario.ROLE,
                              "scenario": scenario, "ours": ours}
    region, region_origin = _glavapu_project_region(req.inputs or {})
    if region != "msk":
        # Калькулятор ГлавАПУ — московский: в проекте области он не участвует
        # ни подстановкой, ни сверкой (владелец, 06.10.2026).
        answer.update(state="refused",
                      error="проект не московский — калькулятор ГлавАПУ в нём не участвует",
                      where=f"регион проекта: {region_origin}")
        return answer
    if scenario["problems"]:
        answer.update(state="refused", error="; ".join(scenario["problems"]),
                      where="сценарий проекта (наши вводные и ТЭП), до калькулятора")
        return answer
    if not scenario["numbers"]:
        normalized = ((req.inputs or {}).get("_glavapu_import") or {}).get("normalized") or {}
        quarter = str(normalized.get("cadastral_quarter") or "").strip()
        missing = (f"у проекта есть только кадастровый квартал {quarter}, а калькулятор "
                   "ГлавАПУ берёт номер участка (вида 77:05:0004001:1234), не квартал"
                   if quarter else
                   "у проекта нет кадастрового номера участка, а калькулятору он нужен, "
                   "чтобы взять район, квартал и коэффициенты")
        answer.update(state="refused",
                      error=missing + ". Впишите номер в поле «Участок» на вкладке вводных "
                                      "(блок «Автозагрузка исходных данных») и повторите",
                      where="участок проекта (_project_cadastral_numbers): поле участка, "
                            "поиск ЕГРН, расчёт ТЭП по номеру — номеров нет")
        return answer
    with _GLAVAPU_SCENARIO_LOCK:
        record = _glavapu_scenario_load(key)
        if req.force and record and record.get("state") in ("done", "error"):
            record = None
        if not _glavapu_scenario_fresh(record):
            record = None
            if not req.poll:
                if not _glavapu_headless_available():
                    state = _glavapu_headless_state()
                    answer.update(state="unavailable",
                                  error=f"штатный калькулятор: {state.get('state')}",
                                  where=str(state.get("where") or ""),
                                  hint=str(state.get("hint") or state.get("last_error") or ""))
                    return answer
                record = {"state": "queued", "stored_at": time.time(),
                          "queued_at": datetime.now(timezone.utc).isoformat()}
                _glavapu_scenario_save(key, record)
                threading.Thread(target=_glavapu_scenario_run, args=(key, scenario),
                                 name=f"glavapu-scenario-{key[:8]}", daemon=True).start()
    if record is None:
        answer.update(state="none", error="задание не найдено — запустите сверку")
        return answer
    answer.update({k: v for k, v in record.items() if k not in ("stored_at",)})
    if record.get("state") == "done":
        answer["comparison"] = glavapu_scenario.compare(
            ours, record.get("glavapu") or {}, reasons, record.get("applied"))
    return answer


@app.get("/glavapu/scenario/{key}")
def glavapu_scenario_state(key: str) -> dict[str, Any]:
    """Запись задания как есть — для оператора: что ставили, что принято, где отказ."""
    url = _core_api_url(f"/glavapu/scenario/{key}")
    if url:
        try:
            with urllib.request.urlopen(url, timeout=15) as response:
                return json.loads(response.read().decode("utf-8"))
        except Exception as exc:
            raise HTTPException(status_code=502,
                                detail="Ядро не ответило: " + _public_error(exc, "scenario state"))
    if not _GLAVAPU_SCENARIO_KEY.fullmatch(str(key or "")):
        raise HTTPException(status_code=400,
                            detail="Ключ сверки — шестнадцатеричный хэш из ответа /glavapu/scenario")
    record = _glavapu_scenario_load(key)
    if record is None:
        raise HTTPException(status_code=404, detail="Задания сверки с таким ключом нет")
    return record


def _cadastral_analysis_for(numbers: list[str],
                            supplied: dict[str, Any] | None) -> dict[str, Any]:
    """Территория запрошенных участков — присланная страницей или своя.

    Страница собирает территорию перед расчётом ТЭП и держит её в руках; тот же
    вопрос ГлавАПУ второй раз за один клик стоил внешнего запроса на ровном
    месте. Принимается присланная территория только тех участков, что запрошены:
    иначе ТЭП посчитался бы по чужим коэффициентам, выглядя безупречно.
    """
    if isinstance(supplied, dict):
        recognized = {str(x).strip() for x in (supplied.get("recognized") or [])}
        coefficients = supplied.get("coefficients") or {}
        area = float((supplied.get("territory") or {}).get("area_ha") or 0.0)
        if recognized == {str(x).strip() for x in numbers} and coefficients and area > 0:
            return supplied
    return analyze_cadastral_territory(
        CadastralAnalysisRequest(cadastral_numbers=numbers))


@app.post("/cadastral/tep-server")
def cadastral_tep_server(req: CadastralAnalysisRequest) -> dict[str, Any]:
    """ТЭП по формулам ГлавАПУ, посчитанный сервером.

    Штатный путь гоняет настоящий калькулятор в скрытом iframe браузера —
    Telegram WebView этого не тянет, и сбор падал по таймауту: сайт собирал
    ТЭП, мини-приложение нет. Формулы калькулятора сняты с его кода и
    сходятся с контрольными выгрузками до единицы, поэтому серверный расчёт —
    равноценная замена, а не суррогат."""
    numbers = _parse_cadastral_numbers(req.cadastral_numbers)
    request_started = time.monotonic()
    logging.info("tep-server rid=%s numbers=%s analysis=%s headless=%s",
                 req.request_id or "-", ", ".join(numbers),
                 "прислана" if req.cadastral_analysis else "нет",
                 "готов" if _glavapu_headless_available() else "недоступен")

    # Расчёт уходит на ядро — тем же путём, что и анализ территории. Браузер
    # для штатного калькулятора живёт там: на ядре свой образ, четыре гигабайта
    # и нет засыпания, а Render к тому же не наш Dockerfile. На самом ядре
    # адрес пуст, и пересылать некуда — там считаем.
    if _core_api_url("/cadastral/tep-server"):
        try:
            forwarded = _core_post(
                _core_api_url("/cadastral/tep-server"),
                _core_forward_payload(req),
                _MO_CALC_TIMEOUT_SECONDS,
            )
            logging.info("tep-server rid=%s ядро ответило за %.1f с",
                         req.request_id or "-", time.monotonic() - request_started)
            return forwarded
        except Exception as exc:
            # Ядро не ответило — считаем здесь формулами, как раньше.
            logging.warning("tep-server core forward failed: %s", exc)

    # Сначала — настоящий калькулятор. Формулы остаются фолбэком: копия
    # методики отстаёт от города на неизвестный срок, и это уже дважды
    # находил человек на скриншотах, а не мы.
    # Тот же участок, посчитанный настоящим калькулятором час назад, — это тот
    # же ТЭП. Браузер поднимать незачем.
    if _glavapu_headless_available() and numbers:
        # Браузер на ходу — запасной ответ из памяти не годится: он отвечал бы
        # за калькулятор, который снова работает.
        cached = _glavapu_tep_cached(numbers, want_calculator=True)
        if cached is not None:
            logging.info("tep-server rid=%s из кэша", req.request_id or "-")
            return cached

    if _glavapu_headless_available() and numbers:
        try:
            started = time.monotonic()
            analysis = _cadastral_analysis_for(numbers, req.cadastral_analysis)
            area = float((analysis.get("territory") or {}).get("area_ha") or 0.0)
            rows = _glavapu_headless_rows(numbers, area)
            imported = import_cadastral_tep(CadastralTepRequest(
                rows=rows, cadastral_analysis=analysis))
            _GLAVAPU_HEADLESS["runs"] += 1
            _GLAVAPU_HEADLESS["last_ok"] = datetime.now().isoformat(timespec="seconds")
            _GLAVAPU_HEADLESS["last_error"] = ""
            _GLAVAPU_HEADLESS_BLOCKED_UNTIL["at"] = 0.0
            # Удавшийся расчёт сбрасывает и лестницу: связка ожила, и следующий
            # одиночный срыв снова стоит пять минут, а не полчаса.
            _GLAVAPU_HEADLESS_BLOCKED_UNTIL["row"] = 0
            _glavapu_health_save()
            imported.setdefault("source", {}).update({
                "format": "Штатный калькулятор ГлавАПУ — серверный запуск",
                "cadastral_numbers": numbers,
                "calculated_at": date.today().isoformat(),
                "headless": {"state": "готов", "where": "ядро"},
            })
            logging.info("tep-server rid=%s готов за %.1f с",
                         req.request_id or "-", time.monotonic() - started)
            _glavapu_tep_store(numbers, imported)
            return imported
        except Exception as exc:
            _GLAVAPU_HEADLESS["fallbacks"] += 1
            # Первая строка сообщения Playwright называет виновника прямо:
            # «<div id="react-joyride-portal"> intercepts pointer events» —
            # без неё причина срыва читалась только из логов контейнера.
            _reason = str(exc).strip().splitlines()
            _GLAVAPU_HEADLESS["last_error"] = (
                f"{datetime.now().isoformat(timespec='seconds')}: {_error_location(exc)}"
                + (f" — {_reason[0][:200]}" if _reason else ""))
            _glavapu_health_save()
            _glavapu_headless_failed()
            logging.warning("glavapu headless failed, falling back for %ds: %s",
                            int(_GLAVAPU_HEADLESS_COOLDOWN_SECONDS), exc)

    # Формулы тоже помнятся: пока штатный калькулятор недоступен, повторный
    # расчёт того же участка не должен снова ходить к ГлавАПУ за территорией.
    cached_formulas = _glavapu_tep_cached(numbers) if numbers else None
    if cached_formulas is not None:
        logging.info("tep-server rid=%s формулы из кэша", req.request_id or "-")
        return cached_formulas

    # Территория для формул: присланная страницей идёт без сети вовсе. Если её
    # нет и спросить не у кого — не роняем расчёт, формулы спросят сами.
    formulas_analysis = None
    if numbers:
        try:
            formulas_analysis = _cadastral_analysis_for(numbers, req.cadastral_analysis)
        except Exception as exc:
            logging.info("tep-server: территорию для формул взять не удалось: %s", exc)
    quick = vri_tep_quick("msk", ", ".join(numbers), analysis=formulas_analysis)
    result = parse_glavapu_xlsx(quick["file"], quick["filename"])
    result["source"].update({
        "format": "Формулы калькулятора ГлавАПУ — серверный расчёт DevelopAid",
        "cadastral_numbers": numbers,
        "calculated_at": date.today().isoformat(),
    })
    headless_state = _glavapu_headless_state()
    result["source"]["headless"] = headless_state
    result["warnings"].insert(
        0,
        "ТЭП посчитан серверными формулами ГлавАПУ: штатный калькулятор "
        f"недоступен ({headless_state['state']}, {headless_state['where']}). "
        + str(headless_state.get("hint") or "")
        + " Формулы сняты с его кода и сходятся с контрольными выгрузками до "
        "единицы, но методику город меняет — расчёт штатного калькулятора имеет "
        "приоритет."
        # Текст срыва (первая строка Playwright и место в коде) в ответ
        # расчёта не кладётся: это внутренности сервера, и видит их любой,
        # кто считает ТЭП. Он лежит в состоянии связки — /glavapu/health и
        # /status бота, — и здесь сказано, где его смотреть.
        + (" Последняя ошибка запуска записана в состоянии связки: "
           "/glavapu/health (в боте — /status)."
           if _GLAVAPU_HEADLESS.get("last_error") else ""),
    )
    if _GLAVAPU_FORMULA_DRIFT["items"]:
        result["warnings"].insert(
            0,
            "ВНИМАНИЕ: серверные формулы разошлись со штатным калькулятором "
            "(" + "; ".join(_GLAVAPU_FORMULA_DRIFT["items"][:4]) + "). "
            "Методика ГлавАПУ могла измениться — сверьте расчёт на сайте.",
        )
    if numbers:
        _glavapu_tep_store(numbers, result, is_fallback=True)
    logging.info("tep-server rid=%s формулы за %.1f с", req.request_id or "-",
                 time.monotonic() - request_started)
    return result


def _glavapu_row_values(rows: list[list[Any]]) -> dict[str, str]:
    """Строки таблицы ТЭП как «код → значение». Читатель, а не счётчик."""
    values: dict[str, str] = {}
    for row in rows or []:
        if not row or len(row) < 4:
            continue
        code = str(row[0] or "").strip()
        if code:
            values[code] = str(row[3] or "").strip()
    return values


def vri_tep_moscow(query: str) -> dict[str, Any]:
    """Кнопка бота «Посчитать ВРИ и ТЭП» по Москве — тем же путём, что и сайт.

    Прежде кнопка звала `vri_tep_quick("msk", …)` напрямую. Путь к штатному
    калькулятору при этом существовал и работал: `/cadastral/tep-server` при
    заданном `MO_CALC_API_URL` пересылает запрос на ядро, там headless-Chromium
    гоняет калькулятор ГлавАПУ, а формулы включаются только при срыве браузера.
    Эндпоинт бот обходил — на Render браузера нет, и подпись «Методика: Формулы
    калькулятора ГлавАПУ» в файле значила не «сорвалось», а «иначе тут не
    бывает»: сайт и бот отвечали по одному участку разными числами, и оба
    выглядели верными. Четвёртый случай правила «модуль не заводит своего пути
    туда, где у сервиса уже есть общий».

    Карточка, файл и шаблон собираются ИЗ ТОЙ ЖЕ таблицы, которой посчитан
    ТЭП. Считать их рядом нельзя: два счёта одной величины однажды разойдутся.
    Калькулятор не ответил — возвращаются прежние формулы со своей карточкой и
    своим предупреждением; второй заход по территории при этом попадает в кэш
    участка, который сервер только что заполнил.
    """
    try:
        numbers = _parse_cadastral_numbers(query)
    except Exception:
        numbers = []
    if not numbers:
        # Не кадастровый номер — спрашивать калькулятор нечем. Отказ вернёт
        # прежний путь, своими словами: два разных отказа на одну причину
        # человек читает как две разные поломки.
        return vri_tep_quick("msk", query)
    try:
        served = cadastral_tep_server(CadastralAnalysisRequest(cadastral_numbers=query))
    except Exception as exc:
        logging.warning("бот: штатный расчёт ТЭП не удался (%s) — формулы", exc)
        return vri_tep_quick("msk", query)

    glavapu = served.get("glavapu") or {}
    rows = list(glavapu.get("rows") or [])
    if not glavapu.get("calculator") or not rows:
        return vri_tep_quick("msk", query)

    source = served.get("source") or {}
    method = str(source.get("format") or "Штатный калькулятор ГлавАПУ")
    values = _glavapu_row_values(rows)

    def num(code: str) -> float:
        return _ru_number(str(values.get(code, "")).split("(")[0]) or 0.0

    def fmt(value: Any, digits: int = 1) -> str:
        try:
            return f"{float(value):,.{digits}f}".replace(",", " ").replace(".", ",")
        except (TypeError, ValueError):
            return "—"

    area = num("1")
    spp = num("6") * 1000.0
    apartments_gns = num("7.1") * 1000.0
    commerce_gns = num("7.2") * 1000.0
    apartments = num("10") * 1000.0
    commerce_np = num("9.1.2") * 1000.0
    apartments_np = num("9.1.1") * 1000.0
    population, units = num("4"), num("5")
    dou, school = num("30"), num("31")
    clinic_adult, clinic_child = num("33"), num("34")
    compensation = num("54") + num("55") + num("56")
    permanent, guest, onsite = num("42.1"), num("42.2"), num("42.3")
    vri_mln = num("44")

    parameters = [list(row) for row in (glavapu.get("parameters") or [])]
    by_name = {str(row[0] or "").strip(): (row[1] if len(row) > 1 else "")
               for row in parameters if row}
    district = str(by_name.get("Район") or "")
    # Чем посчитано — часть ответа: подпись «Формулы калькулятора ГлавАПУ»
    # прежде стояла у любого файла бота и ни о чём не сообщала.
    parameters.append(["Методика", method, "—"])

    card = (
        "<b>ВРИ и ТЭП · Москва</b>\n"
        f"Участок: <code>{html.escape(str(query)[:80])}</code>\n"
        f"• площадь — {fmt(area, 4)} га · район — "
        f"{html.escape(district or '—')}\n"
        f"• СПП — {fmt(spp / 1000, 1)} тыс. м² · квартиры — {fmt(apartments, 0)} м²\n"
        f"• население — {fmt(population, 0)} чел. · квартир — {fmt(units, 0)}\n"
        f"• соцпотребность — ДОО {fmt(dou, 0)} мест, СОШ {fmt(school, 0)} мест, "
        f"поликлиники {fmt(clinic_adult, 0)}+{fmt(clinic_child, 0)} пос./см.\n"
        + (f"• <b>компенсация за соцобъекты — {fmt(compensation, 1)} млн ₽</b>\n"
           if compensation > 0 else "")
        + (f"• паркинг — {fmt(permanent + guest, 0)} м/м (постоянные "
           f"{fmt(permanent, 0)} + гостевые {fmt(guest, 0)}) · приобъектные "
           f"{fmt(onsite, 0)}\n" if permanent + guest + onsite > 0 else "")
        + (f"• <b>плата за смену ВРИ — {fmt(vri_mln, 1)} млн ₽</b>\n"
           if vri_mln > 0 else "")
        + f"<i>Считал {html.escape(method)}.</i>\n"
        + ("<i>Льготы по ВРИ (МПТ, передача жилья городу), аренда и МАИП — в "
           "мини-приложении: кнопка «Открыть и изменить расчёт».</i>\n")
    )

    workbook = _build_glavapu_xlsx_from_rows(rows, parameters)
    safe = re.sub(r"[^0-9A-Za-zА-Яа-я_-]+", "_", str(query))[:40] or "участок"
    today = date.today().isoformat()
    payload: dict[str, Any] = {
        "card": card, "file": workbook,
        "filename": f"ВРИ_ТЭП_{safe}_{today}.xlsx",
    }
    try:
        products: dict[str, dict[str, float]] = {
            "apartments": {"gns": apartments_gns, "total_area": apartments_np,
                           "saleable": apartments, "units": units},
            "ground_commercial": {"gns": commerce_gns, "total_area": commerce_np,
                                  "saleable": num("11") * 1000.0},
        }
        if permanent + guest > 0:
            products["underground_parking"] = {"units": permanent + guest}
        payload["template_file"] = _manual_tep_filled_template(
            str(query).strip()[:80] or "Участок",
            "Москва" + (f" · {district}" if district else ""),
            area, vri_mln, compensation, products)
        payload["template_filename"] = f"ТЭП_DevelopAid_{safe}_{today}.xlsx"
    except Exception as exc:
        _TELEGRAM_RUNTIME["last_error"] = "Шаблон ВРИ/ТЭП: " + _error_location(exc)
    return payload


@app.post("/cadastral/tep-from-calculator")
def import_cadastral_tep(req: CadastralTepRequest) -> dict[str, Any]:
    if not 30 <= len(req.rows) <= 150:
        raise HTTPException(status_code=400, detail="Калькулятор вернул неполную таблицу ТЭП")
    table_rows: list[list[Any]] = []
    for item in req.rows:
        code = str(item.get("code") or "").strip()[:20]
        name = str(item.get("name") or "").strip()[:300]
        unit = str(item.get("unit") or "").strip()[:80]
        value = str(item.get("value") or "").strip()[:120]
        if name and value:
            table_rows.append([code or None, name, unit, value])
    # Контроль полноты — по ИМЕНАМ строк, а не по их номерам. Кода 60 у ГлавАПУ
    # больше нет (живой снимок ядра, 01.09.2026): таблица перенумерована и
    # кончается на 58, а разбор и так читает её по именам. Номер чужой строки
    # означает только её место, и держаться за него — значит ломаться при
    # каждой перенумерации, молча и у всех сразу.
    missing = _glavapu_missing_controls(
        [{"name": row[1]} for row in table_rows])
    if missing:
        raise HTTPException(
            status_code=400,
            detail="Не все контрольные строки ТЭП получены из калькулятора: "
                   + ", ".join(missing))

    analysis = req.cadastral_analysis or {}
    territory = analysis.get("territory") or {}
    coefficients = analysis.get("coefficients") or {}
    parameters = [
        ["Район", territory.get("district") or ""],
        ["Административный округ", territory.get("administrative_district") or ""],
        ["Кадастровый квартал", territory.get("cadastral_quarter") or ""],
        ["Коэффициент аренды", coefficients.get("rent")],
        ["Коэффициент МПТ", coefficients.get("mpt_location")],
        # К1 и К2 приобъектной парковки приходят тем же ответом, что аренда и
        # УПКС, — и до полей не доезжали: расчёт нежилой парковки отказывался
        # «не заданы коэффициенты», а заполнить их было неоткуда, хотя город
        # их прислал. Какое из двух значений К2 взято, решает признак ТТК из
        # того же ответа: в августе оговорка «признак анализ не отдаёт» была
        # неверной, и приобъектные места считались по чужому числу.
        ["К1 — доступность рельсового каркаса", coefficients.get("rail")],
        ["К2 — деловая активность "
         + ("(внутри ТТК)" if bool(territory.get("inside_ttc")) else "(вне ТТК)"),
         coefficients.get("business_inside_ttc" if bool(territory.get("inside_ttc"))
                          else "business_outside_ttc")],
    ]
    numbers = analysis.get("recognized") or analysis.get("requested") or []
    safe_numbers = "_".join(str(number).replace(":", "-") for number in numbers[:3]) or "территория"
    filename = f"ГлавАПУ_{safe_numbers}.xlsx"
    workbook = _build_glavapu_xlsx_from_rows(table_rows, parameters)
    try:
        result = parse_glavapu_xlsx(workbook, filename)
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Не удалось перенести ТЭП из калькулятора: {exc}") from exc
    result["source"].update({
        "format": "Калькулятор ТЭП ГлавАПУ — автоматическое получение",
        "cadastral_numbers": numbers,
        "calculated_at": date.today().isoformat(),
        "calculator_url": analysis.get("calculator_url") or "https://genplan.tech/calc/",
    })
    result.setdefault("notes", []).insert(
        0,
        "Показатели автоматически считаны из готовой таблицы genplan.tech.",
    )
    # Таблица, которой посчитан этот ТЭП, едет вместе с ним. Строит её только
    # калькулятор, и второй раз взять её неоткуда: кто соберёт по этому ответу
    # свою карточку или свой файл, обязан читать те же строки, а не считать
    # рядом свои. Строки — строки и None, поэтому переживают пересылку на ядро
    # и обратно.
    result["glavapu"] = {"rows": table_rows, "parameters": parameters,
                         "calculator": True}
    # Каждый успешный сбор штатного калькулятора — бесплатная сверка серверных
    # формул: разошлись — значит, ГлавАПУ поменял методику, и путь Telegram
    # начал бы врать. Ошибка, ушедшая только в лог, — ошибка, которой нет,
    # поэтому расхождение кричит здесь, в /status и в серверных ответах.
    _glavapu_drift_in_background(table_rows, [str(n) for n in numbers])
    if _GLAVAPU_FORMULA_DRIFT.get("items"):
        result["warnings"].insert(
            0,
            "ВНИМАНИЕ: серверные формулы DevelopAid разошлись со штатным "
            "калькулятором (" + "; ".join(_GLAVAPU_FORMULA_DRIFT["items"][:4]) + "). "
            "Методика ГлавАПУ могла измениться — расчёты Telegram и кнопки бота "
            "требуют сверки.",
        )
    return result


# Бот Telegram вынесен в engine/bot_telegram.py и выполняется здесь же,
# в пространстве имён движка: порядок объявлений и подмены core.<имя>
# остаются прежними.
_engine_part("bot_telegram")


# Встроенные в PDF гарнитуры кириллицы не содержат, поэтому отчёт целиком —
# и таблицы, и заголовки, и колонтитул — набирается подключённым TTF. Каталоги
# различаются между дистрибутивами: у Debian это liberation, у части сборок
# liberation2, поэтому ищем по обоим и не привязываемся к одному пути.
_PDF_FONT_DIRS = (
    "/usr/share/fonts/truetype/dejavu",
    "/usr/share/fonts/truetype/liberation",
    "/usr/share/fonts/truetype/liberation2",
    "/usr/share/fonts/dejavu",
)
_PDF_REGULAR_FILES = ("DejaVuSans.ttf", "LiberationSans-Regular.ttf")
_PDF_BOLD_FILES = ("DejaVuSans-Bold.ttf", "LiberationSans-Bold.ttf")


def _pdf_find_font(names: tuple[str, ...]) -> str | None:
    for name in names:
        for directory in _PDF_FONT_DIRS:
            candidate = Path(directory) / name
            if candidate.is_file():
                return str(candidate)
    return None


def _pdf_font_names() -> tuple[str, str]:
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    regular = _pdf_find_font(_PDF_REGULAR_FILES)
    bold = _pdf_find_font(_PDF_BOLD_FILES)
    if not regular or not bold:
        raise RuntimeError(
            "На сервере не найден шрифт с кириллицей для PDF. "
            "Установите пакеты fontconfig и fonts-dejavu-core "
            "(в образе они ставятся в Dockerfile) и пересоберите контейнер."
        )
    if "DevelopAidSans" not in pdfmetrics.getRegisteredFontNames():
        pdfmetrics.registerFont(TTFont("DevelopAidSans", regular))
    if "DevelopAidSansBold" not in pdfmetrics.getRegisteredFontNames():
        pdfmetrics.registerFont(TTFont("DevelopAidSansBold", bold))
    return "DevelopAidSans", "DevelopAidSansBold"


def _project_articles_term(tep_report: dict[str, Any]) -> Any:
    """Имя базы общепроектных статей — то, что назвал движок."""
    return TERMS.get(str(tep_report.get("project_articles_area") or ""), CORE_TOTAL_AREA)


def _project_articles_sqm(tep_report: dict[str, Any]) -> float:
    """База общепроектных статей, м² — число движка (`project_articles_sqm`).

    У жилого и смешанного проекта это суммарная площадь МКД в ГНС, у чисто
    нежилого — суммарная площадь объектов (`object_rate_is_turnkey`). Отчёт
    старого формата поля не несёт — тогда база по-прежнему МКД.
    """
    if tep_report.get("project_articles_sqm") is not None:
        return float(tep_report.get("project_articles_sqm") or 0.0)
    return (float(tep_report.get("core_above_gns") or 0.0)
            + float(tep_report.get("core_under_gns") or 0.0))


def _above_ground_sqm(tep_report: dict[str, Any]) -> float:
    """Наземная часть проекта: строительный объём минус подземные СТРОКИ.

    Вычитается только подземная часть, которая в этом объёме стоит, — гараж
    МКД и кладовые. Гараж отдельно стоящего объекта живёт полем на его строке
    и в `total.gns` не входит вовсе: вычесть его значило бы занизить наземную
    площадь на объект, которого в ней и не было.

    Берётся из тех же строк ТЭП, что и вся таблица отчёта: заводить вторую
    арифметику ради подписи нельзя — она разойдётся с числами над ней.
    """
    return max(0.0, _number_or_zero((tep_report.get("total") or {}).get("gns"))
               - _core_underground_sqm(tep_report))


def _core_underground_sqm(tep_report: dict[str, Any]) -> float:
    """Подземная часть МКД — та, что движок и так считает своей базой.

    Читается `core_under_gns`, а не строка гаража: кладовые лежат на том же
    подземном этаже и в наземную площадь не входят, а перебор строк их терял —
    подпись отчёта относила их к наземной части. Перебор остаётся запасным
    путём для отчётов, собранных до появления базы.
    """
    base = tep_report.get("core_under_gns")
    if base is not None:
        return _number_or_zero(base)
    return sum(_number_or_zero(row.get("gns"))
               for row in (tep_report.get("rows") or [])
               if str(row.get("key")) in _UNDERGROUND_TEP_KEYS)


def _underground_sqm(tep_report: dict[str, Any]) -> float:
    """Вся подземная часть проекта: МКД, кладовые и гаражи объектов.

    Гараж офисника или ТЦ — такая же подземная площадь, как гараж дома: своя
    себестоимость метра, свой продукт местами. В подпись отчёта он не входил
    вовсе, при том что в `summary.underground_gns_sqm` и в статье CAPEX он
    есть, — две величины под одним именем.
    """
    return _core_underground_sqm(tep_report) + sum(
        _number_or_zero(row.get("under_gns"))
        for row in (tep_report.get("rows") or []))


def _number_or_zero(value: Any) -> float:
    try:
        result = float(value)
    except (TypeError, ValueError):
        return 0.0
    return result if result == result else 0.0


def _pdf_num(value: Any, decimals: int = 1) -> str:
    try:
        number = float(value or 0)
    except Exception:
        return "—"
    return f"{number:,.{decimals}f}".replace(",", " ").replace(".", ",")


def _pdf_count_text(value: Any, measure: str) -> str:
    """«1 362 квартир» — одна неразрывная строка ячейки PDF.

    Число и мера связаны неразрывным пробелом, разряды числа — тоже: узкая
    колонка «Кол-во» рвала «квартир» на «кварти / р», а «1 199» — на две
    строки. Пробелы внутри длинной меры («посещений в смену») остаются
    обычными — там перенос по словам законен.
    """
    return _pdf_num(value, 0).replace(" ", "\u00a0") + "\u00a0" + measure


def _pdf_count_column_width(cells: "list[str]", font: str, size: float,
                            padding: float, minimum: float) -> float:
    """Ширина колонки количества по самому длинному неразрывному куску.

    Колонка не угадывается числом миллиметров: мера у продуктов своя, и
    «4 500 посещений в смену» длиннее «250 мест». Ячейка переносится только
    по обычным пробелам и по строкам, поэтому ширину задаёт самое длинное
    слово с неразрывными пробелами, плюс поля ячейки.
    """
    from reportlab.pdfbase.pdfmetrics import stringWidth
    widest = 0.0
    for cell in cells:
        for line in str(cell or "").split("\n"):
            for token in line.split(" "):
                widest = max(widest, stringWidth(token, font, size))
    return max(minimum, widest + 2 * padding + 1.0)


def _pdf_unit_num(value: Any, digits: int) -> str:
    """Удельное: нулевая база — прочерк, а не «0,0» (движок отдаёт None)."""
    return "—" if value is None else _pdf_num(value, digits)


def _pdf_unit_base(item: dict[str, Any]) -> str:
    """База удельного строки — подпись из словаря по ключу движка."""
    base = str(item.get("base") or "")
    return f"м² {TERMS[base].genitive}" if base in TERMS else "—"


def _pdf_unit_saleable(item: dict[str, Any], digits: int) -> str:
    """На м² продаваемой — для сравнения с ценой; у строк с этой базой не повторяется."""
    if str(item.get("base") or "") == UNIT_BASE_SALEABLE:
        return "—"
    return _pdf_unit_num(item.get("per_saleable_th"), digits)


def _pdf_unit_bases_note(summary: dict[str, Any]) -> str:
    """Площади баз удельных — числами движка и словами словаря."""
    bases = summary.get("unit_bases") or {}
    parts = [f"{TERMS[key].name} — {_pdf_num(bases.get(key), 0)} м²"
             for key in (UNIT_BASE_TOTAL, UNIT_BASE_SALEABLE, UNIT_BASE_CORE_ABOVE, UNIT_BASE_CORE_UNDER)
             if key in TERMS and bases.get(key) is not None]
    return ("Базы удельных: " + "; ".join(parts) + ". Расходы — на "
            f"{TOTAL_AREA.genitive}, выручка и прибыль — на {SALEABLE_AREA.genitive}, "
            f"СМР наземной части — на {CORE_ABOVE_AREA.genitive}, подземной — на "
            f"{CORE_UNDER_AREA.genitive}.") if parts else ""


def _pdf_money(value: Any) -> str:
    try:
        number = float(value or 0)
    except Exception:
        return "—"
    if abs(number) >= 1_000_000_000:
        return _pdf_num(number / 1_000_000_000, 2) + " млрд ₽"
    return _pdf_num(number / 1_000_000, 1) + " млн ₽"


def _pdf_pct(value: Any) -> str:
    try:
        return _pdf_num(float(value or 0) * 100, 1) + "%"
    except Exception:
        return "—"


def _phase_comparison_pdf(table: dict[str, Any], regular: str, bold: str, colors: Any) -> Any:
    """Таблица сравнения очередей для PDF — печать `phase_comparison_table`.

    Блок открывается строкой-заголовком во всю ширину; итог жирный и с линией
    сверху, слагаемое и «из них» — с отступом: то же, что на странице.
    """
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.units import mm
    from reportlab.platypus import Paragraph, Table, TableStyle

    cell = ParagraphStyle("pc_cell", fontName=regular, fontSize=6.8, leading=8.2,
                          textColor=colors.HexColor("#222222"))
    num = ParagraphStyle("pc_num", parent=cell, alignment=2)
    strong = ParagraphStyle("pc_strong", parent=cell, fontName=bold,
                            textColor=colors.HexColor("#111111"))
    strong_num = ParagraphStyle("pc_strong_num", parent=strong, alignment=2)
    head = ParagraphStyle("pc_head", parent=strong, fontSize=6.6)
    muted = ParagraphStyle("pc_muted", parent=cell, textColor=colors.HexColor("#666666"))

    def text(value: Any) -> str:
        return (str(value).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))

    def one(value: Any) -> str:
        # Одна цифра после запятой так, как округляет страница (половина —
        # вверх по короткой записи числа): иначе «вводная 10,25» выходит
        # 10,3 на экране и 10,2 в PDF.
        from decimal import ROUND_HALF_UP, Decimal
        return _pdf_num(float(Decimal(repr(float(value or 0))).quantize(
            Decimal("0.1"), rounding=ROUND_HALF_UP)), 1)

    def fmt(row: dict[str, Any], value: Any) -> str:
        if value is None or value == "":
            return "—"
        kind = row.get("kind")
        if kind == "money":
            # Одна единица на таблицу, как на странице: «166,0 млн» под
            # «3,15 млрд» читается как другой масштаб колонки.
            return _pdf_num(float(value) / 1_000_000_000, 2) + " млрд ₽"
        if kind == "qty":
            unit = str(row.get("unit") or "")
            return (_pdf_num(value, 0 if unit == "шт." else 1) + " " + unit).strip()
        if kind == "th":
            return one(value)
        if kind == "pct":
            return _pdf_pct(value)
        if kind == "mult":
            return _pdf_num(value, 2) + "x"
        if kind == "date":
            raw = str(value)[:10]
            return f"{raw[8:10]}.{raw[5:7]}.{raw[:4]}" if len(raw) == 10 else raw
        return str(value)

    def label(row: dict[str, Any]) -> str:
        out = str(row.get("label") or "")
        if row.get("rate_input") is not None:
            out += f" (вводная {one(row['rate_input'])})"
        if row.get("kind") == "th":
            out += ", тыс ₽/м²"
        return out

    columns = list(table.get("columns") or [])
    span = len(columns) + 2
    data: list[list[Any]] = [[Paragraph("Показатель", head)]
                             + [Paragraph(text(n), ParagraphStyle("pc_hn", parent=head, alignment=2))
                                for n in columns + ["Свод"]]]
    style: list[tuple] = [
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("LINEBELOW", (0, 0), (-1, 0), 0.8, colors.HexColor("#111111")),
        ("LINEBELOW", (0, 1), (-1, -1), 0.3, colors.HexColor("#E2E2E2")),
        ("LEFTPADDING", (0, 0), (-1, -1), 4), ("RIGHTPADDING", (0, 0), (-1, -1), 4),
        ("TOPPADDING", (0, 0), (-1, -1), 2.5), ("BOTTOMPADDING", (0, 0), (-1, -1), 2.5),
    ]
    # Делители удельных — одна подпись таблицы мелким шрифтом под шапкой,
    # как на странице, а не строки-показатели.
    note = ParagraphStyle("pc_note", parent=muted, fontSize=5.8, leading=7.0)
    section = ParagraphStyle("pc_section", parent=strong, fontSize=8.2, leading=10,
                             textColor=colors.white)
    divisors = [
        text(str(d.get("label") or "")) + ": " + " · ".join(
            [text(n) + " " + _pdf_num(v, 0) for n, v in zip(columns, d.get("values") or [])]
            + ["свод " + _pdf_num(d.get("total"), 0)]) + " " + text(str(d.get("unit") or ""))
        for d in table.get("divisors") or []]
    if divisors:
        i = len(data)
        data.append([Paragraph("Удельные показатели — делители: " + "<br/>".join(divisors), note)]
                    + [""] * (span - 1))
        style += [("SPAN", (0, i), (-1, i)), ("TOPPADDING", (0, i), (-1, i), 4)]
    for block in table.get("blocks") or []:
        i = len(data)
        # Заголовок раздела — тёмная полоса крупнее итогов: жирное «Итого» с
        # линией выглядело так же, и разделы терялись (владелец, 29.09.2026).
        data.append([Paragraph(text(str(block.get("title") or "").upper()), section)] + [""] * (span - 1))
        style += [("SPAN", (0, i), (-1, i)), ("TOPPADDING", (0, i), (-1, i), 4),
                  ("BOTTOMPADDING", (0, i), (-1, i), 4),
                  ("BACKGROUND", (0, i), (-1, i), colors.HexColor("#111111"))]
        for row in block.get("rows") or []:
            i = len(data)
            if row.get("kind") == "note":
                data.append([Paragraph(text(str(row.get("label") or "")), note)] + [""] * (span - 1))
                style += [("SPAN", (0, i), (-1, i)), ("LEFTPADDING", (0, i), (0, i), 12)]
                continue
            role = row.get("role") or ""
            lab_style = strong if role == "total" else (muted if role in ("part", "sub") else cell)
            num_style = strong_num if role == "total" else num
            values = list(row.get("values") or []) + [row.get("total")]
            data.append([Paragraph(text(label(row)), lab_style)]
                        + [Paragraph(text(fmt(row, v)), num_style) for v in values])
            if role == "total":
                style.append(("LINEABOVE", (0, i), (-1, i), 0.9, colors.HexColor("#111111")))
            if role in ("part", "sub"):
                style.append(("LEFTPADDING", (0, i), (0, i), 12))
    label_w = 62 * mm
    rest = (170 * mm - label_w) / max(1, len(columns) + 1)
    out = Table(data, colWidths=[label_w] + [rest] * (len(columns) + 1), repeatRows=1, hAlign="LEFT")
    out.setStyle(TableStyle(style))
    return out


def _pdf_entry_cost_rows(result: dict[str, Any],
                         expense_structure: list[dict[str, Any]]) -> list[list[str]]:
    """Цена входа и плата за ВРИ — из расчёта, а не из формы.

    Форма не знает ни о льготе, ни о доле очереди. При стопроцентной льготе
    отчёт печатал полную плату за смену ВРИ как расход, которого в модели нет:
    ключевая экономика не сходилась с собственной структурой расходов ниже, и
    оба числа выглядели достоверно.
    """
    purchase = 0.0
    for group in expense_structure or []:
        if str(group.get("label")) == "Цена приобретения":
            purchase = float(group.get("value") or 0)
            break
    paid = float((result.get("capex") or {}).get("land_rights") or 0)
    relief = float(((result.get("vri") or {}).get("totals") or {}).get("relief") or 0)
    # Стоимость сделки — две строки и итог, когда в ней есть выкуп ЗУ/ОКС у
    # третьих лиц (решение владельца, 29.09.2026). Разбивка — из сводки
    # расчёта, итог — та же группа структуры расходов.
    deal = result.get("deal") or {}
    buyout = float(deal.get("buyout_mln") or 0) * 1_000_000
    deal_rows = ([["Цена участка / права", _pdf_money(purchase - buyout)],
                  ["Выкуп ЗУ/ОКС у третьих лиц (кадастровая стоимость, не цена сделки)",
                   _pdf_money(buyout)],
                  ["Стоимость сделки", _pdf_money(purchase)]]
                 if buyout > 0 else [["Цена приобретения", _pdf_money(purchase)]])
    return [
        *deal_rows,
        ["Смена ВРИ / земельные права",
         _pdf_money(paid) + (f" (льгота {_pdf_money(relief)})" if relief > 0 else "")],
    ]


def _layout_dscr(layout: Any) -> float | None:
    """DSCR кредита объекта для вердикта — только у проекта без ДДУ.

    У проекта с БРИДЖем и ПФ вердикт меряет LLCR, как прежде; у проекта без
    них — минимальный DSCR объектов из `report_layout`. Нет DSCR (прямая
    продажа без аренды) — вердикт без долговой проверки.
    """
    if not isinstance(layout, dict) or layout.get("project_finance", True):
        return None
    metric = layout.get("debt_metric")
    if isinstance(metric, dict):
        return float(metric["value"]) if metric.get("key") == "dscr" else None
    values = [float(t["value"]) for t in layout.get("nonres_tiles") or []
              if t.get("unit") == "mult" and t.get("value") is not None]
    return min(values) if values else None


def _layout_no_debt_cover(layout: Any) -> bool:
    """У проекта без ПФ нет показателя долга (`debt_metric.key` пуст): кредит
    объектов гасится продажами. Вердикт тогда не говорит ни об LLCR, ни о DSCR."""
    metric = layout.get("debt_metric") if isinstance(layout, dict) else None
    return isinstance(metric, dict) and not metric.get("key")


def _purchase_feasibility(
    purchase_price_mln: Any,
    net_profit_mln: Any,
    llcr: Any,
    debt_amount: Any = 0.0,
    ending_debt_mln: Any = 0.0,
    default_date: Any = None,
    pf_shortfall_mln: Any = 0.0,
    pf_shortfall_month: Any = None,
    object_dscr: Any = None,
    no_debt_cover: bool = False,
) -> dict[str, str]:
    """Вердикт по вводным плюс оговорка о дефолте, если он в модели был.

    Дефолт в дату раскрытия эскроу — факт о расчёте, а не ещё одна ветка
    вердикта: он верен и при низком LLCR, и при высоком, и спорить с ними за
    очередь ему незачем. Прежде он звучал ровно в одном случае — когда долг
    оставался непогашенным на КОНЕЦ горизонта. Если остаточные продажи его
    закрывали, вердикт молчал, и прибыль печаталась голым числом: банк при
    этом ждал погашения в РВЭ и не получил его (владелец, 30.08.2026:
    «значит нельзя писать и чистую прибыль»).
    """
    verdict = _purchase_feasibility_base(
        purchase_price_mln, net_profit_mln, llcr, debt_amount, ending_debt_mln,
        object_dscr, no_debt_cover)
    verdict = _financing_not_closed_clause(
        verdict, pf_shortfall_mln, pf_shortfall_month)
    when = str(default_date or "").strip()
    # У ветки «Дефолтный» оговорка уже своя, и повторять её нечем.
    if not when or verdict.get("status") in ("default", "not_available"):
        return verdict
    verdict = dict(verdict)
    verdict["conditional"] = True
    verdict["default_date"] = when
    verdict["text"] = verdict["text"].rstrip() + (
        f" В модели есть дефолт: {_month_in_words(when)} раскрытого эскроу не "
        "хватило на погашение ПФ. Долг закрывается позже, продажами следующих "
        "периодов, — но только если банк на это согласится: пени и досрочное "
        "требование модель не считает. Значит показанная чистая прибыль — при "
        "этом допущении, а не результат.")
    return verdict


def _financing_not_closed_clause(
    verdict: dict[str, str], shortfall_mln: Any, shortfall_month: Any,
) -> dict[str, str]:
    """Одобренного лимита ПФ не хватило — экономика показана при допущении.

    Движок это умел с самого начала: доходит выборка до потолка — остаток
    уходит в `pf_shortfall` с месяцем первой нехватки. А до вердикта величина
    не доезжала вовсе — её не было ни в своде, ни в отчёте, только в
    `finance`, — и проект, которому банк не дал трети нужных денег, получал
    «Предварительно целесообразна» ровно тем же текстом, что и полностью
    профинансированный.

    Ветка здесь не заводится, и это не упущение: приписка того же рода, что у
    дефолта в РВЭ (решение владельца, 30.08.2026), — она верна и при LLCR
    0,99, и при 1,38, и спорить с ними за очередь ей незачем. Чего модель НЕ
    делает: не выдумывает, откуда возьмутся недостающие деньги, и не считает
    их стоимость. Она называет сумму, месяц и то, что дальше посчитано так,
    будто их кто-то дал.
    """
    try:
        gap = float(shortfall_mln or 0.0)
    except (TypeError, ValueError):
        gap = 0.0
    # Полмиллиона — тот же порог, по которому отчёт печатает остаток ПФ:
    # копейки округления новостью не являются.
    if gap <= 0.5:
        return verdict
    verdict = dict(verdict)
    # Заголовок положительной ветки — единственный, который правится. «Предварительно
    # целесообразна» это утверждение без условий, а условие как раз есть, и в
    # PDF с чатом видно прежде всего заголовок: текст под ним читают не все.
    # У прочих веток («нецелесообразна», «требует пересмотра», «дефолтный»)
    # заголовок зелёным светом и не был — там хватает приписки.
    if verdict.get("status") == "positive":
        verdict["status"] = "review"
        verdict["title"] = "Целесообразность не подтверждена: финансирование не закрыто"
    verdict["conditional"] = True
    verdict["financing_gap"] = True
    verdict["pf_shortfall_mln"] = gap
    when = str(shortfall_month or "").strip()
    verdict["pf_shortfall_month"] = when
    since = f" — впервые {_month_in_words(when)}" if len(when) >= 7 else ""
    verdict["text"] = verdict["text"].rstrip() + (
        f" Финансирование не закрыто: одобренного лимита ПФ не хватает на "
        f"{_telegram_number(gap, 1)} млн ₽{since}. Дальше посчитано так, будто "
        "эти деньги проект получил: источника у них в модели нет, и их "
        "стоимость не учтена. Пока лимит не подтверждён, показанные прибыль, "
        "маржинальность и LLCR — при этом допущении, а не результат.")
    return verdict


def _month_in_words(iso: Any) -> str:
    """«2030-01-01» → «в январе 2030». Пустое — «в дату раскрытия»."""
    text = str(iso or "").strip()
    if len(text) < 7:
        return "в дату раскрытия эскроу"
    try:
        year, month = int(text[:4]), int(text[5:7])
    except ValueError:
        return "в дату раскрытия эскроу"
    if not 1 <= month <= 12:
        return "в дату раскрытия эскроу"
    return f"в {_MONTHS_IN[month - 1]} {year}"


# Предложный падеж списком, а не заменой окончаний: правило «я→е» однажды
# даст «в феврале» из чего угодно. Тот же список, той же формы, что на
# странице (RU_MONTHS_IN) — но объявить его один раз на два языка нечем.
_MONTHS_IN = ("январе", "феврале", "марте", "апреле", "мае", "июне", "июле",
              "августе", "сентябре", "октябре", "ноябре", "декабре")


def _purchase_feasibility_base(
    purchase_price_mln: Any,
    net_profit_mln: Any,
    llcr: Any,
    debt_amount: Any = 0.0,
    ending_debt_mln: Any = 0.0,
    object_dscr: Any = None,
    no_debt_cover: bool = False,
) -> dict[str, str]:
    """Return a short preliminary purchase-feasibility conclusion.

    `object_dscr` — у проекта без ДДУ (`report_layout.project_finance` ложно)
    долг — кредит объекта, и его покрытие меряет DSCR, а не LLCR: те же
    пороги 1,00x и 1,20x.

    The conclusion uses only the current model parameters. It does not estimate
    market value or calculate an alternative purchase price.
    """
    try:
        purchase_price = float(purchase_price_mln or 0.0)
    except (TypeError, ValueError):
        purchase_price = 0.0
    try:
        net_profit = float(net_profit_mln or 0.0)
    except (TypeError, ValueError):
        net_profit = 0.0
    try:
        llcr_value = float(llcr or 0.0)
    except (TypeError, ValueError):
        llcr_value = 0.0
    try:
        debt = float(debt_amount or 0.0)
    except (TypeError, ValueError):
        debt = 0.0
    try:
        ending_debt = float(ending_debt_mln or 0.0)
    except (TypeError, ValueError):
        ending_debt = 0.0

    if purchase_price <= 0:
        return {
            "status": "not_available",
            "title": "Вывод не сформирован",
            "text": "Цена покупки не указана, поэтому оценить целесообразность приобретения при текущих параметрах нельзя.",
        }
    # Непогашенный долг на конец проекта — дефолт, и он старше бумажной
    # прибыли: для инвестора такой проект не «прибыльный с оговоркой», а
    # дефолтный (решение владельца, 27.08.2026). Закрыть дыру «вкладом
    # акционера» — значит показать благотворительность как инвестицию.
    if ending_debt > 0.5:
        return {
            "status": "default",
            "title": "Дефолтный: долг не погашается",
            "text": (
                "На конец проекта остаётся непогашенный долг "
                f"{_telegram_number(ending_debt, 1)} млн ₽ — денежного потока "
                "проекта не хватает вернуть кредит. Показанная чистая прибыль — "
                "бумажная: чтобы рассчитаться с банком, инвестору пришлось бы "
                "доплатить эту сумму своими деньгами. Для инвестора проект "
                "дефолтный, а не прибыльный."
            ),
        }
    if net_profit <= 0:
        return {
            "status": "negative",
            "title": "Предварительно нецелесообразна",
            "text": "При текущей цене покупки и принятых параметрах проект не формирует положительную чистую прибыль.",
        }
    if object_dscr is not None:
        dscr = float(object_dscr)
        shown = _telegram_number(dscr, 2)
        if dscr < 1.0:
            return {"status": "negative", "title": "Предварительно нецелесообразна",
                    "text": f"Проект прибылен, но NOI не покрывает обслуживание кредита объекта: DSCR {shown}x — ниже 1,00x."}
        if dscr < 1.20:
            return {"status": "review", "title": "Требует пересмотра условий покупки",
                    "text": f"Проект формирует прибыль, однако DSCR кредита объекта {shown}x — ниже целевого уровня 1,20x. Следует проверить аренду, долю кредита, ставку и срок."}
        return {"status": "positive", "title": "Предварительно целесообразна",
                "text": f"При текущей цене покупки проект формирует положительную чистую прибыль, а DSCR кредита объекта {shown}x — не ниже 1,20x."}
    if debt > 0 and llcr_value < 1.0:
        return {
            "status": "negative",
            "title": "Предварительно нецелесообразна",
            "text": "Проект прибылен, но денежного потока недостаточно для обслуживания расчётной долговой нагрузки: LLCR ниже 1,00x.",
        }
    if debt > 0 and llcr_value < 1.20:
        return {
            "status": "review",
            "title": "Требует пересмотра условий покупки",
            "text": "Проект формирует прибыль, однако LLCR ниже целевого уровня 1,20x. Следует проверить цену покупки, себестоимость, сроки и условия финансирования.",
        }
    if debt > 0:
        return {
            "status": "positive",
            "title": "Предварительно целесообразна",
            "text": "При текущей цене покупки проект формирует положительную чистую прибыль, а LLCR находится не ниже целевого уровня 1,20x.",
        }
    if no_debt_cover:
        return {
            "status": "positive",
            "title": "Предварительно целесообразна",
            "text": "При текущей цене покупки проект формирует положительную чистую прибыль; кредит объектов гасится выручкой прямых продаж, покрытие долга NOI не меряется — погашение кредита показано в «Финансировании объекта».",
        }
    return {
        "status": "positive",
        "title": "Предварительно целесообразна",
        "text": "При текущей цене покупки проект формирует положительную чистую прибыль; долговое финансирование не создаёт ограничений по LLCR.",
    }


class _PdfSection:
    """Метка секции в потоке отчёта.

    Разделы собирались в том порядке, в каком их удобно было считать, и отчёт
    читался не как разбор проекта, а как история правок: удельные расходы
    стройки стояли на первой странице до ТЭП, вводные — после выводов и
    чувствительности, а графики продаж жили в блоке финансирования. Порядок
    вычислений менять нельзя (одно опирается на другое), поэтому разделы
    помечаются здесь, а собираются в читаемом порядке при сборке документа.
    """

    __slots__ = ("name",)

    def __init__(self, name: str) -> None:
        self.name = name


def _project_cadastral_numbers(inputs: dict[str, Any]) -> list[str]:
    """Все кадастровые номера проекта — из первого места, где проект хранит
    участок номерами: снимок поиска ЕГРН (`_land_lookup.query`), поле
    `cadastral_numbers`, вписанное в поле участка (`_cadastral_query`), расчёт
    ТЭП по номеру (`_cadastral_analysis`). Поиск по адресу номеров не даёт и
    следующие места не заслоняет. Без обрезки: территория КРТ из двадцати
    участков — двадцать номеров, и тизер, таблица и карта читают этот список
    целиком."""
    inputs = inputs or {}
    analysis = inputs.get("_cadastral_analysis") or {}
    analysed = analysis.get("recognized") or analysis.get("requested") or []
    sources = (
        (inputs.get("_land_lookup") or {}).get("query"),
        inputs.get("cadastral_numbers"),
        inputs.get("_cadastral_query"),
        " ".join(_land_text(item) for item in analysed) if isinstance(analysed, list)
        else analysed,
    )
    for source in sources:
        numbers: list[str] = []
        for n in re.findall(r"(?<![\d:])\d{2}:\d{2}:\d{6,8}:\d+", _land_text(source)):
            if n not in numbers:
                numbers.append(n)
        if numbers:
            return numbers
    return []


def _pdf_screening_numbers(inputs: dict[str, Any]) -> list[str]:
    """Кадастровые номера для раздела реализуемости посадки полного PDF:
    первые десять из `_project_cadastral_numbers` — скрининг участка стоит
    десятки запросов к НСПД. Тизер эту обрезку не наследует."""
    return _project_cadastral_numbers(inputs)[:10]


def _pdf_ordered_story(story: list[Any], order: list[tuple[str, bool]],
                       page_break: Any) -> list[Any]:
    """Поток отчёта, пересобранный по секциям.

    До первой метки идёт шапка — она остаётся на месте. Разрыв страницы
    ставится перед секцией, только если в ней что-то есть: пустая секция не
    имеет права оставлять за собой пустую страницу.
    """
    head: list[Any] = []
    sections: dict[str, list[Any]] = {}
    current: str | None = None
    for item in story:
        if isinstance(item, _PdfSection):
            current = item.name
            sections.setdefault(current, [])
            continue
        (sections[current] if current is not None else head).append(item)
    out = list(head)
    for name, breaks_page in order:
        block = sections.get(name) or []
        if not block:
            continue
        if breaks_page and out:
            out.append(page_break())
        out.extend(block)
    return out


def _pdf_pf_step_rows(financing: dict[str, Any]) -> list[list[str]]:
    """Ступени надбавки по покрытию эскроу — строками таблицы финансирования.

    Средняя ставка без лестницы объяснима, с лестницей — нет: банк спросит,
    почему процент такой, и ответ «в среднем 0,22%» его не устроит. Показываем
    ступень, её ставку и сколько месяцев она действовала. Ступеней нет — нет и
    строк: у большинства НКЛ ставка одна.
    """
    rows: list[list[str]] = []
    for step in (financing.get("pf_special_steps") or []):
        edge = str(step.get("coverage_from_pct", "")).replace(".", ",")
        rate = str(step.get("rate_pct", "")).replace(".", ",")
        rows.append([f"Ступень: покрытие от {edge}%",
                     f"{rate}% · {int(step.get('months') or 0)} мес."])
    return rows


# Легенда графика покрытия эскроу объявлена один раз. Её читают страница и PDF,
# и разошедшиеся подписи одних и тех же линий — это две версии правды об одном
# графике: копии уже разошлись, одна называла накопленное накопленным, вторая
# нет. Стиль здесь назван, а не нарисован: у страницы это CSS, у PDF — штрих.
_ESCROW_CHART_LEGEND: tuple[tuple[str, str, str], ...] = (
    ("Эскроу накоплено", "#2D6A4F", "area"),
    ("Обязательство: тело + начисленные проценты и комиссии", "#A35D00", "line"),
    ("Тело ПФ", "#A35D00", "dash4"),
    ("Чем эскроу не перекрыт", "#A35D00", "band"),
    ("Раскрыто с эскроу, накопленным итогом", "#1B5E77", "dash6"),
    ("Продано после ввода, накопленным итогом", "#1B5E77", "thin"),
)
ESCROW_CHART_LEGEND_PLACEHOLDER = "__DEVELOPAID_ESCROW_LEGEND__"


def _escrow_chart_legend_html() -> str:
    """Та же легенда разметкой страницы."""
    spans = []
    for text, colour, style in _ESCROW_CHART_LEGEND:
        if style == "dash4":
            fill = f"repeating-linear-gradient(90deg,{colour} 0 4px,transparent 4px 7px)"
        elif style == "dash6":
            fill = f"repeating-linear-gradient(90deg,{colour} 0 6px,transparent 6px 10px)"
        elif style == "area":
            fill = f"{colour};opacity:.45;height:9px"
        elif style == "band":
            fill = f"{colour};opacity:.25;height:9px"
        elif style == "thin":
            fill = f"{colour};opacity:.55;height:2px"
        else:
            fill = colour
        spans.append(f'<span><i style="background:{fill}"></i>{html.escape(text)}</span>')
    return '<div class="legend">' + "".join(spans) + "</div>"


def _pdf_nonres_value(row: dict[str, Any]) -> str:
    """Значение строки нежилья и гостиницы (`nonres_report`, `hotel_report`,
    `report_layout`) для PDF. Отсутствующее — «—», а не ноль."""
    unit, value = row.get("unit"), row.get("value")
    if value is None and unit not in ("text", "section"):
        return "—"
    if unit == "mln":
        return _pdf_num(float(value) / 1e6, 1) + " млн ₽"
    if unit == "rub_unit":
        return _pdf_num(float(value), 0) + " ₽"
    if unit == "count":
        return _pdf_num(float(value), 0)
    if unit == "years":
        return _pdf_num(float(value), 1)
    if unit == "rub":
        return _pdf_money(value)
    if unit == "pct":
        return _pdf_num(float(value or 0) * 100, 1) + "%"
    if unit == "mult":
        return "—" if value is None else _pdf_num(float(value), 2) + "x"
    if unit == "date":
        return ".".join(reversed(str(value or "—")[:7].split("-")))
    if unit == "section":
        return " "  # пустая клетка: «—» значило бы «нет данных»
    return str(value or "—")


# Метки PDF у разделов объектной вёрстки: свои — `object_<ключ>`, общие
# с жилой — финансирование (кредит объекта и собственное участие),
# чувствительность и календарь.
_PDF_OBJECT_SHARED = {"finance": "financing", "sensitivity": "sensitivity",
                      "calendar": "calendar"}


def _pdf_section_order(object_sections: dict[str, Any]) -> list[tuple[str, bool]]:
    """Порядок разделов PDF — порядок `report_layout.sections` движка.

    Жилой: разбор проекта — что за участок → что на нём выходит → на чём
    считали → сколько стоит → сколько приносит → чем финансируется → чем
    рискуем → когда. Объектный: девять разделов владельца; реализуемость
    посадки — в разделе «Объект и участок».
    """
    if not object_sections:
        return [
            ("tep", False), ("vri", False), ("screening", True), ("summary", False),
            ("phases", True), ("premises", True),
            ("expenses", False), ("expenses_detail", False),
            ("income", True), ("financing", True), ("sensitivity", True),
            ("calendar", False), ("footer", False),
        ]
    order: list[tuple[str, bool]] = []
    for index, key in enumerate(object_sections):
        name = _PDF_OBJECT_SHARED.get(key, f"object_{key}")
        order.append((name, index > 0 and key != "calendar"))
        if key == "object":
            order.append(("screening", False))
    return order + [("footer", False)]


def _pdf_object_value(row: dict[str, Any]) -> str:
    """Значение строки объектной вёрстки: единицы `nonres_report` плюс метры,
    места, тыс ₽/м² и вводная со своей единицей."""
    unit, value = row.get("unit"), row.get("value")
    if unit in ("sqm", "count", "th", "num") and value is None:
        return "—"
    if unit == "sqm":
        return _pdf_num(value, 0) + " м²"
    if unit == "count":
        return _pdf_num(value, 0)
    if unit == "th":
        return _pdf_num(value, 1) + " тыс ₽/м²"
    if unit == "num":
        return (_pdf_num(value, 2).rstrip("0").rstrip(",") + (" " + str(row["suffix"])
                                                             if row.get("suffix") else ""))
    return _pdf_nonres_value(row)


def _object_pdf_sections(story: list[Any], sections: dict[str, Any], inputs: dict[str, Any],
                         P: Any, table: Any, h2: Any, small: Any, normal: Any,
                         KeepTogether: Any, Spacer: Any, mm: float, *,
                         sensitivity_done: bool) -> None:
    """Разделы объектной вёрстки в поток PDF — блоками движка, без пересчёта."""
    for key, section in sections.items():
        if key in ("finance", "calendar") or (key == "sensitivity" and sensitivity_done):
            continue
        story.append(_PdfSection(_PDF_OBJECT_SHARED.get(key, f"object_{key}")))
        story.append(P(str(section.get("title") or ""), h2))
        _object_pdf_blocks(story, section, inputs, P, table, small, KeepTogether, Spacer, mm)


def _object_pdf_blocks(story: list[Any], section: dict[str, Any], inputs: dict[str, Any],
                       P: Any, table: Any, small: Any, KeepTogether: Any, Spacer: Any,
                       mm: float) -> None:
    """Блоки одного раздела объектной вёрстки — таблицами движка."""
    for block in section.get("blocks") or []:
        title = str(block.get("title") or "")
        ref = block.get("ref")
        if block.get("kind") == "verdict" and section.get("verdict"):
            verdict = section["verdict"]
            story.append(table([["Вывод", str(verdict.get("title") or "")],
                                ["Основание", str(verdict.get("text") or "")]],
                               [45*mm, 125*mm], header=False, font_size=8.0))
            continue
        if ref == "goal_seek":
            goal = section.get("goal_seek") or {}
            story.append(P(
                (f"{title}: подбирается на странице отчёта полным пересчётом модели — "
                 f"наибольшая цена участка, при которой «{goal.get('label')}» не ниже "
                 f"{_pdf_num(goal.get('target'), 2)}x.") if goal.get("metric")
                else f"{title}: {goal.get('reason') or 'показателя долга у проекта нет.'}",
                small))
            continue
        if ref == "site":
            rows = []
            area = float(inputs.get("site_area_ha") or 0)
            if area > 0:
                rows.append(["Площадь участка", _pdf_num(area, 4) + " га"])
            numbers = _project_cadastral_numbers(inputs)
            if numbers:
                rows.append(["Кадастровые номера", ", ".join(numbers)])
            if rows:
                story.append(KeepTogether([P(title, small),
                                           table(rows, [60*mm, 110*mm], header=False)]))
            continue
        if ref == "sensitivity":
            brief = ", ".join(str(r.get("value") or "") for r in section.get("brief") or [])
            story.append(P("Чувствительность не рассчитана на вкладке — факторы объекта: "
                           + (brief or "—") + ".", small))
            continue
        if block.get("years"):
            columns = block.get("columns") or []
            rows = [[str(c[1]) for c in columns]]
            for year in block["years"]:
                rows.append([str(year.get(c[0])) if c[2] == "text"
                             else _pdf_object_value({"unit": c[2], "value": year.get(c[0])})
                             for c in columns])
            width = 170 / max(1, len(columns))
            story.append(KeepTogether([P(title, small),
                                       table(rows, [width*mm] * len(columns), font_size=6.8)]))
            continue
        rows = [[title or " ", " "]]
        for row in block.get("rows") or []:
            rows.append([str(row.get("label") or ""), _pdf_object_value(row)])
        story.append(table(rows, [112*mm, 58*mm], font_size=7.6))
        story.append(Spacer(1, 2*mm))


def _build_developaid_pdf(payload: dict[str, Any]) -> bytes:
    from reportlab.lib import colors
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
    from reportlab.lib.units import mm
    from reportlab.graphics.shapes import Circle, Drawing, Line, PolyLine, Polygon, Rect, String
    from reportlab.platypus import KeepTogether, SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak

    regular, bold = _pdf_font_names()
    result = payload.get("result") or {}
    inputs = payload.get("inputs") or {}
    summary = result.get("summary") or {}
    report = result.get("report") or {}
    financing = report.get("financing") or {}
    tep_report = result.get("tep") or {}
    products = report.get("products") or []
    expense_structure = report.get("expense_structure") or []
    calendar_data = report.get("calendar") or {}
    # Проект без жилья — свои разделы (`report.object_report`, вёрстку выбрал
    # движок в `report_layout.kind`): PDF их печатает, а не собирает.
    _object_sections = {str(sec.get("key")): sec
                        for sec in (report.get("object_report") or {}).get("sections") or []}
    _object_calendar = (_object_sections.get("calendar") or {}).get("calendar") or {}
    if _object_calendar.get("events"):
        calendar_data = _object_calendar
    cads = payload.get("cadastral_numbers") or []
    source_label = str(payload.get("source_label") or "ТЭП DevelopAid")
    scenario_key = str(payload.get("scenario") or "base")
    scenario_label = {"conservative":"Консервативный","base":"Базовый","optimistic":"Оптимистичный"}.get(scenario_key, scenario_key or "Базовый")
    # Класс — то же решение, что у карточки и предпосылок (`project_class_view`).
    _class_view = project_class_view(inputs)
    class_label = _class_view["label"]
    class_title = "Класс жилья" if _class_view["kind"] == "housing" else _class_view["title"]
    project_name = str(payload.get("project_name") or "").strip()
    title_scope = project_name or (", ".join(str(x) for x in cads) if cads else "Девелоперский проект")

    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf,pagesize=A4,rightMargin=14*mm,leftMargin=14*mm,topMargin=14*mm,bottomMargin=15*mm,title=f"DevelopAid — {title_scope}",author="DevelopAid")
    styles = getSampleStyleSheet()
    normal = ParagraphStyle("normal_ru",parent=styles["BodyText"],fontName=regular,fontSize=8.8,leading=12,textColor=colors.HexColor("#222222"))
    small = ParagraphStyle("small_ru",parent=normal,fontSize=7.4,leading=9.5,textColor=colors.HexColor("#666666"))
    h1 = ParagraphStyle("h1_ru",parent=styles["Title"],fontName=bold,fontSize=20,leading=24,spaceAfter=5,textColor=colors.HexColor("#111111"))
    h2 = ParagraphStyle("h2_ru",parent=styles["Heading2"],fontName=bold,fontSize=12.5,leading=16,spaceBefore=8,spaceAfter=6,textColor=colors.HexColor("#111111"))

    def P(value: Any, style=normal):
        text = str(value if value not in (None, "") else "—")
        return Paragraph(html.escape(text).replace("\n", "<br/>"), style)

    def table(rows, widths=None, header=True, font_size=8.0):
        converted=[]
        for r_idx,row in enumerate(rows):
            converted.append([cell if hasattr(cell,'wrap') else P(cell, small if (header and r_idx==0) else normal) for cell in row])
        t=Table(converted,colWidths=widths,repeatRows=1 if header else 0,hAlign='LEFT')
        commands=[('FONTNAME',(0,0),(-1,-1),regular),('FONTSIZE',(0,0),(-1,-1),font_size),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('GRID',(0,0),(-1,-1),0.35,colors.HexColor('#D8D8D8')),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]
        if header and rows:
            commands += [('BACKGROUND',(0,0),(-1,0),colors.HexColor('#F1F1EF')),('FONTNAME',(0,0),(-1,0),bold)]
        t.setStyle(TableStyle(commands));return t

    def chart_month(value: Any) -> str:
        try:
            parsed = d(str(value)[:10])
            return f"{parsed.month:02d}.{parsed.year}"
        except Exception:
            return str(value or "—")[:7]

    def tornado_chart(rows: list[dict[str, Any]], base: float, digits: int) -> Drawing | None:
        """Горизонтальные плечи от базовой линии, как на вкладке.

        Плечо рисуется от базы к своему значению, поэтому случай, когда рост
        параметра ухудшает показатель, отображается сам собой.
        """
        values = [base]
        for row in rows:
            for key in ("low_result", "high_result"):
                if row.get(key) is not None:
                    values.append(float(row[key]))
        low, high = min(values), max(values)
        if high - low < 1e-9:
            high = low + 1.0
        span = (high - low) * 1.08
        low -= (high - low) * 0.04
        width, row_h = 500, 17
        label_width, plot = 170, 250
        height = 14 + row_h * len(rows)
        drawing = Drawing(width, height)

        def position(value: float) -> float:
            return label_width + (value - low) / span * plot

        for index, row in enumerate(rows):
            y = height - 14 - index * row_h
            label = str(row.get("label") or "—")
            if len(label) > 30:
                label = label[:28] + "…"
            drawing.add(String(0, y, label, fontName=regular, fontSize=7,
                               fillColor=colors.HexColor("#333333")))
            for key, colour in (("low_result", "#A35D00"), ("high_result", "#2D6A4F")):
                value = row.get(key)
                if value is None:
                    continue
                start = min(position(base), position(float(value)))
                end = max(position(base), position(float(value)))
                drawing.add(Rect(start, y - 2, max(1.0, end - start), 9,
                                 fillColor=colors.HexColor(colour), strokeColor=None))
            pair = [row.get("low_result"), row.get("high_result")]
            pair = [float(v) for v in pair if v is not None]
            if pair:
                drawing.add(String(position(max(pair)) + 4, y, _pdf_num(max(pair), digits),
                                   fontName=regular, fontSize=6.5,
                                   fillColor=colors.HexColor("#777777")))
        drawing.add(Line(position(base), 2, position(base), height - 4,
                         strokeColor=colors.HexColor("#111111"), strokeWidth=1))
        return drawing

    def expense_bar_chart(items: list[dict[str, Any]]) -> Drawing | None:
        ranked = [
            {"label": str(item.get("label") or "—"), "value": float(item.get("value") or 0)}
            for item in items if float(item.get("value") or 0) > 0
        ]
        ranked.sort(key=lambda item: item["value"], reverse=True)
        if not ranked:
            return None
        if len(ranked) > 7:
            ranked = ranked[:6] + [{
                "label": "Прочие расходы",
                "value": sum(item["value"] for item in ranked[6:]),
            }]
        width, row_h = 500, 20
        height = 18 + row_h * len(ranked)
        drawing = Drawing(width, height)
        maximum = max(item["value"] for item in ranked) or 1.0
        label_width, bar_width = 174, 240
        for index, item in enumerate(ranked):
            y = height - 18 - index * row_h
            label = item["label"]
            if len(label) > 31:
                label = label[:29] + "…"
            drawing.add(String(
                0, y, label, fontName=regular, fontSize=7.5,
                fillColor=colors.HexColor("#333333"),
            ))
            drawing.add(Rect(
                label_width, y - 2,
                max(1.0, bar_width * item["value"] / maximum), 9,
                fillColor=colors.HexColor("#202020" if index == 0 else "#777777"),
                strokeColor=None,
            ))
            drawing.add(String(
                width, y, _pdf_num(item["value"] / 1_000_000_000, 2),
                fontName=bold, fontSize=7.5, textAnchor="end",
                fillColor=colors.HexColor("#222222"),
            ))
        drawing.add(String(
            width, height - 7, "млрд ₽", fontName=regular, fontSize=6.5,
            textAnchor="end", fillColor=colors.HexColor("#777777"),
        ))
        return drawing

    def line_chart(
        rows: list[dict[str, Any]],
        series: list[dict[str, Any]],
        unit: str,
        height: float = 132,
    ) -> Drawing | None:
        if not rows:
            return None
        width = 500
        left, right, bottom, top = 42, 8, 22, 22
        plot_w, plot_h = width - left - right, height - bottom - top

        values: list[float] = []
        for row in rows:
            for spec in series:
                active = spec.get("active")
                if active and not active(row):
                    continue
                values.append(float(row.get(spec["key"], 0.0) or 0.0) * float(spec.get("factor", 1.0)))
        maximum = max(values or [0.0])
        if maximum <= 0:
            return None
        maximum *= 1.08

        drawing = Drawing(width, height)
        x_at = lambda index: left + (plot_w * index / max(len(rows) - 1, 1))
        y_at = lambda value: bottom + plot_h * max(0.0, value) / maximum

        for tick in range(5):
            value = maximum * tick / 4
            y = y_at(value)
            drawing.add(Line(left, y, width - right, y, strokeColor=colors.HexColor("#E2E2E2"), strokeWidth=0.5))
            drawing.add(String(
                left - 5, y - 2, _pdf_num(value, 1), fontName=regular,
                fontSize=6.5, textAnchor="end", fillColor=colors.HexColor("#777777"),
            ))

        legend_x = left
        for spec in series:
            color = colors.HexColor(spec["color"])
            drawing.add(Line(legend_x, height - 8, legend_x + 13, height - 8, strokeColor=color, strokeWidth=2.2))
            drawing.add(String(
                legend_x + 17, height - 11, spec["label"], fontName=regular,
                fontSize=6.8, fillColor=colors.HexColor("#444444"),
            ))
            legend_x += 17 + min(105, 4.6 * len(spec["label"]))
        drawing.add(String(
            width - right, height - 11, unit, fontName=regular, fontSize=6.5,
            textAnchor="end", fillColor=colors.HexColor("#777777"),
        ))

        for spec in series:
            color = colors.HexColor(spec["color"])
            segments: list[list[tuple[float, float]]] = []
            current: list[tuple[float, float]] = []
            for index, row in enumerate(rows):
                active = spec.get("active")
                if active and not active(row):
                    if current:
                        segments.append(current)
                        current = []
                    continue
                value = float(row.get(spec["key"], 0.0) or 0.0) * float(spec.get("factor", 1.0))
                current.append((x_at(index), y_at(value)))
            if current:
                segments.append(current)
            for points in segments:
                if len(points) >= 2:
                    drawing.add(PolyLine(points, strokeColor=color, strokeWidth=2.0, fillColor=None))
                elif points:
                    drawing.add(Circle(points[0][0], points[0][1], 1.7, fillColor=color, strokeColor=None))

        marker_indexes = sorted(set([0, len(rows) // 2, len(rows) - 1]))
        for index in marker_indexes:
            drawing.add(String(
                x_at(index), 5, chart_month(rows[index].get("month")),
                fontName=regular, fontSize=6.4, textAnchor="middle",
                fillColor=colors.HexColor("#777777"),
            ))
        return drawing

    def sales_bar_chart(rows: list[dict[str, Any]], height: float = 108,
                        key: str = "sales", factor: float = 1 / 1_000_000_000,
                        unit_label: str = "млрд ₽/мес.", digits: int = 1) -> Drawing | None:
        if not rows:
            return None
        values = [max(0.0, float(row.get(key, 0.0) or 0.0) * factor) for row in rows]
        maximum = max(values or [0.0])
        if maximum <= 0:
            return None
        width = 500
        left, right, bottom, top = 42, 8, 21, 12
        plot_w, plot_h = width - left - right, height - bottom - top
        maximum *= 1.08
        drawing = Drawing(width, height)
        for tick in range(4):
            value = maximum * tick / 3
            y = bottom + plot_h * value / maximum
            drawing.add(Line(left, y, width - right, y, strokeColor=colors.HexColor("#E5E5E5"), strokeWidth=0.5))
            drawing.add(String(
                left - 5, y - 2, _pdf_num(value, digits), fontName=regular,
                fontSize=6.5, textAnchor="end", fillColor=colors.HexColor("#777777"),
            ))
        slot = plot_w / max(len(rows), 1)
        bar_width = max(1.0, slot * 0.72)
        for index, value in enumerate(values):
            if value <= 0:
                continue
            x = left + index * slot + (slot - bar_width) / 2
            drawing.add(Rect(
                x, bottom, bar_width, plot_h * value / maximum,
                fillColor=colors.HexColor("#202020"), strokeColor=None,
            ))
        drawing.add(String(
            width - right, height - 8, unit_label, fontName=regular,
            fontSize=6.5, textAnchor="end", fillColor=colors.HexColor("#777777"),
        ))
        for index in sorted(set([0, len(rows) // 2, len(rows) - 1])):
            x = left + (index + 0.5) * slot
            drawing.add(String(
                x, 4, chart_month(rows[index].get("month")),
                fontName=regular, fontSize=6.4, textAnchor="middle",
                fillColor=colors.HexColor("#777777"),
            ))
        return drawing

    def gantt_drawings(items: list[dict[str, Any]], chunk_size: int = 18) -> list[Drawing]:
        """Build a real calendar Gantt for the PDF report.

        Bars are positioned by actual project dates. Milestones are diamonds.
        Multi-phase projects keep separate event rows and use phase colours.
        Long calendars are split into several repeated-axis drawings.
        """
        prepared: list[dict[str, Any]] = []
        for raw in items:
            try:
                start = d(raw.get("start"))
                end = d(raw.get("end") or raw.get("start"))
            except Exception:
                continue
            if end < start:
                start, end = end, start
            item = dict(raw)
            item["_start"] = start
            item["_end"] = end
            prepared.append(item)
        if not prepared:
            return []

        first = min(item["_start"] for item in prepared)
        last = max(item["_end"] for item in prepared)
        q_month = ((first.month - 1) // 3) * 3 + 1
        horizon_start = date(first.year, q_month, 1)
        last_q_month = ((last.month - 1) // 3) * 3 + 1
        horizon_end = add_months(date(last.year, last_q_month, 1), 3)
        total_days = max(1, (horizon_end - horizon_start).days)

        width = 500.0
        label_width = 148.0
        track_x = label_width
        track_width = width - label_width
        axis_height = 36.0
        row_height = 19.0
        phase_palette = ["#171717", "#A35D00", "#2D6A4F", "#4F6D7A", "#7A5C61"]
        group_palette = {
            "Финансирование": "#4B4B4B",
            "Продажи": "#7B7B7B",
            "Социальная нагрузка": "#A0A0A0",
            "Строительство": "#202020",
            "Подготовка": "#666666",
            "Ключевые вехи": "#111111",
        }

        def x_at(value: date) -> float:
            ratio = (value - horizon_start).days / total_days
            return track_x + track_width * max(0.0, min(1.0, ratio))

        chunks = [prepared[i:i + chunk_size] for i in range(0, len(prepared), chunk_size)]
        drawings: list[Drawing] = []
        for chunk in chunks:
            rows: list[tuple[str, Any]] = []
            previous_group = None
            for item in chunk:
                group = str(item.get("group") or "Прочее")
                if group != previous_group:
                    rows.append(("group", group))
                    previous_group = group
                rows.append(("event", item))

            height = axis_height + row_height * len(rows) + 4.0
            drawing = Drawing(width, height)
            body_top = height - axis_height

            drawing.add(Rect(0, body_top, width, axis_height, fillColor=colors.HexColor("#F6F6F4"), strokeColor=None))
            drawing.add(Line(label_width, 0, label_width, height, strokeColor=colors.HexColor("#CFCFCF"), strokeWidth=0.6))
            drawing.add(String(4, height - 13, "Этап / событие", fontName=bold, fontSize=7.4, fillColor=colors.HexColor("#222222")))

            quarter = horizon_start
            while quarter < horizon_end:
                next_quarter = add_months(quarter, 3)
                x = x_at(quarter)
                x_next = x_at(next_quarter)
                drawing.add(Line(x, 0, x, body_top, strokeColor=colors.HexColor("#DDDDDD"), strokeWidth=0.45))
                drawing.add(String((x + x_next) / 2, height - 29, f"Q{((quarter.month - 1) // 3) + 1}", fontName=regular, fontSize=6.2, textAnchor="middle", fillColor=colors.HexColor("#666666")))
                quarter = next_quarter
            drawing.add(Line(x_at(horizon_end), 0, x_at(horizon_end), body_top, strokeColor=colors.HexColor("#DDDDDD"), strokeWidth=0.45))

            for year in range(horizon_start.year, horizon_end.year + 1):
                ys = max(horizon_start, date(year, 1, 1))
                ye = min(horizon_end, date(year + 1, 1, 1))
                if ye <= ys:
                    continue
                x1, x2 = x_at(ys), x_at(ye)
                drawing.add(String((x1 + x2) / 2, height - 12, str(year), fontName=bold, fontSize=7.0, textAnchor="middle", fillColor=colors.HexColor("#333333")))
                drawing.add(Line(x1, 0, x1, height, strokeColor=colors.HexColor("#B9B9B9"), strokeWidth=0.75))

            for row_index, (kind, value) in enumerate(rows):
                y = body_top - (row_index + 1) * row_height
                drawing.add(Line(0, y, width, y, strokeColor=colors.HexColor("#E4E4E4"), strokeWidth=0.4))
                if kind == "group":
                    drawing.add(Rect(0, y, width, row_height, fillColor=colors.HexColor("#F1F1EF"), strokeColor=None))
                    drawing.add(String(4, y + 6, str(value).upper(), fontName=bold, fontSize=6.5, fillColor=colors.HexColor("#666666")))
                    continue

                item = value
                label = str(item.get("label") or "—")
                phase_name = str(item.get("phase_name") or "").strip()
                if phase_name and phase_name.lower() not in label.lower():
                    label = f"{phase_name} · {label}"
                if len(label) > 34:
                    label = label[:32] + "…"
                start = item["_start"]
                end = item["_end"]
                drawing.add(String(4, y + 9, label, fontName=regular, fontSize=6.7, fillColor=colors.HexColor("#222222")))
                date_label = start.strftime("%m.%Y") if start == end else f"{start.strftime('%m.%Y')}—{end.strftime('%m.%Y')}"
                drawing.add(String(4, y + 2.3, date_label, fontName=regular, fontSize=5.4, fillColor=colors.HexColor("#777777")))

                phase_index = int(item.get("phase_index") or 0)
                colour = phase_palette[min(max(phase_index - 1, 0), len(phase_palette) - 1)] if phase_index else group_palette.get(str(item.get("group") or ""), "#333333")
                fill = colors.HexColor(colour)
                x1 = x_at(start)
                x2 = x_at(end + timedelta(days=1))
                centre_y = y + row_height / 2
                milestone = str(item.get("kind") or "") == "milestone" or start == end
                if milestone:
                    size = 4.1
                    drawing.add(Polygon([x1, centre_y + size, x1 + size, centre_y, x1, centre_y - size, x1 - size, centre_y], fillColor=fill, strokeColor=None))
                else:
                    drawing.add(Rect(x1, centre_y - 4.0, max(2.2, x2 - x1), 8.0, fillColor=fill, strokeColor=None))

            drawing.add(Line(0, 0, width, 0, strokeColor=colors.HexColor("#CFCFCF"), strokeWidth=0.6))
            drawings.append(drawing)
        return drawings

    story=[P("DevelopAid",h1),P("Инвестиционный отчёт по девелоперскому проекту",h2),P(title_scope,ParagraphStyle("scope",parent=h2,fontSize=11,textColor=colors.HexColor('#555555')))]
    meta=[["Дата расчёта",date.today().strftime("%d.%m.%Y")],["Источник ТЭП",source_label],[class_title,class_label],["Сценарий",scenario_label]]
    # Класс жилья у проекта без жилья ничего не значит (`report_layout.housing`).
    if not (report.get("layout") or {}).get("housing", True):
        meta=[row for row in meta if row[0]!="Класс жилья"]
    # Один расчёт — один идентификатор: у пары «PDF + книга» из одного ответа
    # бота он совпадает, и сверка начинается с него, а не со спора о версиях.
    meta.append(["Идентификатор расчёта",
                 f"{_calculation_fingerprint(inputs, payload.get('tep'), payload.get('phasing'))}"
                 f" · DevelopAid {VERSION}"])
    if cads: meta.append(["Кадастровые номера",", ".join(str(x) for x in cads)])
    parity_problems = [str(item) for item in (payload.get("parity_problems") or [])]
    story += [Spacer(1,4*mm),table(meta,[45*mm,125*mm],header=False),Spacer(1,5*mm)]
    if parity_problems:
        story.append(P(
            "<b>Расчёт в окне разошёлся с расчётом на сервере.</b> В отчёт взяты "
            "числа сервера: " + "; ".join(parity_problems[:4])
            + ". Чаще всего это старая страница в браузере — обновите её.",
            ParagraphStyle("parity", parent=small, fontSize=8.0,
                           textColor=colors.HexColor("#A35D00"))))
    # Реализуемость посадки идёт ПЕРЕД финансовым выводом (архитектура,
    # раздел «Места в интерфейсе»): сначала что мешает строить, потом деньги.
    # Отчёт не имеет права падать из-за внешнего сервиса — раздел пропускается.
    try:
        screening_numbers = _pdf_screening_numbers(inputs)
        screening = land_screening(cad=",".join(screening_numbers)) if screening_numbers else None
    except Exception:
        screening = None
    if screening:
        verdict = screening.get("verdict") or {}
        story.append(_PdfSection("screening"))
        story.append(P("Реализуемость посадки", h2))
        story.append(P(verdict.get("headline", ""), ParagraphStyle(
            "screening_head", parent=normal, fontName=bold, fontSize=9.5)))
        rows = [["Ограничение", "Влияние", "Основание"]]
        for parcel in screening.get("parcels") or []:
            for finding in parcel.get("findings") or []:
                mark = {"killer": "СТОП", "economic": "ВЛИЯЕТ"}.get(
                    finding.get("flag_class"), "справка")
                numbers = finding.get("reg_numbers") or (
                    [finding.get("reg_number")] if finding.get("reg_number") else [])
                basis = ", ".join(str(n) for n in numbers if n)
                if finding.get("document_number"):
                    basis = (basis + " · " if basis else "") + str(finding["document_number"])
                share = finding.get("coverage_pct")
                impact = str(finding.get("impact", ""))
                if share is not None:
                    impact = f"{impact} · накрывает ~{_pdf_num(share, 0)}% участка".strip(" ·")
                rows.append([f"{mark} · {finding.get('name','')}", impact, basis or "—"])
        if len(rows) > 1:
            story.append(table(rows, [70*mm, 60*mm, 40*mm]))
        elif verdict.get("status") == "NOT_SCREENED":
            # Та же честность, что и на экране: не спрашивали — значит не знаем.
            story.append(P("Ограничения не проверялись: по номеру нет сведений ЕГРН.", small))
        else:
            story.append(P("В НСПД ограничений на участок не обнаружено.", small))
        if verdict.get("free_pct") is not None:
            story.append(P(
                f"Свободно от ограничений ~{_pdf_num(verdict['free_pct'], 0)}% площади участка "
                "(оценка наложением границ зон на контур ЕГРН, точность порядка процента).",
                small))
        story.append(P(verdict.get("disclaimer", ""), small))
        story.append(Spacer(1, 4*mm))
    story.append(_PdfSection("summary"));story.append(P("Ключевая экономика",h2))
    # Прибыль при непогашенном долге — бумажная: для инвестора проект
    # дефолтный, а не прибыльный (решение владельца, 27.08.2026), и строка
    # прибыли обязана говорить это сама, а не полагаться на вывод ниже.
    _carried_out=float(financing.get('debt_carried_out') or 0)
    # Три разных исхода, и оговорка у каждого своя. Средний прежде молчал:
    # долг не погашен в РВЭ, но остаточные продажи закрыли его к концу
    # горизонта — и прибыль печаталась голым числом, хотя держится она на
    # согласии банка, которого в модели не спрашивали.
    _default_note=(" — бумажная: долг не погашен" if float(financing.get('ending_pf') or 0)>500_000
                   else " — условная: в модели дефолт, долг закрыт продажами "
                        "следующих периодов" if str(financing.get('default_date') or '').strip()
                   else " — долг очереди принят следующей" if _carried_out>500_000 else "")
    kpis=[
        *_pdf_entry_cost_rows(result, expense_structure),
        ["Выручка",_pdf_money(summary.get('revenue'))],["Расходы всего",_pdf_money(summary.get('total_expenses'))],["EBITDA",_pdf_money(summary.get('ebitda'))],["Чистая прибыль",_pdf_money(summary.get('net_profit'))+_default_note],["Маржинальность",_pdf_pct(summary.get('margin'))],["LLCR",_pdf_num(summary.get('llcr'),2)+"x"],["Расчётный БРИДЖ",_pdf_money(financing.get('calculated_bridge'))],["Фактический пик БРИДЖ",_pdf_money(financing.get('actual_bridge'))],["Пиковая (непокрытая эскроу) задолженность ПФ",_pdf_money(financing.get('pf_uncovered_peak'))],["Проценты и комиссии",_pdf_money(financing.get('interest_and_fees'))],
    ]
    # Остаток ПФ на конец проекта — это несостоявшееся погашение, а не деталь
    # финансирования: без него отчёт выглядел безупречно при непогашенном долге.
    _ending_pf=float(financing.get('ending_pf') or 0)
    _rve_pf_shortfall=float(financing.get('rve_pf_shortfall') or 0)
    if _rve_pf_shortfall>500_000:
        kpis.append(["Остаток ПФ после раскрытия эскроу в РВЭ",
                     _pdf_money(_rve_pf_shortfall)])
    # Непокрытая потребность — у числа, а не только в плашке вердикта: плашку
    # пролистывают, таблицу показателей нет. Требуемый лимит печатается рядом
    # с одобренным — «не хватает 16 млрд» без обеих баз не проверить.
    _pf_gap=float(financing.get('pf_shortfall') or 0)
    if _pf_gap>500_000:
        kpis.append(["Требуемый лимит ПФ",_pdf_money(financing.get('pf_limit_required'))])
        kpis.append(["Одобренный лимит ПФ",_pdf_money(financing.get('pf_limit_approved'))])
        kpis.append(["Непокрытая потребность в ПФ (финансирование не закрыто)",
                     _pdf_money(_pf_gap)])
    if _ending_pf>500_000:
        kpis.append(["Непогашенный долг ПФ на конец проекта",_pdf_money(_ending_pf)])
    elif _carried_out>500_000:
        kpis.append(["Долг передан в ПФ следующей очереди",_pdf_money(_carried_out)])
    # Нежилой проект без ДДУ: БРИДЖа, ПФ и LLCR у него нет — строки банка
    # уходят, а на их место встают деньги объектов (`report.layout`).
    _layout = report.get("layout") or {}
    if _layout and not _layout.get("project_finance", True):
        _bank = {"LLCR", "Расчётный БРИДЖ", "Фактический пик БРИДЖ",
                 "Пиковая (непокрытая эскроу) задолженность ПФ"}
        kpis = [row for row in kpis if row[0] not in _bank]
    kpis += [[str(t.get("label") or ""), _pdf_nonres_value(t)]
             for t in _layout.get("nonres_tiles") or []]
    story.append(table([["Показатель","Значение"]]+kpis,[112*mm,58*mm]))
    story.append(_PdfSection("vri"))
    # Основание платы за ВРИ — тремя множителями формулы ГлавАПУ. Расхождение
    # платы между двумя расчётами одного участка всегда сидит в одном из них
    # (чаще в базовой стоимости — город индексирует её поквартально), и без
    # расшифровки его приходилось искать перепиской со скриншотами.
    _vri_src = (inputs.get("_glavapu_import") or {}).get("normalized") or {}
    _vri_spp = float(_vri_src.get("spp_total_sqm") or 0)
    _vri_rent = _vri_src.get("rent_coefficient")
    _vri_base = _vri_src.get("vri_base_cost_rub")
    if _vri_spp > 0 and _vri_rent and _vri_base:
        story.append(P(
            f"Плата за смену ВРИ — по формуле ГлавАПУ: СПП {_pdf_num(_vri_spp, 0)} м²"
            f" × коэффициент аренды {_pdf_num(_vri_rent, 4)}"
            f" × базовая стоимость {_pdf_num(_vri_base, 0)} ₽/м² × 1,8964."
            " Базовую стоимость город индексирует поквартально — расчёты разных"
            " дат по одному участку могут отличаться на величину индексации.",
            small))
    story.append(_PdfSection("summary"))
    # Удельная экономика проекта была только в книге и на странице, а в отчёте
    # её не было вовсе: решение принимают по рублю на метр, а не по миллиардам.
    # Обе базы обязаны стоять рядом — на ГНС считают стройку, на продаваемую
    # сравнивают с ценой продажи, и подмена одной другой ошибается вдвое.
    unit_economics = report.get("unit_economics") or []
    if unit_economics:
        # Каждая строка — на свою базу, и база названа в строке (решение 4
        # ревизии книги); вторая колонка — на продаваемую, для сравнения с
        # ценой. У строк, чья база и есть продаваемая, она не повторяется.
        ue_rows = [["Показатель", "Всего", "На м² своей базы", "База",
                    "тыс ₽/м² продаваемой"]]
        for item in unit_economics:
            ue_rows.append([
                str(item.get("label") or "—"),
                _pdf_money(item.get("total")),
                _pdf_unit_num(item.get("per_base_th"), 1),
                _pdf_unit_base(item),
                _pdf_unit_saleable(item, 1),
            ])
        story.append(KeepTogether([
            P("Удельная экономика проекта", h2),
            table(ue_rows, [40*mm, 32*mm, 24*mm, 50*mm, 24*mm], font_size=7.2),
            # База — НАЗЕМНАЯ площадь: подземная в ГНС не входит, у неё своя
            # экономика — свой метр стройки и продукт, продаваемый местами
            # (решение владельца, 04.09.2026). Строительный объём стоит рядом
            # своим числом: на нём считаются общие статьи, и без него удельный
            # показатель читается как посчитанный по всему объёму. Термин наш:
            # город считает нагрузки от суммарной поэтажной площади.
            P(_pdf_unit_bases_note(summary) + " "
              "Общие статьи (ИРД, проектирование, подготовка, "
              f"сети, сдача, содержание) считаются от {_project_articles_term(tep_report).genitive} — "
              f"{_pdf_num(_project_articles_sqm(tep_report), 0)} м²: "
              + ("квартиры, коммерция 1 этажа, подземный паркинг и кладовые. "
                 if _project_articles_term(tep_report) is CORE_TOTAL_AREA
                 else "здания объектов и их подземные гаражи. ") +
              f"База продаваемой — {_pdf_num(summary.get('monetizable_saleable_sqm'), 0)} м² "
              "монетизируемой площади (паркинг и кладовые продаются штуками и в неё "
              "не входят). Показатели на метр — термины финансовой модели DevelopAid, "
              "а не градостроительной методики: город считает нагрузки от суммарной "
              "поэтажной площади.", small),
        ]))
    story.append(_PdfSection("expenses_detail"))
    # Удельные расходы стройки — детализация структуры расходов, а не свод:
    # по ним читается себестоимость, но читать её раньше ТЭП бессмысленно.
    construction_costs = report.get("construction_costs") or []
    if construction_costs:
        # Вторая база в заголовке обязательна: без неё 23 тыс ₽/м² подземной
        # части читались как ставка на подземный метр (она — 190, во вводных).
        # СМР — на ту часть, на которую начислено; прочие статьи — на
        # суммарную площадь в ГНС. База — в строке, из движка.
        cc_rows = [["Статья", "млн ₽", "На м² своей базы", "База",
                    "тыс ₽/м² продаваемой"]]
        for item in construction_costs:
            cc_rows.append([
                str(item.get("label") or "—"),
                _pdf_num(float(item.get("value") or 0) / 1e6, 1),
                _pdf_unit_num(item.get("per_base_th"), 2),
                _pdf_unit_base(item),
                _pdf_unit_saleable(item, 2),
            ])
        story.append(KeepTogether([
            P("Удельные расходы строительства", h2),
            table(cc_rows, [52*mm, 22*mm, 24*mm, 48*mm, 24*mm], font_size=7.2),
            P("Внутренние инженерные сети входят в СМР соответствующей части.", small),
        ]))
    story.append(_PdfSection("summary"))
    purchase_assessment = _purchase_feasibility(
        inputs.get("purchase_price_mln"),
        float(summary.get("net_profit") or 0) / 1_000_000,
        summary.get("llcr"),
        max(
            float(financing.get("calculated_bridge") or 0),
            float(financing.get("pf_uncovered_peak") or 0),
        ),
        float(financing.get("ending_pf") or 0) / 1_000_000,
        financing.get("default_date"),
        float(financing.get("pf_shortfall") or 0) / 1_000_000,
        financing.get("pf_shortfall_month"),
        _layout_dscr(report.get("layout")),
        _layout_no_debt_cover(report.get("layout")),
    )
    story.append(KeepTogether([
        P("Оценка целесообразности покупки", h2),
        table([
            ["Вывод", purchase_assessment["title"]],
            ["Основание", purchase_assessment["text"]],
        ], [45*mm, 125*mm], header=False, font_size=8.0),
    ]))
    story.append(_PdfSection("tep"));story.append(P("ТЭП",h2))
    # Переданные метры строятся и не продаются: в продаваемой их нет.
    # В книге колонка переданного была с самого начала, а отчёт о
    # переданном молчал — и читался так, будто продано всё построенное
    # (владелец, 10.09.2026). Колонка появляется вместе с числом: постоянный
    # столбец нулей — шум, а не полнота.
    # Строка продукта, которого нет в проекте, не печатается — то же
    # правило, что у ТЭП тизера (`row_listed`).
    rows_data = [row for row in (tep_report.get('rows') or []) if row_listed(row)]
    total=tep_report.get('total') or {}
    given = sum(float(row.get('transfer') or 0) for row in rows_data)
    # Итог количества — разбор по мере счёта, а не сумма: квартиры,
    # машино-места и места детского сада складывались в число, не значащее
    # ничего. Строка продукта тоже называет свою меру: «250 шт.» у ДОО читалось
    # как штуки, а это места.
    # Итог — мера на строку: через « · » в одну строку он разваливался в
    # узкой колонке на семь обрывков.
    def _count(row):
        measure = tep_count_measure(row.get('key'))
        return _pdf_count_text(row.get('units'), measure) if measure else '—'
    _counts = '\n'.join(_pdf_count_text(value, measure)
                        for measure, value in (total.get('units_by_measure') or {}).items()
                        if value) or '—'
    # Свой паркинг отдельно стоящего объекта — продукт, и в ТЭП он стоит
    # подстрокой с местами, как на экране: полем на строке объекта его в
    # печати не было вовсе. Метры гаража названы в подписи — в колонке ГНС
    # они читались бы наземными. В итог эти места входят через разбор по мере
    # счёта: там они в графе «м/м», отдельно складывать их нечего.
    def _park_label(row):
        under=float(row.get('parking_under_units') or 0)
        over=float(row.get('parking_over_units') or 0)
        sold=float(row.get('parking_saleable_units') or 0)
        where=[]
        if under: where.append("подземных "+_pdf_num(under,0)
                               +(f" (гараж {_pdf_num(row.get('under_gns'),0)} м²)"
                                 if float(row.get('under_gns') or 0) else ""))
        if over: where.append("на первых этажах "+_pdf_num(over,0)+" (в ГНС здания)")
        guest=float(row.get('parking_guest_units') or 0)
        tail=("продаётся "+_pdf_num(sold,0)+(", гостевых "+_pdf_num(guest,0) if guest else "")
              if sold else "не продаются — обеспечивают посетителей")
        return "   в т.ч. паркинг объекта, мест: "+"; ".join(where+[tail])
    def _park_count(row):
        return _pdf_count_text(row.get('parking_units'), COUNT_PARKING)

    def _tep_widths(rows, middle):
        """Колонка «Кол-во» — по своему содержимому, остаток — названию."""
        count_w = _pdf_count_column_width([row[-1] for row in rows[1:]], regular,
                                          normal.fontSize, 5, 22*mm)
        return [170*mm - sum(middle) - count_w, *middle, count_w]
    if given > 0:
        tep_rows=[["Продукт",TOTAL_AREA.with_unit(),"Продаваемая, м²",
                   f"{TRANSFER_WORD}, м²","Кол-во"]]
        for row in rows_data:
            tep_rows.append([row.get('label') or row.get('key') or '—',
                             _pdf_num(row.get('gns'),0),_pdf_num(row.get('saleable'),0),
                             _pdf_num(row.get('transfer'),0),_count(row)])
            if float(row.get('parking_units') or 0):
                tep_rows.append([_park_label(row),"—","—","—",_park_count(row)])
        tep_rows.append(["Итого",_pdf_num(total.get('gns'),0),_pdf_num(total.get('saleable'),0),
                         _pdf_num(given,0),_counts])
        story.append(table(tep_rows,_tep_widths(tep_rows,[28*mm,30*mm,30*mm])))
        story.append(P("Переданные метры строятся, но не продаются: в продаваемой "
                       f"площади их нет. {TRANSFER_RECIPIENT_NOTE.capitalize()}.",
                       small))
    else:
        tep_rows=[["Продукт",TOTAL_AREA.with_unit(),"Продаваемая, м²","Кол-во"]]
        for row in rows_data:
            tep_rows.append([row.get('label') or row.get('key') or '—',_pdf_num(row.get('gns'),0),_pdf_num(row.get('saleable'),0),_count(row)])
            if float(row.get('parking_units') or 0):
                tep_rows.append([_park_label(row),"—","—",_park_count(row)])
        tep_rows.append(["Итого",_pdf_num(total.get('gns'),0),_pdf_num(total.get('saleable'),0),_counts])
        story.append(table(tep_rows,_tep_widths(tep_rows,[32*mm,36*mm])))

    # Очередность меняет проект целиком — сроки, инфляцию затрат, стартовые цены
    # и нагрузку по финансированию, — а отчёт о ней молчал: сводные цифры были,
    # а из чего они сложились, увидеть было негде.
    comparison = result.get("comparison") or []
    if len(comparison) > 1:
        story.append(_PdfSection("phases"));story.append(P("Очереди проекта",h2))
        phase_cfg = {str(item.get("name") or ""): item for item in
                     ((payload.get("phasing") or {}).get("phases") or [])}
        params=[["Очередь","Сдвиг старта, мес.","Строительство, мес.","Инфляция затрат","Индексация цены"]]
        for item in comparison:
            cfg = phase_cfg.get(str(item.get("name") or "")) or {}
            params.append([
                str(item.get("name") or "—"),
                _pdf_num(cfg.get("start_offset_months"),0) if cfg else "—",
                _pdf_num(cfg.get("construction_months"),0) if cfg else "—",
                _pdf_num((float(item.get("cost_inflation_factor") or 1)-1)*100,1)+"%",
                _pdf_num((float(item.get("sales_price_inflation_factor") or 1)-1)*100,1)+"%",
            ])
        story.append(table(params,[30*mm,35*mm,38*mm,34*mm,33*mm],font_size=7.4))
        story.append(P("Сравнение очередей",h2))
        # Та же таблица, что на странице, и из того же места —
        # `phase_comparison_table`: состав, порядок блоков и числа решает
        # движок, PDF только печатает. Прежде отчёт печатал своё сравнение
        # пятью таблицами в своём порядке, и две раскладки одного сравнения
        # расходились (владелец, 27.09.2026: «PDF тоже надо сделать то же»).
        story.append(_phase_comparison_pdf(phase_comparison_table(result), regular, bold, colors))
        story.append(P("Удельные показатели — в тыс. ₽ за м² своего делителя; итог по ним — "
                       "отношение сумм, а не среднее по очередям.", small))
        # Причина, по которой долг сменил очередь или остался на своей: без неё
        # обнулённый долг первой очереди рядом с выросшим долгом второй
        # читается как ошибка расчёта. Раздел «Непогашенный долг и перенос
        # между очередями» стал строками блока «Финансирование»; здесь —
        # объяснение к ним.
        _carry = result.get("debt_carry") if isinstance(result.get("debt_carry"), dict) else {}
        _has_debt = any(
            float(i.get("ending_pf") or 0) > 500_000
            or float(i.get("debt_carried_out") or 0) > 500_000
            or float(i.get("carried_debt_in") or 0) > 500_000
            for i in comparison)
        if _carry.get("note"):
            story.append(P(str(_carry["note"]),small))
        elif _has_debt:
            story.append(P(
                "Перенос долга между очередями выключен: непогашенный остаток "
                "остаётся на очереди, которая его набрала, и означает дефолт по "
                "её линии. Итог по проекту при этом складывается из очередей.",small))
        phase_financing = result.get("phase_financing") or {}
        if phase_financing.get("rows"):
            story.append(P(
                ("Единый денежный поток проекта включён. " if phase_financing.get("enabled")
                 else "Независимое финансирование очередей включено. ")
                + "Свободный cash учитывается только после обслуживания долга более ранней "
                  "очереди; эскроу, будущая прибыль и банковские лимиты не используются.", small))
        # Кассовая и аллоцированная прибыль очереди — разные показатели с
        # одинаковой суммой по проекту; без словаря их сравнивали лоб в лоб
        # с книгой и читали методику как расхождение моделей.
        allocated_parts = [
            f"{item.get('name')}: {_pdf_money(item.get('allocated_net_profit'))}"
            for item in comparison if item.get("allocated_net_profit") is not None]
        if allocated_parts:
            story.append(P(
                "Чистая прибыль очередей — кассовая, как в CF-листах Excel-книги: общие "
                "расходы (покупка, ВРИ, соцнагрузка) стоят в очереди их оплаты. "
                "Аллоцированная прибыль разносит их экономически: "
                + "; ".join(allocated_parts)
                + ". Сумма по проекту в обеих раскладках одна.", small))

    # Раздел появляется только если чувствительность считали на вкладке.
    # Гнать полсотни расчётов внутри сборки PDF ради раздела, который никто не
    # просил, незачем — а сборка отчёта и так идёт следом за карточкой.
    sensitivity = payload.get("sensitivity") if isinstance(payload.get("sensitivity"), dict) else None
    if sensitivity and (sensitivity.get("items") or []):
        base = sensitivity.get("base") or {}
        digits = int(base.get("digits") or 2)
        rows = list(sensitivity["items"])[:14]
        story.append(_PdfSection("sensitivity"))
        story.append(P("Чувствительность проекта",h2))
        story.append(P(
            f"Показатель: {base.get('label') or ''} · база "
            f"{_pdf_num(base.get('value'), digits)} {base.get('unit') or ''} · "
            f"охват: {base.get('scope_label') or ''}"
            + ("" if base.get("project_value") is None else
               f" (не весь проект: у проекта {_pdf_num(base.get('project_value'), digits)} "
               f"{base.get('unit') or ''})")
            + " · отклонение "
            f"{_pdf_num(sensitivity.get('change_pct'), 0)}% и "
            f"{_pdf_num(sensitivity.get('duration_change_months'), 0)} мес. для сроков. "
            "Меняется один параметр за расчёт.", small))
        chart = tornado_chart(rows, float(base.get("value") or 0), digits)
        if chart:
            story.extend([chart, Spacer(1, 3*mm)])
        table_rows=[["Параметр","Ниже","Выше","Размах"]]
        for row in rows:
            table_rows.append([
                str(row.get("label") or "—"),
                _pdf_num(row.get("low_result"), digits),
                _pdf_num(row.get("high_result"), digits),
                _pdf_num(row.get("impact"), digits),
            ])
        story.append(table(table_rows,[92*mm,26*mm,26*mm,26*mm],font_size=7.4))
        for line in (sensitivity.get("verdict") or []):
            story.append(P(str(line), small))

    story.append(_PdfSection("premises"));story.append(P("Цены и основные предпосылки",h2))
    # Класс — то же решение, что у карточки «Ключевые параметры»
    # (`project_class_view`): у гостиницы — звёздность, а не класс жилья.
    _class_dev=project_class_view(inputs)
    premise_rows=[["Параметр","Значение"],[_class_dev["title"],_class_dev["label"]],["Стартовая цена квартир",_pdf_num(inputs.get('apartment_price_th'),0)+" тыс. ₽/м²"],["Стартовая цена коммерции",_pdf_num(inputs.get('commercial_price_th'),0)+" тыс. ₽/м²"],["Цена подземного машино-места",_pdf_num(inputs.get('parking_price_th'),0)+" тыс. ₽/шт."],["СМР наземной части",_pdf_num(inputs.get('main_above_th_per_sqm'),0)+" тыс. ₽/м² наземной части"],["СМР подземной части",_pdf_num(inputs.get('main_under_th_per_sqm'),0)+" тыс. ₽/м² подземной части"],["Наружные инженерные сети, в т.ч. техприсоединение",_pdf_num(inputs.get('utilities_th_per_sqm'),1)+" тыс. ₽/м² "+CORE_TOTAL_AREA.genitive],["Доля продаж до РВЭ",_pdf_num(inputs.get('share_before_rve_pct'),1)+"%"],["Налог на прибыль",_pdf_num(inputs.get('profit_tax_pct'),1)+"%"]]
    # Тип проекта называется только там, где он не тот, что у всех: строка
    # «Жилой / смешанный» в каждом отчёте — постоянная приписка, а такие
    # перестают читаться. Оставшееся от жилья идёт своей строкой, потому что
    # это не предпосылка, а расхождение вводных с объявленным типом.
    # Оставшееся берётся из свода, а не считается здесь заново: второй счёт
    # той же величины однажды разошёлся бы с экраном, и обе строки выглядели
    # бы верными.
    _kind = str(summary.get("project_kind") or "")
    if _kind in PROJECT_KINDS_WITHOUT_HOUSING:
        # Цены и темп проекта принадлежат продуктам МКД: у объекта свой
        # профиль продаж и своя цена места. Напечатанные у нежилого проекта,
        # они читались бы как предпосылки его расчёта.
        _mkd_premises = {"Стартовая цена квартир", "Стартовая цена коммерции",
                         "Цена подземного машино-места", "Доля продаж до РВЭ"}
        if _kind == PROJECT_KIND_HOTEL:
            # Стройку гостиницы считает её ставка (`hotel_cost_th_per_sqm`),
            # а не ставки жилья: СМР дома и сети класса жилья у неё не
            # участвуют, и напечатанные они читались бы её предпосылкой.
            _mkd_premises |= {"СМР наземной части", "СМР подземной части",
                              "Наружные инженерные сети, в т.ч. техприсоединение"}
        premise_rows = [row for row in premise_rows if row[0] not in _mkd_premises]
        premise_rows.append(["Тип проекта",
                             dict(PROJECT_KINDS)[_kind]
                             + (" — жилья, соцнагрузки, платы за смену ВРИ и объектов "
                                "(ТЦ, офисы, паркинг, ФОК) в расчёте нет"
                                if _kind == PROJECT_KIND_HOTEL else
                                " — жилья, соцнагрузки и платы за смену ВРИ в расчёте нет")])
        _left = [str(item) for item in (summary.get("project_kind_leftovers") or [])]
        if _left:
            # Остаток назван, но не посчитан (`residential_excluded`): без
            # пометки строка читалась бы как часть расчёта — ровно так её и
            # прочёл владелец, увидев рядом второй подземный паркинг.
            premise_rows.append(["Осталось от жилья во вводных",
                                 "; ".join(_left) + " — в расчёт не входит"])
    story.append(table(premise_rows,[105*mm,65*mm]))
    if _class_dev["rows"]:
        # Ушёл от базы — скажи об этом: молча два отчёта «одного класса»
        # разойдутся, и оба будут выглядеть достоверно.
        # Единица стоит у числа: профиль класса перестал быть только деньгами —
        # норматив площади на человека это м²/чел., и «5 → 8» без единицы
        # читается ставкой. Слово «ставки» по той же причине снято.
        _dev_text="; ".join(
            f"{item['label']} {_pdf_num(item['base'],1)} → {_pdf_num(item['actual'],1)}"
            + (f" {item['unit']}" if item.get("unit") else "")
            for item in _class_dev["rows"])
        story.append(Spacer(1,1.5*mm))
        story.append(P(f"Отличается от базы класса «{_class_dev['label']}»: {_dev_text}.",
                       ParagraphStyle("class_dev",parent=small,fontSize=8.0,
                                      textColor=colors.HexColor("#a02418"))))
    story.append(_PdfSection("expenses"));story.append(P("Структура расходов",h2))
    expense_chart=expense_bar_chart(expense_structure)
    if expense_chart:
        story.extend([expense_chart,Spacer(1,2*mm)])
    # Рубль на метр — в обеих базах, как во всех удельных отчёта: именно по
    # этим статьям спорят с подрядчиком и с банком, а в долях процента спор
    # не ведут.
    # Все строки — расходы, база у них одна (решение 4 ревизии книги):
    # суммарная площадь в ГНС; подпись — из словаря терминов.
    expense_rows=[["Статья","Сумма","Доля",unit_label(UNIT_BASE_TOTAL).replace("тыс. ","тыс "),"тыс ₽/м² продаваемой"]]
    total_expense=sum(float(item.get('value') or 0) for item in expense_structure) or float(summary.get('total_expenses') or 0)
    for item in expense_structure:
        value=float(item.get('value') or 0)
        if value==0: continue
        # Удельные берутся из расчёта, без запасного счёта на месте. Запасной
        # счёт здесь уже стоил дорого: свод по очередям приходил без удельных,
        # печать досчитывала их сама и выглядела безупречно, а страница
        # показывала нули во всех строках. Одна поверхность прикрывала ошибку
        # другой, и найти её удалось только глазами.
        expense_rows.append([item.get('label') or '—',_pdf_money(value),
                             (_pdf_num(value/total_expense*100,1)+'%') if total_expense else '—',
                             _pdf_unit_num(item.get('per_base_th'),1),
                             _pdf_unit_num(item.get('per_saleable_th'),1)])
        # Отдельно стоящий объект меряется своей площадью, наземный паркинг —
        # своими местами. Числа считает движок; отчёт носят в банк, и
        # расходиться с экраном ему нельзя — подстроки те же.
        # Строки объекта собраны движком — здание и свой гараж порознь, база
        # названа в ячейке, как на экране.
        for line in (l for part in item.get('items') or [] for l in part.get('lines') or []):
            _base=(" "+str(line.get('basis'))) if line.get('basis') else ""
            _gns='—' if line.get('gns_th') is None else _pdf_num(line['gns_th'],1)+_base
            if line.get('per_unit_mln') is not None:
                _sal=_pdf_num(line['per_unit_mln'],2)+" млн ₽/место"
            else:
                _sal='—' if line.get('saleable_th') is None else _pdf_num(line['saleable_th'],1)+_base
            expense_rows.append(["   в т.ч. "+str(line.get('label') or '—'),
                                 _pdf_money(line.get('value') or 0),"—",_gns,_sal])
    expense_rows.append(["Итого расходы",_pdf_money(total_expense),"100,0%" if total_expense else "—",
                         _pdf_unit_num(summary.get('full_cost_per_total_area_th'),1),
                         _pdf_num(summary.get('full_cost_per_saleable_th'),1)])
    story.append(table(expense_rows,[62*mm,32*mm,20*mm,28*mm,28*mm],font_size=7.4))
    _exp_note=next((str(i.get('items_note') or '') for i in expense_structure
                    if i.get('items') and i.get('items_note')),'')
    if _exp_note:
        story.append(P(_exp_note,small))
    # Пустая статья называется и на бумаге: нулевая строка в таблицу не
    # попадает, а отчёт носят в банк — отсутствие благоустройства там читается
    # как «его не будет», а не как «мы его не посчитали». Фраза берётся из
    # свода целиком: второй текст об одной пустоте разошёлся бы с экраном.
    _land_gap=str(summary.get('landscaping_gap') or '')
    if _land_gap:
        story.append(P(_land_gap,ParagraphStyle("land_gap",parent=small,fontSize=8.0,
                                                textColor=colors.HexColor("#a02418"))))
    story.append(_PdfSection("income"));story.append(P("Продажи и продукты",h2))
    product_rows=[["Продукт","Объём","Темп до РВЭ","Стартовая цена","Средняя цена","Выручка"]]
    for item in products:
        # Непродаваемое в таблицу ПРОДАЖ не идёт: соцобъект стоял тут строкой
        # с объёмом «350 м²» и выручкой ноль, хотя 350 — это места. Его метры
        # и мощность названы в таблице ТЭП, где у них своя мера.
        if item.get('sellable') is False or item.get('excluded'): continue
        quantity=float(item.get('quantity') or 0);revenue=float(item.get('revenue') or 0)
        built=float(item.get('built_units') or 0)
        # Паркинг объекта с местами, которые не продаются (ТЦ, ФОК), — тоже
        # строка своего объекта: построено есть, продаётся ноль, как на экране.
        if quantity<=0 and revenue<=0 and built<=0: continue
        unit=item.get('unit') or ''
        pace=item.get('pace_pre')
        volume=_pdf_num(quantity,0)+(' '+unit if unit else '')
        if built>0:
            volume+=f" из {_pdf_num(built,0)} построенных"
        product_rows.append([item.get('label') or '—',volume,
                             (_pdf_num(pace,0)+' '+unit+'/мес') if pace else '—',
                             _pdf_num(item.get('start_price_th'),0)+" тыс. ₽",_pdf_num(item.get('avg_price_th'),0)+" тыс. ₽",_pdf_money(revenue)])
    story.append(table(product_rows,[45*mm,26*mm,28*mm,26*mm,26*mm,29*mm],font_size=7.4))
    # Профиль продаж и лестница цены объекта — под таблицей, своими словами:
    # средняя цена без них не объясняет, откуда взялась.
    for item in products:
        notes = []
        if item.get("sales_profile"):
            notes.append(f"профиль продаж {item['sales_profile']}")
        if item.get("price_ladder"):
            notes.append(f"лестница цены {item['price_ladder']}")
        notes += [str(w) for w in (item.get("schedule_warnings") or [])]
        if notes:
            story.append(P(f"{item.get('label') or '—'}: " + "; ".join(notes) + ".", small))
    # ТЦ и офисы вне ДДУ — таблицей движка (`nonres_report`), той же, что на
    # экране: прямая продажа или аренда с выходом и свой кредит объекта.
    for _nr in report.get("nonres_strategy") or []:
        _nr_rows = [["Нежильё — стратегия реализации: " + str(_nr.get("title") or ""), " "]]
        for _row in _nr.get("rows") or []:
            # Блок «Итог объекта» — заголовком строки, без значения.
            _nr_rows.append([str(_row.get("label") or "").upper()
                             if _row.get("unit") == "section" else str(_row.get("label") or ""),
                             _pdf_nonres_value(_row)])
        story.append(KeepTogether([table(_nr_rows, [112*mm, 58*mm], font_size=7.6)]
                                  + [P(str(w), small) for w in _nr.get("warnings") or []]))
    # Гостиница — таблицей движка (`hotel_report`), той же, что на экране:
    # ключевые показатели и годовой USALI. Незаполненная — названа, не нулями.
    _hotel = report.get("hotel")
    if _hotel:
        story.append(P("Гостиница — эксплуатация (USALI)", h2))
        if not _hotel.get("computed"):
            story.append(P("Гостиница не считается: не заданы "
                           + ", ".join(str(m) for m in _hotel.get("missing") or []) + ".", small))
        else:
            _h_rows = [["Показатель", "Значение"]]
            for _row in _hotel.get("rows") or []:
                _h_rows.append([str(_row.get("label") or ""), _pdf_nonres_value(_row)])
            story.append(table(_h_rows, [112*mm, 58*mm], font_size=7.4))
            for _w in _hotel.get("warnings") or []:
                story.append(P(str(_w), small))
            _usali = _hotel.get("usali") or {}
            _years = list(_usali.get("years") or [])
            # Годы — колонками, по шесть на таблицу: пятнадцать лет на А4 не
            # читаются. Деньги — в млн ₽, как в «Своде» эталонных моделей.
            for _start in range(0, len(_years), 6):
                _span = _years[_start:_start + 6]
                _u_rows = [["USALI, млн ₽"] + [str(y) for y in _span]]
                for _line in _usali.get("rows") or []:
                    _vals = (_line.get("values") or [])[_start:_start + 6]
                    _cells = []
                    for _v in _vals:
                        if _v is None:
                            _cells.append("—")
                        elif _line.get("unit") == "rub":
                            _cells.append(_pdf_num(float(_v) / 1e6, 1))
                        else:
                            _cells.append(_pdf_nonres_value({"unit": _line.get("unit"), "value": _v}))
                    _u_rows.append([str(_line.get("label") or "")] + _cells)
                _w0 = 62*mm
                story.append(table(_u_rows, [_w0] + [(170*mm - _w0) / max(1, len(_span))] * len(_span),
                                   font_size=6.8))
    # Квартиры продаются штуками. «40 квартир в месяц» проверяется отделом
    # продаж и рынком, «2 400 м² в месяц» — нет, а в отчёте был только метр.
    apartment_sales = report.get("apartment_sales") or {}
    if float(apartment_sales.get("units_total") or 0) > 0:
        story.append(KeepTogether([
            P("Темп продаж квартир", h2),
            table([
                ["Показатель", "Значение"],
                ["Квартир в проекте", _pdf_num(apartment_sales.get("units_total"), 0) + " шт."],
                ["Средняя площадь квартиры", _pdf_num(apartment_sales.get("avg_unit_sqm"), 1) + " м²"],
                ["Средняя цена квартиры", _pdf_money(float(apartment_sales.get("avg_unit_price_mln") or 0) * 1e6)],
                ["Темп до РВЭ", _pdf_num(apartment_sales.get("pace_pre_rve_units"), 1) + " кв./мес."],
                ["Средний темп за весь период продаж", _pdf_num(apartment_sales.get("pace_units"), 1) + " кв./мес."],
                ["Пиковый месяц", _pdf_num(apartment_sales.get("peak_units"), 1) + " кв."],
                ["Длительность продаж", _pdf_num(apartment_sales.get("months"), 0) + " мес."],
            ], [112*mm, 58*mm], font_size=7.6),
            P("Штуки пересчитаны из помесячных продаж по средней площади квартиры "
              "из ТЭП: изменится нарезка — изменится и темп.", small),
        ]))
    _financing_start = len(story)
    story.append(_PdfSection("financing"));story.append(P("Финансирование и динамика проекта",h2))
    # Раскрытие эскроу — событие очереди, и у каждой оно своё. На
    # многоочередном проекте подписи «в РВЭ» называли моментом сумму
    # разнесённых во времени событий (владелец, 31.08.2026). Величины те же,
    # но названы итогами; по очередям они стоят в разделе «Очереди проекта».
    _pdf_phased = len(result.get("comparison") or []) > 1
    def _pdf_rve_label(base: str) -> str:
        return f"{base} — всего" if _pdf_phased else f"{base} в РВЭ"
    finance_rows=[["Показатель","Значение"],[("Расчётный БРИДЖ — сумма лимитов очередей" if _pdf_phased else "Расчётный БРИДЖ"),_pdf_money(financing.get('calculated_bridge'))],[("Пик одновременно открытых линий БРИДЖа очередей (тело долга)" if _pdf_phased else "Пиковый фактический БРИДЖ (тело долга)"),_pdf_money(financing.get('actual_bridge'))],["Собственные средства до ПФ",_pdf_money(financing.get('own_funds'))],["Пик БРИДЖ с капитализацией процентов (справочно)",_pdf_money(financing.get('bridge_peak_capitalized') or financing.get('actual_bridge'))],["Пиковая (непокрытая эскроу) задолженность ПФ",_pdf_money(financing.get('pf_uncovered_peak'))],[_pdf_rve_label("Долг ПФ перед раскрытием"),_pdf_money(financing.get('rve_pf_before_repayment'))],[_pdf_rve_label("Раскрытый эскроу"),_pdf_money(financing.get('rve_escrow_release'))],["Из него на погашение ПФ",_pdf_money(financing.get('rve_pf_repayment'))],[_pdf_rve_label("Не покрыто эскроу при раскрытии"),_pdf_money(financing.get('rve_pf_shortfall'))],[("Лимит ПФ — сумма по очередям" if _pdf_phased else "Лимит ПФ"),_pdf_money(financing.get('pf_limit'))],*([["Общий лимит ПФ по генеральным условиям — ожидание, потолком очередей не служит",_pdf_money(financing.get('pf_limit_general'))]] if (_pdf_phased and float(financing.get('pf_limit_general') or 0)>500_000) else []),["Текущая ключевая ставка",_pdf_pct(financing.get('current_key_rate'))],["Спред БРИДЖ",_pdf_pct(financing.get('bridge_spread'))],["Ставка БРИДЖ на текущей ключевой",_pdf_pct(financing.get('current_bridge_rate'))],["Средняя ключевая за период БРИДЖ",_pdf_pct(financing.get('avg_bridge_key_rate'))],["Средневзвешенная ставка БРИДЖ за период",_pdf_pct(financing.get('avg_bridge_rate'))],["Средняя фактическая ставка ПФ",_pdf_pct(financing.get('avg_pf_effective_rate'))],*_pdf_pf_step_rows(financing),["Проценты и комиссии",_pdf_money(financing.get('interest_and_fees'))],["Непогашенный долг ПФ на конец проекта",_pdf_money(financing.get('ending_pf'))],*([["Долг передан в ПФ следующей очереди",_pdf_money(financing.get('debt_carried_out'))]] if float(financing.get('debt_carried_out') or 0)>500_000 else []),*([["в т.ч. принято от предыдущей очереди",_pdf_money(financing.get('carried_debt_in'))]] if (not _pdf_phased and float(financing.get('carried_debt_in') or 0)>500_000) else []),["LLCR",_pdf_num(summary.get('llcr'),2)+"x"]]
    story.append(table(finance_rows,[112*mm,58*mm],font_size=7.6))

    # Restore the bridge-purpose disclosure that exists in the web report.
    # VRI is deliberately absent: it is funded directly by PF at RnS/permit.
    bridge_total = float(financing.get("calculated_bridge") or 0.0)
    capex_data = result.get("capex") or {}

    # Режим «строительство и компенсация» PDF не знал: денежная часть падала
    # в ноль и молча уезжала в «приобретение проекта», а сайт в той же строке
    # показывал её отдельно. Два достоверных на вид отчёта с разными числами —
    # ровно то, что правило «поверхности считают одинаково» запрещает.
    # Состав лимита приходит из расчёта — печать его не пересобирает: в БРИДЖ
    # входит только то, что платится ДО РнС, и вычитание «итог минус…» при
    # рассрочке покупки дало бы второе, расходящееся число. Помощник общий на
    # свод и на очереди: у каждой очереди свой лимит и свой состав.
    def _bridge_uses(res: dict[str, Any]) -> tuple[float, list[tuple[str, float]]]:
        res_financing = ((res.get("report") or {}).get("financing")) or {}
        total = float(res_financing.get("calculated_bridge") or 0.0)
        parts = dict(res_financing.get("calculated_bridge_parts") or {})
        uses = [
            ("Приобретение проекта", float(parts.get("purchase") or 0.0)),
            ("Социальная компенсация", float(parts.get("social") or 0.0)),
            ("Проектирование - стадия П", float(parts.get("design_p") or 0.0)),
            ("Проектирование - стадия РД", float(parts.get("design_rd") or 0.0)),
        ]
        return total, [(label, value) for label, value in uses if value > 0.5]

    def _bridge_use_rows(total: float, uses: list[tuple[str, float]],
                         footer: str) -> list[list[str]]:
        rows = []
        for label, value in uses:
            share = _pdf_num(value / total * 100, 1) + "%" if total else "—"
            rows.append([label, _pdf_money(value), share])
        rows.append([footer, _pdf_money(total), "100,0%" if total else "—"])
        return rows

    bridge_total, bridge_uses = _bridge_uses(result)
    bridge_rows = [["Цель", "Сумма", "Доля"]] + _bridge_use_rows(
        bridge_total, bridge_uses, "ИТОГО БРИДЖ")
    # График платежей за покупку — до структуры БРИДЖа: лимит считается от
    # всей цены, а выборка идёт за платежами, и разница между ними видна
    # только когда напечатаны сроки.
    purchase_plan = report.get("purchase") or {}
    if purchase_plan.get("custom") or purchase_plan.get("warnings"):
        purchase_rows = [["Дата", "Сумма", "Доля цены"]]
        for item in purchase_plan.get("rows") or []:
            when = str(item.get("date") or "")[:10]
            purchase_rows.append([
                ".".join(reversed(when.split("-"))) if when else "—",
                _pdf_money(float(item.get("amount_mln") or 0) * 1e6),
                _pdf_num(float(item.get("share") or 0) * 100, 1) + "%",
            ])
        block = [P("График платежей за покупку", h2),
                 table(purchase_rows, [60*mm, 60*mm, 50*mm], font_size=8.0)]
        for warning in purchase_plan.get("warnings") or []:
            block.append(P(str(warning), small))
        story.append(KeepTogether(block))

    # Лимит БРИДЖа — цифра одного договора, и у проекта с очередями таких
    # договоров столько же, сколько очередей: открыты они в разные годы, и
    # сложенные в одну сумму дают лимит, которого никто не выдавал («это
    # глупость, а не расчётный бридж», владелец, 04.09.2026). Экран уже
    # разбирает его по очередям, и отчёт обязан говорить то же самое.
    _bridge_limit_phases = [item for item in (payload.get("phases") or [])
                            if isinstance(item, dict)]
    if len(_bridge_limit_phases) > 1:
        phase_bridge_rows = [["Цель", "Сумма", "Доля"]]
        for item in _bridge_limit_phases:
            name = str(item.get("name") or "Очередь")
            total_q, uses_q = _bridge_uses(item.get("result") or {})
            if not uses_q:
                phase_bridge_rows.append([name + " - лимит БРИДЖа не рассчитывается", "", ""])
                continue
            phase_bridge_rows.append([name, "", ""])
            phase_bridge_rows.extend(_bridge_use_rows(
                total_q, uses_q, "Лимит БРИДЖа " + name))
        story.append(KeepTogether([
            P("Расчётный лимит БРИДЖа - по очередям", h2),
            table(phase_bridge_rows, [98*mm, 45*mm, 27*mm], font_size=8.0),
            P("Лимит считает банк по каждому договору отдельно: у каждой очереди "
              "своя линия до открытия её ПФ. Сложенные вместе, лимиты дали бы "
              "договор, которого никто не выдавал, поэтому свода здесь нет.", small),
        ]))
    else:
        story.append(KeepTogether([
            P("Структура расчётного БРИДЖА", h2),
            table(bridge_rows, [98*mm, 45*mm, 27*mm], font_size=8.0),
        ]))

    # Фактический пик — по статьям, оплаченным к его месяцу. Без этой таблицы
    # разница между лимитом методики и реальной потребностью («остальное
    # вашими») читалась только глазами по структуре расходов.
    actual_structure = list(financing.get("actual_bridge_structure") or [])
    # По очередям — у каждой свой БРИДЖ и свой месяц пика; свод — подписью.
    pdf_phase_items = [item for item in (payload.get("phases") or []) if isinstance(item, dict)]
    if len(pdf_phase_items) > 1:
        for item in pdf_phase_items:
            pf_fin = ((item.get("result") or {}).get("report") or {}).get("financing") or {}
            rows_q = list(pf_fin.get("actual_bridge_structure") or [])
            name_q = str(item.get("name") or "Очередь")
            if not rows_q:
                continue
            peak_q = float(pf_fin.get("actual_bridge") or 0)
            month_q = str(pf_fin.get("actual_bridge_month") or "")
            table_q = [["Статья", "Оплачено к пику очереди", "Доля"]]
            for row_q in rows_q:
                table_q.append([str(row_q.get("label") or "—"), _pdf_money(float(row_q.get("value") or 0)),
                                _pdf_num(float(row_q.get("share") or 0) * 100, 1) + "%"])
            table_q.append([f"ПИК БРИДЖА {name_q}", _pdf_money(peak_q), "100,0%" if peak_q else "—"])
            story.append(KeepTogether([
                P(f"Структура фактического БРИДЖА · {name_q}"
                  + (f" · {'.'.join(reversed(month_q.split('-')))}" if month_q else ""), h2),
                table(table_q, [98*mm, 45*mm, 27*mm], font_size=8.0),
            ]))
        story.append(P("У каждой очереди свой БРИДЖ до открытия её ПФ; оплачено к месяцу пика этой очереди. "
                       + (f"Свод: наибольшая сумма одновременно открытых линий — "
                          f"{_pdf_money(float(financing.get('actual_bridge') or 0))}."
                          if financing.get("actual_bridge") else ""), small))
        actual_structure = []
    if actual_structure:
        actual_peak = float(financing.get("actual_bridge") or 0)
        actual_rows = [["Статья", "Оплачено к пику", "Доля"]]
        for item in actual_structure:
            value = float(item.get("value") or 0)
            actual_rows.append([
                str(item.get("label") or "—"), _pdf_money(value),
                _pdf_num(float(item.get("share") or 0) * 100, 1) + "%",
            ])
        actual_rows.append(["ПИК БРИДЖА", _pdf_money(actual_peak),
                            "100,0%" if actual_peak else "—"])
        month = str(financing.get("actual_bridge_month") or "")
        queues = financing.get("actual_bridge_queues") or {}
        on_bridge = [str(name) for name in (queues.get("on_bridge") or [])]
        queue_note = ""
        if on_bridge:
            tails = []
            if queues.get("refinanced"):
                tails.append(", ".join(map(str, queues["refinanced"]))
                             + " к этому месяцу уже на ПФ — их расходы сюда не входят")
            if queues.get("not_started"):
                tails.append(", ".join(map(str, queues["not_started"])) + " ещё не начаты")
            queue_note = ("Пик свода — месяц, когда на БРИДЖе " + ", ".join(on_bridge)
                          + ("; " + "; ".join(tails) if tails else "") + ". ")
        story.append(KeepTogether([
            P("Структура фактического БРИДЖА"
              + (f" · {'.'.join(reversed(month.split('-')))}" if month else "")
              + (f" · на БРИДЖе: {', '.join(on_bridge)}" if on_bridge else ""), h2),
            table(actual_rows, [98*mm, 45*mm, 27*mm], font_size=8.0),
            P(queue_note
              + "Оплачено к месяцу пика. До открытия ПФ у очереди нет ни выручки, ни ПФ, "
              "поэтому остаток её БРИДЖа равен оплаченному; разница с расчётным лимитом — "
              "расходы, под которые лимит не даётся.", small),
        ]))

    timeline_rows=list((result.get("finance") or {}).get("rows") or [])
    debt_chart=line_chart(
        timeline_rows,
        [
            {"label":"БРИДЖ","key":"bridge_balance","factor":1/1_000_000_000,"color":"#171717","active":lambda row:float(row.get("bridge_balance",0) or 0)>0},
            {"label":"ПФ","key":"pf_balance","factor":1/1_000_000_000,"color":"#A35D00","active":lambda row:float(row.get("pf_balance",0) or 0)>0},
            {"label":"Эскроу","key":"escrow","factor":1/1_000_000_000,"color":"#2D6A4F","active":lambda row:float(row.get("escrow",0) or 0)>0},
        ],
        "млрд ₽",
        height=128,
    )
    if debt_chart:
        story.append(KeepTogether([P("Долг и наполнение эскроу",h2),debt_chart]))

    # Тот же вопрос, но полной мерой: банку в раскрытие причитается тело И
    # начисленное. График выше сравнивает счёт с телом и на этот вопрос не
    # отвечает — «эскроу выше долга» читалось бы как «рассчитались».
    def escrow_cover_chart(rows: list[dict[str, Any]], cover: dict[str, Any],
                           height: float = 132) -> Drawing | None:
        """Заливка, а не линии: ответ на «перекрывает или нет» — это площадь.

        Линии отвечали хуже: две кривые рядом видно, а разрыв между ними —
        нет. Заливкой видно и его, и то, что после раскрытия остаток гасят
        продажи, а не эскроу.
        """
        def duty(row: dict[str, Any]) -> float:
            return float(row.get("pf_obligation", 0.0) or 0.0)

        def escrow_of(row: dict[str, Any]) -> float:
            return float(row.get("escrow", 0.0) or 0.0)

        data = [row for row in rows if duty(row) > 0 or escrow_of(row) > 0]
        if len(data) < 2:
            return None
        def cum_of(row: dict[str, Any], key: str) -> float:
            return float(row.get(key, 0.0) or 0.0)

        width = 500
        from reportlab.pdfbase.pdfmetrics import stringWidth
        # Легенда шире одной строки: подписей шесть, а ширина листа не растёт.
        # Раскладка считается до геометрии — иначе верхнее поле не знает,
        # сколько строк над ним.
        legend_rows, line_x = 1, 0.0
        for text, _colour, _style in _ESCROW_CHART_LEGEND:
            step = 22 + stringWidth(text, regular, 6.4)
            if line_x and line_x + step > width - 42:
                legend_rows += 1
                line_x = 0.0
            line_x += step
        left, right, bottom = 42, 30, 22
        # Легенда переносом не отнимает у графика поле, а поднимает крышу:
        # подписей стало шесть, и съеденная ими треть высоты — это сплющенный
        # долг, ровно то, от чего уходили. Подписи осей идут под легендой:
        # на одной строке с ней они наезжали друг на друга.
        height = height + 10 * (legend_rows - 1)
        top_pad = 12 + 10 * legend_rows
        plot_w, plot_h = width - left - right, height - bottom - top_pad
        peak = max(max(duty(row), escrow_of(row)) for row in data) * 1.08 or 1.0
        # Долг — «сколько должны сейчас», накопленное — «сколько пришло с
        # начала»: на одной шкале второе перерастает первое и сплющивает его
        # в нижнюю треть. У накопленного своя ось справа.
        cum_peak = max(max(cum_of(row, "escrow_released_cumulative"),
                           cum_of(row, "sales_after_rve_cumulative"))
                       for row in data) * 1.08 or 1.0
        drawing = Drawing(width, height)
        x_at = lambda i: left + plot_w * i / (len(data) - 1)
        y_at = lambda v: bottom + plot_h * max(0.0, v) / peak
        y_cum = lambda v: bottom + plot_h * max(0.0, v) / cum_peak

        for tick in range(5):
            value = peak * tick / 4
            y = y_at(value)
            drawing.add(Line(left, y, width - right, y,
                             strokeColor=colors.HexColor("#E2E2E2"), strokeWidth=0.5))
            drawing.add(String(left - 5, y - 2, _pdf_num(value / 1_000_000_000, 1),
                               fontName=regular, fontSize=6.5, textAnchor="end",
                               fillColor=colors.HexColor("#777777")))

        # Свод складывает счета очередей, а даты раскрытия у них разные: в
        # месяц первой выборки ПФ второй очереди на линии стоит почти только
        # эскроу ПЕРВОЙ, и одной площадью это читается как «выборка сразу
        # покрыта» (владелец, 04.09.2026). Отчёт носят в банк, и расходиться
        # с экраном ему нельзя — здесь те же слои.
        # Число слоёв — по САМОЙ длинной строке, а не по первой: в первом
        # месяце счёт может быть ещё не у всех очередей, и слой пропал бы
        # молча вместе с очередью.
        parts = list(range(max((len(row.get("escrow_by_phase") or []) for row in data),
                               default=0)))
        if len(parts) > 1:
            for layer in range(len(parts)):
                def _below(row: dict[str, Any], k: int = layer) -> float:
                    return sum(float(v or 0.0)
                               for v in (row.get("escrow_by_phase") or [])[:k])

                def _upto(row: dict[str, Any], k: int = layer) -> float:
                    values = row.get("escrow_by_phase") or []
                    return _below(row, k) + float((values[k] if k < len(values) else 0.0) or 0.0)

                band = [(x_at(i), y_at(_upto(row))) for i, row in enumerate(data)]
                band += [(x_at(i), y_at(_below(data[i]))) for i in reversed(range(len(data)))]
                drawing.add(Polygon([c for point in band for c in point],
                                    fillColor=colors.HexColor("#2D6A4F"),
                                    fillOpacity=0.14 + 0.10 * layer,
                                    strokeColor=colors.HexColor("#2D6A4F"), strokeWidth=0.4))
            layer_names = [str(x) for x in (cover.get("phase_names") or [])][:len(parts)]
            drawing.add(String(left + 4, bottom + plot_h - 8,
                               "эскроу — слоями по очередям, снизу вверх"
                               + (": " + " · ".join(layer_names)
                                  if len(layer_names) == len(parts) else ""),
                               fontName=regular, fontSize=6.4,
                               fillColor=colors.HexColor("#2D6A4F")))
        else:
            escrow_area = [(x_at(0), y_at(0))]
            for index, row in enumerate(data):
                escrow_area.append((x_at(index), y_at(escrow_of(row))))
            escrow_area.append((x_at(len(data) - 1), y_at(0)))
            drawing.add(Polygon([c for point in escrow_area for c in point],
                                fillColor=colors.HexColor("#2D6A4F"), fillOpacity=0.30,
                                strokeColor=None))

        run: list[int] = []

        def flush() -> None:
            if len(run) > 1:
                points = [(x_at(i), y_at(duty(data[i]))) for i in run]
                points += [(x_at(i), y_at(escrow_of(data[i]))) for i in reversed(run)]
                drawing.add(Polygon([c for point in points for c in point],
                                    fillColor=colors.HexColor("#A35D00"),
                                    fillOpacity=0.18, strokeColor=None))
            run.clear()

        for index, row in enumerate(data):
            if duty(row) - escrow_of(row) > 0:
                run.append(index)
            else:
                flush()
        flush()

        def polyline(value, colour: str, w: float, dash=None) -> None:
            points = [(x_at(i), y_at(value(row))) for i, row in enumerate(data)]
            line = PolyLine([c for point in points for c in point],
                            strokeColor=colors.HexColor(colour), strokeWidth=w,
                            fillColor=None)
            if dash:
                line.strokeDashArray = dash
            drawing.add(line)

        polyline(duty, "#A35D00", 1.8)
        polyline(lambda row: float(row.get("pf_balance", 0.0) or 0.0), "#A35D00", 0.8, [2, 2])
        polyline(escrow_of, "#2D6A4F", 1.4)
        # Раскрытие эскроу и продажи после ввода — разные события, и одной
        # линией они врут: ступенька читалась как «после ввода продали на
        # столько», хотя продаж в этот месяц нет — это деньги предыдущих лет,
        # снятые со счетов разом.
        def cum_polyline(key: str, w: float, dash=None, opacity: float = 1.0) -> None:
            if not any(cum_of(row, key) > 0 for row in data):
                return
            points = [(x_at(i), y_cum(cum_of(row, key))) for i, row in enumerate(data)]
            line = PolyLine([c for point in points for c in point],
                            strokeColor=colors.HexColor("#1B5E77"), strokeWidth=w,
                            fillColor=None)
            if dash:
                line.strokeDashArray = dash
            if opacity < 1.0:
                line.strokeOpacity = opacity
            drawing.add(line)

        cum_polyline("escrow_released_cumulative", 1.4, [4, 3])
        cum_polyline("sales_after_rve_cumulative", 1.0, None, 0.55)
        for tick in range(5):
            value = cum_peak * tick / 4
            drawing.add(String(width - right + 4, y_cum(value) - 2,
                               _pdf_num(value / 1_000_000_000, 1), fontName=regular,
                               fontSize=6.5, textAnchor="start",
                               fillColor=colors.HexColor("#1B5E77")))

        rve = str(cover.get("rve") or "")[:7]
        for index, row in enumerate(data):
            if str(row.get("month") or "")[:7] == rve:
                drawing.add(Line(x_at(index), bottom, x_at(index), bottom + plot_h,
                                 strokeColor=colors.HexColor("#666666"), strokeWidth=0.6,
                                 strokeDashArray=[2, 2]))
                drawing.add(String(x_at(index) - 4, bottom + plot_h - 8, "раскрытие эскроу",
                                   fontName=regular, fontSize=6.2, textAnchor="end",
                                   fillColor=colors.HexColor("#555555")))
                break

        # Остаток — из свода движка, а не из последней нарисованной точки:
        # рисуются только месяцы с долгом или счётом, и у погасившейся очереди
        # последняя из них лежит до погашения.
        ending = float(cover.get("ending_unpaid", 0.0) or 0.0)
        if ending > 1_000_000:
            drawing.add(Circle(x_at(len(data) - 1), y_at(ending), 1.8,
                               fillColor=colors.HexColor("#A35D00"), strokeColor=None))
            drawing.add(String(x_at(len(data) - 1) - 4, y_at(ending) + 17,
                               "не погашено " + _pdf_money(ending), fontName=regular,
                               fontSize=6.4, textAnchor="end",
                               fillColor=colors.HexColor("#A35D00")))

        x, y_legend = left, height - 7
        for text, colour, style in _ESCROW_CHART_LEGEND:
            step = 22 + stringWidth(text, regular, 6.4)
            if x > left and x + step > width - 42:
                x, y_legend = left, y_legend - 10
            if style in ("area", "band"):
                mark = Rect(x, y_legend - 3, 12, 6,
                            fillColor=colors.HexColor(colour),
                            fillOpacity=0.45 if style == "area" else 0.25,
                            strokeColor=None)
            else:
                mark = Line(x, y_legend, x + 12, y_legend,
                            strokeColor=colors.HexColor(colour),
                            strokeWidth=1.0 if style == "thin" else 2.0)
                if style == "dash4":
                    mark.strokeDashArray = [3, 2]
                elif style == "dash6":
                    mark.strokeDashArray = [4, 3]
                if style == "thin":
                    mark.strokeOpacity = 0.55
            drawing.add(mark)
            drawing.add(String(x + 16, y_legend - 3, text, fontName=regular, fontSize=6.4,
                               fillColor=colors.HexColor("#444444")))
            x += step
        # Две оси — две подписи: без них правая колонка чисел читается как
        # продолжение левой.
        axis_y = bottom + plot_h + 3
        drawing.add(String(left, axis_y, "долг и эскроу, млрд ₽", fontName=regular,
                           fontSize=6.4, textAnchor="start",
                           fillColor=colors.HexColor("#777777")))
        drawing.add(String(width - 2, axis_y, "накопленным итогом, млрд ₽", fontName=regular,
                           fontSize=6.4, textAnchor="end",
                           fillColor=colors.HexColor("#1B5E77")))
        for index in sorted(set([0, len(data) // 2, len(data) - 1])):
            drawing.add(String(x_at(index), 5, chart_month(data[index].get("month")),
                               fontName=regular, fontSize=6.4, textAnchor="middle",
                               fillColor=colors.HexColor("#777777")))
        return drawing

    def escrow_cover_block(rows: list[dict[str, Any]], cover: dict[str, Any],
                           title: str, heading=None) -> list[Any]:
        chart = escrow_cover_chart(rows, cover)
        lines = [P(line, small) for line in (cover.get("lines") or [])]
        if not chart and not lines:
            return []
        return [P(title, heading or h2)] + ([chart] if chart else []) + lines

    escrow_cover = financing.get("escrow_cover") or {}
    block = escrow_cover_block(timeline_rows, escrow_cover,
                               "Эскроу против обязательств по ПФ")
    if block:
        story.append(KeepTogether(block))

    # По очередям — своим блоком: дата раскрытия у каждой своя, и свод на
    # вопрос «какой очереди не хватило» не отвечает.
    phase_rows = {str(item.get("name") or ""): (((item.get("result") or {}).get("finance") or {}).get("rows") or [])
                  for item in (payload.get("phases") or [])}
    for cover in (financing.get("escrow_cover_phases") or []):
        name = str(cover.get("label") or "Очередь")
        block = escrow_cover_block(phase_rows.get(name) or [], cover, name, h2)
        if block:
            story.append(KeepTogether(block))

    rate_chart=line_chart(
        timeline_rows,
        [
            {"label":"Ключевая ставка","key":"key_rate","factor":100,"color":"#777777"},
            {"label":"БРИДЖ","key":"bridge_rate","factor":100,"color":"#171717","active":lambda row:float(row.get("bridge_balance",0) or 0)>0},
            {"label":"Фактическая ПФ","key":"pf_rate","factor":100,"color":"#A35D00","active":lambda row:float(row.get("pf_balance",0) or 0)>0},
        ],
        "%",
        height=128,
    )
    if rate_chart:
        story.append(KeepTogether([P("Ставки финансирования",h2),rate_chart]))
    if _layout and not _layout.get("project_finance", True):
        # Банковского блока у проекта без ДДУ нет: печатать нули БРИДЖа,
        # ПФ и эскроу значило бы называть их «посчитанными и пустыми».
        del story[_financing_start:]
        story.append(_PdfSection("financing"))
        story.append(P("Финансирование", h2))
        _hotel_finance = ((report.get("object_report") or {}).get("hotel")
                          and _object_sections.get("finance"))
        if _hotel_finance:
            # Гостиница — свой кредит и своё правило капитала; блоки раздела
            # те же, что на странице (`hotel_object_report`).
            story.append(P("Банк ПФ гостиницу не кредитует: стройку и общие затраты "
                           "финансирует кредит гостиницы на долю затрат, остальное — "
                           "собственный капитал. Пока кредит не погашен, свободный поток "
                           "после процентов и налога гасит долг, собственнику — после "
                           "погашения.", small))
            _object_pdf_blocks(story, _hotel_finance, inputs, P, table, small,
                               KeepTogether, Spacer, mm)
        else:
            story.append(P("Проект без продаж по ДДУ: БРИДЖа, проектного финансирования и "
                           "эскроу нет. Стройку и общие затраты финансирует кредит объекта "
                           "на долю стоимости, остальное — собственный капитал.", small))
    # Кредит объектов вне ДДУ — в разделе «Финансирование», той же таблицей
    # движка (`nonres_financing_report`), что на экране: условия, выборка,
    # платёж, баллон, погашение и обслуживание по годам. Прежде раздел у
    # нежилого проекта был пуст, а таблица стояла среди продуктов.
    if report.get("nonres_financing"):
        loan_chart = line_chart(
            timeline_rows,
            [{"label": "Кредит объектов — остаток", "key": "nonres_loan_balance",
              "factor": 1/1_000_000_000, "color": "#171717",
              # Месяц погашения (остаток 0) тоже точка: без него линия
              # обрывалась на последнем остатке, и долг выглядел непогашенным.
              "active": lambda row: (float(row.get("nonres_loan_balance", 0) or 0) > 0
                                     or float(row.get("nonres_loan_repayment", 0) or 0) > 0)}],
            "млрд ₽",
            height=118,
        )
        if loan_chart:
            story.append(KeepTogether([P("Кредит объектов — остаток долга", h2), loan_chart]))
    for _nf in report.get("nonres_financing") or []:
        _years_cols = _nf.get("columns") or []
        _nf_rows = [["Финансирование объекта: " + str(_nf.get("title") or ""), " "]]
        for _row in _nf.get("rows") or []:
            _nf_rows.append([str(_row.get("label") or "").upper()
                             if _row.get("unit") == "section" else str(_row.get("label") or ""),
                             _pdf_nonres_value(_row)])
        # Длинная таблица переносится со строкой заголовка, а не прыгает
        # целиком на следующую страницу, оставляя раздел пустым.
        story.append(table(_nf_rows, [112*mm, 58*mm], font_size=7.6))
        _parts = []
        if _nf.get("years") and _years_cols:
            _yrows = [[str(c[1]) for c in _years_cols]]
            for _y in _nf["years"]:
                _yrows.append([str(_y.get(c[0])) if c[2] == "text"
                               else _pdf_nonres_value({"unit": c[2], "value": _y.get(c[0])})
                               for c in _years_cols])
            _parts.append(P("Обслуживание кредита по годам", small))
            _parts.append(table(_yrows, [14*mm] + [26*mm] * (len(_years_cols) - 1), font_size=6.8))
        if _parts:
            story.append(KeepTogether(_parts))
    # Собственное участие — та же таблица, что на экране
    # (`equity_participation_report`): вложения, возврат, результат, по годам.
    _eq = report.get("equity_participation") or {}
    if _eq.get("rows"):
        story.append(P("Собственное участие", h2))
        _eq_rows = [["Показатель", "Значение"]]
        for _row in _eq["rows"]:
            _eq_rows.append([str(_row.get("label") or "").upper()
                             if _row.get("unit") == "section" else str(_row.get("label") or ""),
                             _pdf_nonres_value(_row)])
        story.append(table(_eq_rows, [112*mm, 58*mm], font_size=7.6))
        _cols = _eq.get("columns") or []
        if _eq.get("years") and _cols:
            _yrows = [[str(c[1]) for c in _cols]]
            for _y in _eq["years"]:
                _yrows.append([str(_y.get(c[0])) if c[2] == "text"
                               else _pdf_nonres_value({"unit": c[2], "value": _y.get(c[0])})
                               for c in _cols])
            story.append(KeepTogether([P("Собственный капитал по годам", small),
                                       table(_yrows, [16*mm] + [38*mm] * (len(_cols) - 1),
                                             font_size=6.8)]))

    story.append(_PdfSection("income"))
    pace_chart=sales_bar_chart(timeline_rows,height=104)
    if pace_chart:
        story.append(KeepTogether([P("Месячный темп продаж",h2),pace_chart]))

    # Тот же темп в штуках квартир: денежный график прячет и рост цены, и
    # изменение нарезки — по нему не видно, сколько квартир уходит в месяц.
    apartment_pace_rows = (report.get("apartment_sales") or {}).get("rows") or []
    units_chart=sales_bar_chart(apartment_pace_rows,height=104,key="units",
                                factor=1.0,unit_label="квартир/мес.",digits=0)
    if units_chart:
        story.append(KeepTogether([P("Месячный темп продаж квартир, шт.",h2),units_chart]))

    story.append(_PdfSection("calendar"))
    events=calendar_data.get('events') or []
    if events:
        gantt_pages=gantt_drawings(events)
        for page_index,gantt in enumerate(gantt_pages):
            story.append(PageBreak())
            _cal_title = str((_object_sections.get("calendar") or {}).get("title")
                             or "Календарный план проекта")
            story.append(P(_cal_title if page_index==0 else _cal_title+" · продолжение",h2))
            story.append(gantt)
        story.append(Spacer(1,2*mm))
        story.append(P("Полосы построены по фактическим датам модели; ромбами отмечены ключевые вехи. При включённой очередности этапы каждой очереди показаны отдельными строками.",small))
    if _object_sections:
        _object_pdf_sections(story, _object_sections, inputs, P, table, h2, small, normal,
                             KeepTogether, Spacer, mm, sensitivity_done=bool(
                                 sensitivity and (sensitivity.get("items") or [])))
    story.append(_PdfSection("footer"))
    story.extend([Spacer(1,4*mm),P("Отчёт сформирован автоматически DevelopAid на основании текущих вводных модели. Перед инвестиционным решением требуется проверка исходных данных, юридических предпосылок и условий кредитования.",small)])

    def footer(canvas,doc_obj):
        canvas.saveState();canvas.setFont(regular,7);canvas.setFillColor(colors.HexColor('#777777'));canvas.drawString(14*mm,8*mm,'DevelopAid · Девелоперская инвестиционная модель');canvas.drawRightString(A4[0]-14*mm,8*mm,f'Стр. {doc_obj.page}');canvas.restoreState()
    # Разбор проекта, а не история правок: что за участок → что на нём выходит
    # → на чём считали → сколько стоит → сколько приносит → чем финансируется
    # → чем рискуем → когда.
    story = _pdf_ordered_story(story, _pdf_section_order(_object_sections), PageBreak)
    doc.build(story,onFirstPage=footer,onLaterPages=footer)
    return buf.getvalue()


